INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93555, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "出于是因为心里有某个想法，才去做那件事。", "primary_collocate": null, "pronunciation": "chū yú", "ipa": "ʈʂʰu˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "他出于好心，才帮了那个人。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我出于关心，问了她几句。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出于好奇，孩子打开了那个盒子。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出于礼貌，一直听他说完。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师出于关心才批评他。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我出于喜欢，买了这本书。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出于害怕，什么也没说。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈出于担心，给我打了三次电话。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我出于一片好意，才告诉你这件事。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出于同情，把钱给了老人。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "出于+心理感受或想法（好心、关心、好奇），引出做某事的内心动机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d775a5-892d-44cd-bef3-8500762883a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93555, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出于", "is_correct": true, "explanation": "目标词，chū yú，意思是因为心里的想法或感受而去做某事。"}, {"text": "处于", "is_correct": false, "explanation": "chǔ（第三声）与 chū（第一声）声调不同，意思是处在某种状态或位置。"}, {"text": "厨余", "is_correct": false, "explanation": "chú（第二声）与 chū（第一声）声调不同，意思是厨房里剩下的食物。"}, {"text": "出游", "is_correct": false, "explanation": "yóu 与 yú 韵母不同，声调相同，意思是外出游览。"}, {"text": "初遇", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是第一次相遇。"}], "explanations": {"出于": "目标词，chū yú，意思是因为心里的想法或感受而去做某事。", "处于": "chǔ（第三声）与 chū（第一声）声调不同，意思是处在某种状态或位置。", "厨余": "chú（第二声）与 chū（第一声）声调不同，意思是厨房里剩下的食物。", "出游": "yóu 与 yú 韵母不同，声调相同，意思是外出游览。", "初遇": "yù（第四声）与 yú（第二声）声调不同，意思是第一次相遇。"}, "sentence_index": null, "correct_answer": "出于"}, "level_3": {"options": [{"text": "出于", "is_correct": true, "explanation": "正确。出于引出做事的内心动机，“好心”符合语境。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”引出行为的目的，“好心”是心理状态，不能作为目的，句子说不通。"}, {"text": "趁", "is_correct": false, "explanation": "“趁”后接时机或机会，不能接“好心”作依据，句子不通。"}, {"text": "对", "is_correct": false, "explanation": "配价：“对”引出行为的对象，不能直接带“好心”作为动机，句子不通。"}], "explanations": {"出于": "正确。出于引出做事的内心动机，“好心”符合语境。", "为了": "语义：“为了”引出行为的目的，“好心”是心理状态，不能作为目的，句子说不通。", "趁": "“趁”后接时机或机会，不能接“好心”作依据，句子不通。", "对": "配价：“对”引出行为的对象，不能直接带“好心”作为动机，句子不通。"}, "sentence_index": 0, "correct_answer": "出于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出于下雨，比赛取消了。", "explanation": "这里应该用〈因为〉。“出于”的动机义要求心里有某个想法，下雨是客观情况，不能当作动机。（“出于”表示由于时要带“原因”一类名词，如“出于安全原因”。）"}, {"text": "他出于赶上末班车，一路跑到了车站。", "explanation": "这里应该用〈为了〉。“出于”后面要接心里的想法或考虑（如“关心、好意”），“赶上末班车”是要达到的目标，表示目的要用为了。"}, {"text": "出于他跑得快，所以赢了比赛。", "explanation": "这里应该用〈因为〉。“出于”后面要接心里的想法或考虑，“他跑得快”是客观情况，不能作动机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93555, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "出于", "is_correct": true, "explanation": "目标词，chū yú，意思是因为心里的想法或感受而去做某事。"}, {"text": "趋于", "is_correct": false, "explanation": "qū 与 chū 声母不同（q 与 ch），声调相同，意思是趋向、朝某方向发展。"}, {"text": "出狱", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是从监狱里放出来。"}, {"text": "雏鱼", "is_correct": false, "explanation": "chú（第二声）与 chū（第一声）声调不同，意思是刚孵出的小鱼。"}, {"text": "书鱼", "is_correct": false, "explanation": "shū 与 chū 声母不同（sh 与 ch），声调相同，意思是蛀书的小虫。"}], "explanations": {"出于": "目标词，chū yú，意思是因为心里的想法或感受而去做某事。", "趋于": "qū 与 chū 声母不同（q 与 ch），声调相同，意思是趋向、朝某方向发展。", "出狱": "yù（第四声）与 yú（第二声）声调不同，意思是从监狱里放出来。", "雏鱼": "chú（第二声）与 chū（第一声）声调不同，意思是刚孵出的小鱼。", "书鱼": "shū 与 chū 声母不同（sh 与 ch），声调相同，意思是蛀书的小虫。"}, "sentence_index": null, "correct_answer": "出于"}, "level_3": {"options": [{"text": "出于", "is_correct": true, "explanation": "正确。出于引出做事的内心动机，“害怕”符合语境。"}, {"text": "向", "is_correct": false, "explanation": "配价：“向”后要接说话或行动的对象，不能接“害怕”，句子不通。"}, {"text": "按", "is_correct": false, "explanation": "搭配：“按”后接规定或标准，不说“按害怕”。"}, {"text": "沿", "is_correct": false, "explanation": "语义：“沿”表示沿着某条路线，“害怕”不是路线，句子说不通。"}], "explanations": {"出于": "正确。出于引出做事的内心动机，“害怕”符合语境。", "向": "配价：“向”后要接说话或行动的对象，不能接“害怕”，句子不通。", "按": "搭配：“按”后接规定或标准，不说“按害怕”。", "沿": "语义：“沿”表示沿着某条路线，“害怕”不是路线，句子说不通。"}, "sentence_index": 6, "correct_answer": "出于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出于这件事，我没有意见。", "explanation": "这里应该用〈对于〉。出于后面要带动机或考虑，“这件事”只是话题，不能用出于引出。"}, {"text": "出于这个问题，我们再讨论一下。", "explanation": "这里应该用〈关于〉。出于表示动机，不能用来引出讨论的话题。"}, {"text": "出于他很高兴，请我们吃了饭。", "explanation": "这里应该用〈因为〉。“出于”后面要接动机或考虑的名词，“他很高兴”是完整句子，不能用出于引出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她出于了担心，没有告诉我。", "corrected_sentence": "她出于担心，没有告诉我。", "error_description": "体标错误：“出于”是介词，后面不能加“了”。应去掉“了”，改为“出于担心”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他出于的礼貌，没有当场反驳。", "corrected_sentence": "他出于礼貌，没有当场反驳。", "error_description": "错误在于“出于”后面直接加了“的”。“出于”是介词，后面接名词时不能加“的”，应说“出于礼貌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
