INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93556, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "由于；基于某种客观原因或考虑。", "primary_collocate": null, "pronunciation": "chū yú", "ipa": "ʈʂʰu˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "出于安全考虑，这里不能玩火。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出于工作需要，他经常出差。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出于健康原因，医生不让他喝酒。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出于时间的考虑，我们明天再谈。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出于对孩子的考虑，他们搬了家。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出于对天气的考虑，比赛改到了下周。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校出于安全原因，关了那扇门。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出于工作的原因，我要常常用电脑。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出于价格考虑，我没有买那件衣服。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出于经费原因，学校暂时停了这个项目。", "target_word": "出于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "出于+原因或考虑（安全、工作、健康），表示依据的理由", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d775a5-892d-44cd-bef3-8500762883a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93556, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出于", "is_correct": true, "explanation": "目标词，chū yú，意思是由于某种原因或考虑。"}, {"text": "处于", "is_correct": false, "explanation": "chǔ（第三声）与 chū（第一声）声调不同，意思是处在某种状态或位置。"}, {"text": "厨余", "is_correct": false, "explanation": "chú（第二声）与 chū（第一声）声调不同，意思是厨房里剩下的食物。"}, {"text": "初遇", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是第一次相遇。"}, {"text": "趋于", "is_correct": false, "explanation": "qū 与 chū 声母不同（q 与 ch），声调相同，意思是趋向、朝某方向发展。"}], "explanations": {"出于": "目标词，chū yú，意思是由于某种原因或考虑。", "处于": "chǔ（第三声）与 chū（第一声）声调不同，意思是处在某种状态或位置。", "厨余": "chú（第二声）与 chū（第一声）声调不同，意思是厨房里剩下的食物。", "初遇": "yù（第四声）与 yú（第二声）声调不同，意思是第一次相遇。", "趋于": "qū 与 chū 声母不同（q 与 ch），声调相同，意思是趋向、朝某方向发展。"}, "sentence_index": null, "correct_answer": "出于"}, "level_3": {"options": [{"text": "出于", "is_correct": true, "explanation": "正确。出于引出理由或考虑，“安全考虑”符合语境。"}, {"text": "趁", "is_correct": false, "explanation": "“趁”后接时机或机会，不能接“安全考虑”，句子不通。"}, {"text": "按", "is_correct": false, "explanation": "搭配：“按”后接规定或标准，不说“按安全考虑”。"}, {"text": "替", "is_correct": false, "explanation": "“替”后接替代的人，“安全”不是人，“替安全考虑”不通。"}], "explanations": {"出于": "正确。出于引出理由或考虑，“安全考虑”符合语境。", "趁": "“趁”后接时机或机会，不能接“安全考虑”，句子不通。", "按": "搭配：“按”后接规定或标准，不说“按安全考虑”。", "替": "“替”后接替代的人，“安全”不是人，“替安全考虑”不通。"}, "sentence_index": 0, "correct_answer": "出于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他出于考上好大学，每天学习到深夜。", "explanation": "这里应该用〈为了〉。“出于”后面要接心里的想法或考虑，“考上好大学”是要达到的目标，表示目的要用为了。"}, {"text": "出于他很有钱，所以买了一辆车。", "explanation": "这里应该用〈因为〉。“出于”后面要接原因或考虑的名词，“他很有钱”是客观情况的陈述，不能用出于引出。"}, {"text": "出于这件事，我很清楚。", "explanation": "这里应该用〈对于〉。出于要带理由或考虑，“这件事”只是话题，不能用出于引出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93556, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "出于", "is_correct": true, "explanation": "目标词，chū yú，意思是由于某种原因或考虑。"}, {"text": "处于", "is_correct": false, "explanation": "chǔ（第三声）与 chū（第一声）声调不同，意思是处在某种状态或位置。"}, {"text": "出游", "is_correct": false, "explanation": "yóu 与 yú 韵母不同，声调相同，意思是外出游览。"}, {"text": "居于", "is_correct": false, "explanation": "jū 与 chū 声母不同（j 与 ch），声调相同，意思是位于、处在。"}, {"text": "厨余", "is_correct": false, "explanation": "chú（第二声）与 chū（第一声）声调不同，意思是厨房里剩下的食物。"}], "explanations": {"出于": "目标词，chū yú，意思是由于某种原因或考虑。", "处于": "chǔ（第三声）与 chū（第一声）声调不同，意思是处在某种状态或位置。", "出游": "yóu 与 yú 韵母不同，声调相同，意思是外出游览。", "居于": "jū 与 chū 声母不同（j 与 ch），声调相同，意思是位于、处在。", "厨余": "chú（第二声）与 chū（第一声）声调不同，意思是厨房里剩下的食物。"}, "sentence_index": null, "correct_answer": "出于"}, "level_3": {"options": [{"text": "出于", "is_correct": true, "explanation": "正确。出于引出理由，“安全原因”符合语境。"}, {"text": "趁", "is_correct": false, "explanation": "“趁”后接时机或机会，不能接“安全原因”作依据，句子不通。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：“按照”后接规定或标准，“按照安全原因”不通。"}, {"text": "向", "is_correct": false, "explanation": "配价：“向”后接对象，不能带“原因”作为宾语，句子不通。"}], "explanations": {"出于": "正确。出于引出理由，“安全原因”符合语境。", "趁": "“趁”后接时机或机会，不能接“安全原因”作依据，句子不通。", "按照": "搭配：“按照”后接规定或标准，“按照安全原因”不通。", "向": "配价：“向”后接对象，不能带“原因”作为宾语，句子不通。"}, "sentence_index": 6, "correct_answer": "出于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出于他的帮助，我完成了作业。", "explanation": "这里应该用〈凭借〉。出于表示动机或理由，不表示凭借的手段；“他的帮助”是手段，要用凭借。"}, {"text": "出于天气预报，明天会下雨。", "explanation": "这里应该用〈根据〉。出于引出的是理由或动机，天气预报是依据，要用根据。"}, {"text": "出于这件事，我们需要再讨论一下。", "explanation": "这里应该用〈关于〉。出于不能用来引出讨论的话题，“这件事”只是话题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "出于的成本考虑，我们取消了这个计划。", "corrected_sentence": "出于成本考虑，我们取消了这个计划。", "error_description": "错误在于“出于”后面直接加了“的”。“出于”是介词，后面接名词时不能加“的”，应说“出于成本考虑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出于了场地限制，活动改到了室内。", "corrected_sentence": "出于场地限制，活动改到了室内。", "error_description": "错误在于“出于”后面加了“了”。“出于”是介词，不能带“了”，应说“出于场地限制”，“了”只用在“改到了室内”中。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93557, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解散", "is_correct": true, "explanation": "解散指把队伍散开，与“成军”（把人聚成队伍）意思相反。"}, {"text": "集合", "is_correct": false, "explanation": "“集合”指人聚拢到一处，与“成军”意思相近而不相反，不是反义词。"}, {"text": "生长", "is_correct": false, "explanation": "“生长”指植物或生物长大，与“成军”的意思无关，不是反义词。"}, {"text": "出发", "is_correct": false, "explanation": "“出发”指动身前往某处，与“成军”的意思不相反，不是反义词。"}], "correct_answer": "解散", "explanations": {"解散": "解散指把队伍散开，与“成军”（把人聚成队伍）意思相反。", "集合": "“集合”指人聚拢到一处，与“成军”意思相近而不相反，不是反义词。", "生长": "“生长”指植物或生物长大，与“成军”的意思无关，不是反义词。", "出发": "“出发”指动身前往某处，与“成军”的意思不相反，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93557, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解散", "is_correct": true, "explanation": "解散指把队伍散开，与“成军”（把人聚成队伍）意思相反。"}, {"text": "组建", "is_correct": false, "explanation": "“组建”与“成军”意思相近，是近义词而非反义词。"}, {"text": "整合", "is_correct": false, "explanation": "“整合”指把分散的东西组织成一个整体，与“成军”不相反，不是反义词。"}, {"text": "出版", "is_correct": false, "explanation": "“出版”指印刷发行，与“成军”的意思无关，不是反义词。"}], "correct_answer": "解散", "explanations": {"解散": "解散指把队伍散开，与“成军”（把人聚成队伍）意思相反。", "组建": "“组建”与“成军”意思相近，是近义词而非反义词。", "整合": "“整合”指把分散的东西组织成一个整体，与“成军”不相反，不是反义词。", "出版": "“出版”指印刷发行，与“成军”的意思无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93557, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "成军是把人聚在一起，成立一支队伍。", "primary_collocate": null, "pronunciation": "chéng jūn", "ipa": "ʈʂʰɤŋ³⁵ tɕyn⁵⁵", "syllable_count": 2, "sentences": [{"text": "我们打算下个月成军。", "target_word": "成军", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想找几个朋友组一支球队，早点成军。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支足球队去年夏天成军。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一起努力，球队终于成军了。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，只要有十个人就可以成军。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们三个人太少，还不能成军。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的篮球队什么时候成军？", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了参加比赛，同学们很快就成军了。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个乐队刚成军，还没有名字。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们几个爱跑步的人想成军，一起参加比赛。", "target_word": "成军", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成军了", "label": "体标"}, {"form": "成軍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把人聚在一起成立一支队伍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06f273b2-8ada-4e9a-bf00-a5ca09e322b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93557, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成军", "is_correct": true, "explanation": "成军指把人聚在一起组成一支队伍，与“我们打算下个月”相符。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨不是人能事先打算去做的事，“我们打算下个月下雨”不通。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病不是可以列入计划的行为，与“打算”的语义冲突。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”只用于植物，不能用于由人组成的队伍。"}], "explanations": {"成军": "成军指把人聚在一起组成一支队伍，与“我们打算下个月”相符。", "下雨": "语义：下雨不是人能事先打算去做的事，“我们打算下个月下雨”不通。", "生病": "语义：生病不是可以列入计划的行为，与“打算”的语义冲突。", "发芽": "搭配：“发芽”只用于植物，不能用于由人组成的队伍。"}, "sentence_index": 0, "correct_answer": "成军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个协会去年成军，有两百名会员。", "explanation": "“成军”指把人组成一支队伍，协会、机构的成立要用〈成立〉。"}, {"text": "这家餐厅开业三年，已经成军了。", "explanation": "“成军”专指人组成队伍，餐厅的开张不能说成军；这里应该用〈开张〉。"}, {"text": "他一个人就成军了。", "explanation": "“成军”需要多人组成队伍，一个人不能“成军”；这里应该用〈组队〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成军", "is_correct": true, "explanation": "成军指组成队伍，“学校的篮球队什么时候”后接此词正合语境。"}, {"text": "打雷", "is_correct": false, "explanation": "语义：打雷是自然现象，球队不能“打雷”，句子不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：球队是团体，不能结婚，与句子主语语义冲突。"}, {"text": "开花", "is_correct": false, "explanation": "语义：开花指植物绽放，比喻时指成果显现，与“成军”（组成队伍）无关，句子不通。"}], "explanations": {"成军": "成军指组成队伍，“学校的篮球队什么时候”后接此词正合语境。", "打雷": "语义：打雷是自然现象，球队不能“打雷”，句子不通。", "结婚": "语义：球队是团体，不能结婚，与句子主语语义冲突。", "开花": "语义：开花指植物绽放，比喻时指成果显现，与“成军”（组成队伍）无关，句子不通。"}, "sentence_index": 6, "correct_answer": "成军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这群小鸭子在池塘边成军了。", "explanation": "“成军”只用于人组成的队伍，小鸭子之类动物应说〈聚在一起〉。"}, {"text": "那座山上的树木都成军了。", "explanation": "“成军”只用于人组成的队伍，树木应说〈生长〉。"}, {"text": "这些书架成军了，整整齐齐地放在墙边。", "explanation": "“成军”只用于人组成的队伍，书架是物品，应说〈摆放〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支乐队上个月成军着。", "corrected_sentence": "这支乐队上个月成军了。", "error_description": "体标用错：“成军”表示动作的完成，不能用“着”（表示持续状态），应用“了”，写作“上个月成军了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新的舞蹈队下周就要成军着。", "corrected_sentence": "新的舞蹈队下周就要成军。", "error_description": "“成军”后不能加“着”；“下周就要”已表示将来，应去掉“着”，写作“下周就要成军”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93558, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解散", "is_correct": true, "explanation": "解散指把队伍散开，与“成军”（组成队伍）意思相反。"}, {"text": "出生", "is_correct": false, "explanation": "“出生”指人或动物来到世上，与“成军”的意思无关，不是反义词。"}, {"text": "开学", "is_correct": false, "explanation": "“开学”指学校开始上课，与“成军”的意思不相反，不是反义词。"}, {"text": "合唱", "is_correct": false, "explanation": "合唱指多人一起唱歌，与团体有关，但与“成军”并非近义，也不是反义词。"}], "correct_answer": "解散", "explanations": {"解散": "解散指把队伍散开，与“成军”（组成队伍）意思相反。", "出生": "“出生”指人或动物来到世上，与“成军”的意思无关，不是反义词。", "开学": "“开学”指学校开始上课，与“成军”的意思不相反，不是反义词。", "合唱": "合唱指多人一起唱歌，与团体有关，但与“成军”并非近义，也不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93558, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解散", "is_correct": true, "explanation": "解散指把队伍散开，与“成军”（组成队伍）意思相反。"}, {"text": "组建", "is_correct": false, "explanation": "“组建”与“成军”意思相近，是近义词而非反义词。"}, {"text": "整合", "is_correct": false, "explanation": "“整合”指把分散的东西组织成整体，与“成军”不相反，不是反义词。"}, {"text": "出版", "is_correct": false, "explanation": "“出版”指印刷发行，与“成军”的意思无关，不是反义词。"}], "correct_answer": "解散", "explanations": {"解散": "解散指把队伍散开，与“成军”（组成队伍）意思相反。", "组建": "“组建”与“成军”意思相近，是近义词而非反义词。", "整合": "“整合”指把分散的东西组织成整体，与“成军”不相反，不是反义词。", "出版": "“出版”指印刷发行，与“成军”的意思无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93558, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "组成军队或队伍；（运动队等）成立。", "primary_collocate": null, "pronunciation": "chéng jūn", "ipa": "ʈʂʰɤŋ³⁵ tɕyn⁵⁵", "syllable_count": 2, "sentences": [{"text": "这支队伍是三年前成军的。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的篮球队今年九月成军。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市的足球队成军已经一百年了。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支部队在战争开始前成军。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乐队成军以后，第一场演出很成功。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的电竞队明年春天成军。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家队成军后，马上开始训练。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支女子排球队刚成军就拿了冠军。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说那支军队在一九四九年成军。", "target_word": "成军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队成军时只有八个队员，现在有三十个。", "target_word": "成军", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成军了", "label": "体标"}, {"form": "成軍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "军队或运动队等正式组成、成立", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06f273b2-8ada-4e9a-bf00-a5ca09e322b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成军", "is_correct": true, "explanation": "成军指组成队伍，“这支队伍是三年前”后接此词，表示队伍成立的时间。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨不是队伍成立的方式，“这支队伍是三年前下雨的”不通。"}, {"text": "生病", "is_correct": false, "explanation": "语义：队伍不能生病，与句子主语语义冲突。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”只用于植物，不能用于队伍。"}], "explanations": {"成军": "成军指组成队伍，“这支队伍是三年前”后接此词，表示队伍成立的时间。", "下雨": "语义：下雨不是队伍成立的方式，“这支队伍是三年前下雨的”不通。", "生病": "语义：队伍不能生病，与句子主语语义冲突。", "发芽": "搭配：“发芽”只用于植物，不能用于队伍。"}, "sentence_index": 0, "correct_answer": "成军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所大学是三年前成军的，有两万名学生。", "explanation": "“成军”只用于军队或队伍，大学的成立要用〈成立〉。"}, {"text": "这本杂志去年成军，每月出一期。", "explanation": "“成军”只用于军队或队伍，杂志的创办要用〈创刊〉。"}, {"text": "这群小狗昨天成军了，正在草地上玩。", "explanation": "“成军”只用于人组成的军队或队伍，小狗之类动物应说〈聚在一起〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成军", "is_correct": true, "explanation": "成军指组成军队或队伍，“国家队”后接此词，表示组建完成。"}, {"text": "开幕", "is_correct": false, "explanation": "语义：开幕指活动开始，不能表示组队，“国家队开幕后”语义不通。"}, {"text": "入睡", "is_correct": false, "explanation": "语义：国家队是团体，不能入睡，与句子语义冲突。"}, {"text": "收割", "is_correct": false, "explanation": "语义：收割指割取成熟的庄稼，与“国家队”的组建无关，句子不通。"}], "explanations": {"成军": "成军指组成军队或队伍，“国家队”后接此词，表示组建完成。", "开幕": "语义：开幕指活动开始，不能表示组队，“国家队开幕后”语义不通。", "入睡": "语义：国家队是团体，不能入睡，与句子语义冲突。", "收割": "语义：收割指割取成熟的庄稼，与“国家队”的组建无关，句子不通。"}, "sentence_index": 6, "correct_answer": "成军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一个人就能成军，不用找别人。", "explanation": "“成军”需要多人组成队伍，一个人不能“成军”；这里应该用〈组队〉。"}, {"text": "这场比赛昨天成军，观众很多。", "explanation": "“成军”指组成队伍，比赛的开始要用〈开赛〉。"}, {"text": "这台电脑是昨天成军的，运行很快。", "explanation": "“成军”只用于军队或队伍，电脑的装配要用〈组装〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支舞蹈队是去年冬天成军了的。", "corrected_sentence": "这支舞蹈队是去年冬天成军的。", "error_description": "“是……的”结构中的动词后不能加“了”，应写作“成军的”；“成军了的”是“了”的误用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支合唱团今年春天把成军了。", "corrected_sentence": "这支合唱团今年春天成军了。", "error_description": "“成军”是不及物动词，不能用“把”字结构，“把”应删除，写作“成军了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93559, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最终", "is_correct": true, "explanation": "反义：“初步”指刚开始、未最后完成，“最终”指最后确定的，二者相对。"}, {"text": "美好", "is_correct": false, "explanation": "无关：“美好”形容事物的好，与“初步”没有反义关系。"}, {"text": "严格", "is_correct": false, "explanation": "无关：“严格”形容要求或态度，与“初步”没有对立关系。"}, {"text": "陌生", "is_correct": false, "explanation": "无关：“陌生”指不熟悉，与“初步”描述的阶段或程度没有反义关系。"}], "correct_answer": "最终", "explanations": {"最终": "反义：“初步”指刚开始、未最后完成，“最终”指最后确定的，二者相对。", "美好": "无关：“美好”形容事物的好，与“初步”没有反义关系。", "严格": "无关：“严格”形容要求或态度，与“初步”没有对立关系。", "陌生": "无关：“陌生”指不熟悉，与“初步”描述的阶段或程度没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93559, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "完善", "is_correct": true, "explanation": "反义：“初步方案”指尚未完善的方案，“完善”与之相对，指已经完备的状态。"}, {"text": "美观", "is_correct": false, "explanation": "无关：“美观”指外形好看，与“初步”没有反义关系。"}, {"text": "陈旧", "is_correct": false, "explanation": "无关：“陈旧”指时间久、不新鲜，与“初步”的阶段义没有对立关系。"}, {"text": "重要", "is_correct": false, "explanation": "无关：“重要”指作用大，与“初步”没有反义关系。"}], "correct_answer": "完善", "explanations": {"完善": "反义：“初步方案”指尚未完善的方案，“完善”与之相对，指已经完备的状态。", "美观": "无关：“美观”指外形好看，与“初步”没有反义关系。", "陈旧": "无关：“陈旧”指时间久、不新鲜，与“初步”的阶段义没有对立关系。", "重要": "无关：“重要”指作用大，与“初步”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93559, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "初步是刚刚开始的，还不是最后完成的。", "primary_collocate": null, "pronunciation": "chū bù", "ipa": "ʈʂʰu˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "这是我们的初步方案。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初步结果明天就出来了。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是我的初步想法，还要再改。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个城市有了初步印象。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份初步计划还不完整。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生先做了初步检查，还要等报告。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是初步的名单，最后还会改。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初步成绩已经出来了，但不是最后的。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看了我的初步设计，说还要修改。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个初步方案太简单，请再补充细节。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做定语，指刚开始、尚未最后完成的方案、结果、想法等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5996816f-6ae7-41cc-8154-694bc816de42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93559, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初步", "is_correct": true, "explanation": "正确答案。“初步方案”指尚未最后完成的方案，修饰名词“方案”。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：“沙哑”形容嗓音，不能修饰“方案”，“我们的沙哑方案”说不通。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或物的体形，不能修饰“方案”这样的抽象事物。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”表示情绪，不能描述“方案”，与“我们的…方案”的说法不符。"}], "explanations": {"初步": "正确答案。“初步方案”指尚未最后完成的方案，修饰名词“方案”。", "沙哑": "语义：“沙哑”形容嗓音，不能修饰“方案”，“我们的沙哑方案”说不通。", "胖": "体貌：“胖”形容人或物的体形，不能修饰“方案”这样的抽象事物。", "悲伤": "语义：“悲伤”表示情绪，不能描述“方案”，与“我们的…方案”的说法不符。"}, "sentence_index": 0, "correct_answer": "初步"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份方案很初步，可以直接用。", "explanation": "这里应该用〈完整〉。“可以直接用”说明方案已经完成，与“初步”（尚未最后完成）矛盾，应说“完整”。"}, {"text": "他很初步，做事总是不成熟。", "explanation": "这里应该用〈幼稚〉。“初步”描述事情的开始阶段，不能用来形容人的性格，形容人要用“幼稚”。"}, {"text": "这件衣服非常初步。", "explanation": "这里应该用〈完美〉。“初步”表示尚未完成，衣服是成品，不能用“初步”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93559, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初步", "is_correct": true, "explanation": "正确答案。“初步的名单”指尚未定稿的名单，与“最后还会改”的语境相符。"}, {"text": "最终", "is_correct": false, "explanation": "语义：“最终”表示定稿，与后半句“最后还会改”相矛盾。"}, {"text": "完整", "is_correct": false, "explanation": "语义：“完整”表示已经齐全，与“只是”和“还会改”的语境不合。"}, {"text": "精美", "is_correct": false, "explanation": "搭配：“精美”多用来修饰工艺品或印刷品，不用来修饰“名单”。"}], "explanations": {"初步": "正确答案。“初步的名单”指尚未定稿的名单，与“最后还会改”的语境相符。", "最终": "语义：“最终”表示定稿，与后半句“最后还会改”相矛盾。", "完整": "语义：“完整”表示已经齐全，与“只是”和“还会改”的语境不合。", "精美": "搭配：“精美”多用来修饰工艺品或印刷品，不用来修饰“名单”。"}, "sentence_index": 6, "correct_answer": "初步"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我初步三十岁了，还没结婚。", "explanation": "这里应该用〈已经〉。“初步”表示尚在开始阶段，与三十岁的年龄矛盾；说年龄已经到某岁要用“已经”。"}, {"text": "他初步死了，大家都很难过。", "explanation": "这里应该用〈去世〉。“初步”表示刚开始，不能用来说人的死亡这种彻底结束，要说“去世”。"}, {"text": "这顿饭我初步吃了整整一个小时。", "explanation": "这里应该用〈一直〉。“初步”指刚开始的阶段，与“整整一个小时”的持续时间矛盾，要说“一直”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93559, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写了一份很初步报告。", "corrected_sentence": "他写了一份初步报告。", "error_description": "错误形式是“很初步报告”，在“初步”前加了程度副词“很”。“初步”作定语修饰名词时不能受“很”修饰，应直接说“一份初步报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93559, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们提出了一个很初步建议。", "corrected_sentence": "他们提出了一个初步建议。", "error_description": "错误：“初步”直接作定语修饰名词时，前面不能加“很”。正确：去掉“很”，说“一个初步建议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93560, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "彻底", "is_correct": true, "explanation": "反义：“初步解决”指只解决了一部分，“彻底解决”与之相对，指完全解决。"}, {"text": "慢慢", "is_correct": false, "explanation": "无关：“慢慢”描述动作的速度，与“初步”的程度义没有反义关系。"}, {"text": "悄悄", "is_correct": false, "explanation": "无关：“悄悄”描述动作的方式，与“初步”没有对立关系。"}, {"text": "偶尔", "is_correct": false, "explanation": "无关：“偶尔”表示频率，与“初步”没有反义关系。"}], "correct_answer": "彻底", "explanations": {"彻底": "反义：“初步解决”指只解决了一部分，“彻底解决”与之相对，指完全解决。", "慢慢": "无关：“慢慢”描述动作的速度，与“初步”的程度义没有反义关系。", "悄悄": "无关：“悄悄”描述动作的方式，与“初步”没有对立关系。", "偶尔": "无关：“偶尔”表示频率，与“初步”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93560, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "彻底", "is_correct": true, "explanation": "反义：“初步稳定”指只是暂时稳定，“彻底稳定”与之相对，指完全稳定。"}, {"text": "仔细", "is_correct": false, "explanation": "无关：“仔细”描述做事的认真程度，与“初步”没有反义关系。"}, {"text": "匆忙", "is_correct": false, "explanation": "无关：“匆忙”描述速度，与“初步”没有对立关系。"}, {"text": "随意", "is_correct": false, "explanation": "无关：“随意”指不拘束，与“初步”的程度义没有反义关系。"}], "correct_answer": "彻底", "explanations": {"彻底": "反义：“初步稳定”指只是暂时稳定，“彻底稳定”与之相对，指完全稳定。", "仔细": "无关：“仔细”描述做事的认真程度，与“初步”没有反义关系。", "匆忙": "无关：“匆忙”描述速度，与“初步”没有对立关系。", "随意": "无关：“随意”指不拘束，与“初步”的程度义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93560, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "开始阶段的；尚不完善或不最终的。", "primary_collocate": null, "pronunciation": "chū bù", "ipa": "ʈʂʰu˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "我对这个公司只有初步了解。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理初步确定了开会时间，还没告诉大家。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察初步判断，这不是意外。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题我们已经初步解决了。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他初步学会了用电脑，还不太熟。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作初步完成，明天再检查一遍。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家初步认为，原因是天气太冷。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们初步选了三个地方，下周再决定。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划已初步做好，请你提意见。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的情况初步稳定了，但还要观察。", "target_word": "初步", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做状语，修饰动作，表示处在开始阶段、还不完善", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5996816f-6ae7-41cc-8154-694bc816de42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初步", "is_correct": true, "explanation": "正确答案。“初步了解”指只有开始阶段的了解，与“只有”的限定语气相符。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”表示完全，与“只有”的限定语气相矛盾。"}, {"text": "大量", "is_correct": false, "explanation": "搭配：“大量”修饰数量，不能直接修饰“了解”。"}, {"text": "无限", "is_correct": false, "explanation": "语义：“无限”表示没有界限，与“只有”的限定意思相反，句意不通。"}], "explanations": {"初步": "正确答案。“初步了解”指只有开始阶段的了解，与“只有”的限定语气相符。", "全部": "语义：“全部”表示完全，与“只有”的限定语气相矛盾。", "大量": "搭配：“大量”修饰数量，不能直接修饰“了解”。", "无限": "语义：“无限”表示没有界限，与“只有”的限定意思相反，句意不通。"}, "sentence_index": 0, "correct_answer": "初步"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山初步很高，要爬两天。", "explanation": "这里应该删去〈初步〉。“初步”指开始阶段，不能修饰山的高度这类固有属性，直接说“这座山很高”即可。"}, {"text": "他初步忘记了那件事。", "explanation": "这里应该用〈彻底〉。“忘记”是一次性完成的结果，不能用“初步”来限定程度。"}, {"text": "这些书初步卖完了。", "explanation": "这里应该用〈全部〉。“卖完”表示全部售出，与“初步”的未完成义相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初步", "is_correct": true, "explanation": "正确答案。“专家初步认为”表示初步的判断，与后半句“原因是天气太冷”相符。"}, {"text": "吃着", "is_correct": false, "explanation": "语义：“吃着”与“认为”不能同时进行，句意不通。"}, {"text": "睡着", "is_correct": false, "explanation": "语义：“睡着”与“认为”是互不相容的动作，句意不通。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：“大声认为”不是常见搭配，“认为”一般不用“大声”修饰。"}], "explanations": {"初步": "正确答案。“专家初步认为”表示初步的判断，与后半句“原因是天气太冷”相符。", "吃着": "语义：“吃着”与“认为”不能同时进行，句意不通。", "睡着": "语义：“睡着”与“认为”是互不相容的动作，句意不通。", "大声": "搭配：“大声认为”不是常见搭配，“认为”一般不用“大声”修饰。"}, "sentence_index": 6, "correct_answer": "初步"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天初步下雨了，大家都跑回家。", "explanation": "这里应该用〈突然〉。“初步”不能描述下雨这种突然发生的变化，要说“突然下雨”。"}, {"text": "他初步就到。", "explanation": "这里应该用〈马上〉。“初步”不表示时间即将发生，表示很快要做某事要用“马上”。"}, {"text": "我初步认识他十年了。", "explanation": "这里应该用〈已经〉。“十年”是很长的时间，与“初步”的开始阶段义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们很初步讨论了方案。", "corrected_sentence": "我们初步讨论了方案。", "error_description": "错误形式是“很初步讨论”，在作状语的“初步”前加了“很”。“初步”表示“处在开始阶段”，不能受程度副词“很”修饰，应说“初步讨论”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生非常初步检查了病人。", "corrected_sentence": "医生初步检查了病人。", "error_description": "错误：作状语的“初步”不能受程度副词“非常”修饰。正确：去掉“非常”，说“医生初步检查了病人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
