INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93561, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "战机是打仗用的飞机。", "primary_collocate": null, "pronunciation": "zhàn jī", "ipa": "tʂan˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "打仗的时候，战机很重要。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架战机是红色的。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一架老战机。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在看天上的战机。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战机需要很多油才能飞。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员开着战机回到了基地。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战机不是客机，不能坐很多人。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国庆那天，战机在广场上空表演。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想长大后开战机。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战机落在了长长的跑道上。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "架", "label": "量词"}, {"form": "戰機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "打仗时使用的飞机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781e042f-01c8-4179-94a7-75f6a8a36a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93561, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "战机", "is_correct": true, "explanation": "战机（zhàn jī）：打仗时使用的飞机。"}, {"text": "战绩", "is_correct": false, "explanation": "战绩（zhàn jì）：第二个音节声调不同，jì 为第四声，jī 为第一声。意思是比赛或工作的成绩。"}, {"text": "站姿", "is_correct": false, "explanation": "站姿（zhàn zī）：第二个音节声母不同，zī 与 jī 只有声母 z/j 的区别。意思是站立的姿势。"}, {"text": "战技", "is_correct": false, "explanation": "战技（zhàn jì）：第二个音节声调不同，jì 为第四声。意思是作战的技术。"}], "explanations": {"战机": "战机（zhàn jī）：打仗时使用的飞机。", "战绩": "战绩（zhàn jì）：第二个音节声调不同，jì 为第四声，jī 为第一声。意思是比赛或工作的成绩。", "站姿": "站姿（zhàn zī）：第二个音节声母不同，zī 与 jī 只有声母 z/j 的区别。意思是站立的姿势。", "战技": "战技（zhàn jì）：第二个音节声调不同，jì 为第四声。意思是作战的技术。"}, "sentence_index": null, "correct_answer": "战机"}, "level_3": {"options": [{"text": "战机", "is_correct": true, "explanation": "战机：打仗时使用的飞机，句意合理。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具与打仗无关，这句话说打仗时它很重要，句意不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，打仗时并不重要。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不是物品，句意不通。"}], "explanations": {"战机": "战机：打仗时使用的飞机，句意合理。", "玩具": "语义：玩具与打仗无关，这句话说打仗时它很重要，句意不通。", "钢琴": "语义：钢琴是乐器，打仗时并不重要。", "春天": "语义：春天是季节，不是物品，句意不通。"}, "sentence_index": 0, "correct_answer": "战机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春节期间，我们全家坐战机回老家。", "explanation": "这里应该用〈客机〉。战机用于作战，不搭载家人长途出行；载客出行要用客机。"}, {"text": "消防员坐战机到山上去救人。", "explanation": "这里应该用〈直升机〉。山区救援通常用直升机，战机是作战用的飞机。"}, {"text": "宇航员坐战机进入了太空。", "explanation": "这里应该用〈火箭〉。战机靠空气飞行，不能把人送进太空。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93561, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战机", "is_correct": true, "explanation": "战机：属于交通工具中的飞机，但不是客机，句意成立。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是交通工具，不能坐人。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的，不能坐很多人。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“坐”的对象应是交通工具，公园不能“坐很多人”。"}], "explanations": {"战机": "战机：属于交通工具中的飞机，但不是客机，句意成立。", "冰箱": "语义：冰箱不是交通工具，不能坐人。", "书包": "语义：书包是装东西的，不能坐很多人。", "公园": "搭配：“坐”的对象应是交通工具，公园不能“坐很多人”。"}, "sentence_index": 6, "correct_answer": "战机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天开这架战机送孩子上学。", "explanation": "这里应该用〈汽车〉。战机用于作战，不是接送孩子的交通工具；接送孩子要开汽车。"}, {"text": "这架战机在田里翻土。", "explanation": "这里应该用〈拖拉机〉。战机用于作战，不用来耕地；翻地要用拖拉机。"}, {"text": "这架战机装满了货物，飞往南方。", "explanation": "这里应该用〈货机〉。战机用于作战，不装运货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93561, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "基地里停着一辆战机。", "corrected_sentence": "基地里停着一架战机。", "error_description": "量词错误：飞机类的量词应为“架”，不能用“辆”（“辆”多用于车）。正确说法：一架战机。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93561, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "基地里有两战机。", "corrected_sentence": "基地里有两架战机。", "error_description": "数量结构错误：“两”后面要加量词，应说“两架战机”，不能省去“架”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
