INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93562, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用于作战的飞机。", "primary_collocate": null, "pronunciation": "zhàn jī", "ipa": "tʂan˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "一架战机从海上飞过来了。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战机正在天空中飞行。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空军有很多新战机。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员坐上了战机。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些战机明天要去北方。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战机的速度比火车快得多。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在机场检查战机。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候最喜欢看战机的照片。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两架战机在云上慢慢地飞着。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战机起飞以后，天空很安静。", "target_word": "战机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "架", "label": "量词"}, {"form": "戰機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "军事用途的作战飞机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781e042f-01c8-4179-94a7-75f6a8a36a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93562, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "战机", "is_correct": true, "explanation": "战机（zhàn jī）：用于作战的飞机。"}, {"text": "战绩", "is_correct": false, "explanation": "战绩（zhàn jì）：第二个音节声调不同，jì 为第四声，jī 为第一声。意思是比赛或工作的成绩。"}, {"text": "站姿", "is_correct": false, "explanation": "站姿（zhàn zī）：第二个音节声母不同，zī 与 jī 只有声母 z/j 的区别。意思是站立的姿势。"}, {"text": "战技", "is_correct": false, "explanation": "战技（zhàn jì）：第二个音节声调不同，jì 为第四声。意思是作战的技术。"}], "explanations": {"战机": "战机（zhàn jī）：用于作战的飞机。", "战绩": "战绩（zhàn jì）：第二个音节声调不同，jì 为第四声，jī 为第一声。意思是比赛或工作的成绩。", "站姿": "站姿（zhàn zī）：第二个音节声母不同，zī 与 jī 只有声母 z/j 的区别。意思是站立的姿势。", "战技": "战技（zhàn jì）：第二个音节声调不同，jì 为第四声。意思是作战的技术。"}, "sentence_index": null, "correct_answer": "战机"}, "level_3": {"options": [{"text": "战机", "is_correct": true, "explanation": "战机：用于作战的飞机，量词“架”，符合句意。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不能从海上飞过来。"}, {"text": "梯子", "is_correct": false, "explanation": "语义：梯子靠人搬动，不会自己飞过来。"}, {"text": "风车", "is_correct": false, "explanation": "搭配：风车说“转”，不说“飞过来”。"}], "explanations": {"战机": "战机：用于作战的飞机，量词“架”，符合句意。", "钢琴": "语义：钢琴是乐器，不能从海上飞过来。", "梯子": "语义：梯子靠人搬动，不会自己飞过来。", "风车": "搭配：风车说“转”，不说“飞过来”。"}, "sentence_index": 0, "correct_answer": "战机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们全家坐战机去海边玩。", "explanation": "这里应该用〈汽车〉。战机用于作战，不搭载家人出游；全家去海边玩可以坐汽车。"}, {"text": "我每天开战机去菜市场买菜。", "explanation": "这里应该用〈汽车〉。战机是用于作战的飞机，不是日常出行的交通工具；去菜市场要开汽车。"}, {"text": "这架战机每天把乘客从北京送到上海。", "explanation": "这里应该用〈客机〉。战机用于作战，不运送乘客；载客航线要用客机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战机", "is_correct": true, "explanation": "战机：工人在机场检查的对象是飞机，句意合理。"}, {"text": "考卷", "is_correct": false, "explanation": "语义：考卷是纸质试题，工人不会在机场检查考卷。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历属于医院，与机场工人的检查工作不搭。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，工人不会在机场检查沙发。"}], "explanations": {"战机": "战机：工人在机场检查的对象是飞机，句意合理。", "考卷": "语义：考卷是纸质试题，工人不会在机场检查考卷。", "病历": "语义：病历属于医院，与机场工人的检查工作不搭。", "沙发": "语义：沙发是家具，工人不会在机场检查沙发。"}, "sentence_index": 6, "correct_answer": "战机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位宇航员乘坐这架战机进入了太空。", "explanation": "这里应该用〈火箭〉。战机用于空中作战，不能把人送进太空；载人进入太空要用火箭。"}, {"text": "这架战机把病人紧急送往医院。", "explanation": "这里应该用〈救护车〉。战机用于作战，不运送病人；紧急送医要用救护车。"}, {"text": "这架战机赶到火场喷水灭火。", "explanation": "这里应该用〈消防飞机〉。战机用于作战，不用来喷水灭火；空中灭火要用消防飞机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们看到一个战机在天上飞。", "corrected_sentence": "我们看到一架战机在天上飞。", "error_description": "量词错误：飞机类的量词应为“架”，不能用“个”。正确说法：一架战机。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "训练场上的战机们都排成一排。", "corrected_sentence": "训练场上的战机都排成一排。", "error_description": "“们”不能用于战机这类非人的事物，应去掉“们”，说“战机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93563, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "给予", "is_correct": true, "explanation": "给予与剥夺意思相反，指把机会交给别人。"}, {"text": "享受", "is_correct": false, "explanation": "享受指自己得到乐趣，与剥夺并不构成反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "完成指做成某件事，与剥夺没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫指清除脏东西，与剥夺没有反义关系。"}], "correct_answer": "给予", "explanations": {"给予": "给予与剥夺意思相反，指把机会交给别人。", "享受": "享受指自己得到乐趣，与剥夺并不构成反义关系。", "完成": "完成指做成某件事，与剥夺没有反义关系。", "打扫": "打扫指清除脏东西，与剥夺没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93563, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "给予", "is_correct": true, "explanation": "给予与剥夺意思相反，指把时间或机会交给别人。"}, {"text": "忍受", "is_correct": false, "explanation": "忍受指勉强承受痛苦或困难，与剥夺并不构成反义关系。"}, {"text": "维持", "is_correct": false, "explanation": "维持指保持原状，与剥夺没有反义关系。"}, {"text": "追求", "is_correct": false, "explanation": "追求指努力争取某个目标，与剥夺不是反义关系。"}], "correct_answer": "给予", "explanations": {"给予": "给予与剥夺意思相反，指把时间或机会交给别人。", "忍受": "忍受指勉强承受痛苦或困难，与剥夺并不构成反义关系。", "维持": "维持指保持原状，与剥夺没有反义关系。", "追求": "追求指努力争取某个目标，与剥夺不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93563, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "剥夺是硬把别人的机会或时间拿走。", "primary_collocate": null, "pronunciation": "bō duó", "ipa": "pɔ˥ twɔ˧˥", "syllable_count": 2, "sentences": [{"text": "老师不能剥夺学生上课的机会。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能剥夺我说话的机会。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大人不应该剥夺孩子选择的机会。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个决定剥夺了他比赛的机会。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太多，剥夺了我睡觉的时间。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要剥夺我学习的机会。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈剥夺了弟弟玩手机的机会。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不能剥夺你读书的机会。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她剥夺了同学回答问题的机会。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要剥夺孩子休息的时间。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "剥夺了", "label": "体标"}, {"form": "剥夺过", "label": "体标"}, {"form": "剝奪", "label": "繁体"}], "register": "中性", "sense_fingerprint": "硬把别人的机会或时间拿走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d775a5-892d-44cd-bef3-8500762883a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93563, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剥夺", "is_correct": true, "explanation": "正确。剥夺指硬把别人的机会拿走，符合“不能……机会”的语境。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”后接任务或工作，不说“完成学生上课的机会”。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指自己得到乐趣，与“不能……学生的机会”的语境相悖，句子说不通。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：“品尝”用于味道或滋味，“机会”不能被品尝，句子不通。"}], "explanations": {"剥夺": "正确。剥夺指硬把别人的机会拿走，符合“不能……机会”的语境。", "完成": "搭配：“完成”后接任务或工作，不说“完成学生上课的机会”。", "享受": "语义：“享受”指自己得到乐趣，与“不能……学生的机会”的语境相悖，句子说不通。", "品尝": "语义：“品尝”用于味道或滋味，“机会”不能被品尝，句子不通。"}, "sentence_index": 0, "correct_answer": "剥夺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场大雨剥夺了今天的比赛。", "explanation": "这里应该用〈取消〉。剥夺的对象是别人的权利或机会，比赛是活动，被取消不能说剥夺。"}, {"text": "这次改革剥夺了学生的负担。", "explanation": "这里应该用〈减少〉。“负担”不是可以被夺走的权利或机会，只能说减少。"}, {"text": "他剥夺了沉默，大家都很惊讶。", "explanation": "这里应该用〈打破〉。沉默不是别人拥有的东西，不能被剥夺，只能说打破。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93563, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剥夺", "is_correct": true, "explanation": "正确。剥夺指硬把别人的机会拿走，符合“妈妈……弟弟机会”的语境。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：“挑选”后接东西或人，不说“挑选机会”，句子不通。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指觉得好而赞赏，“机会”不能被欣赏，句子说不通。"}, {"text": "感受", "is_correct": false, "explanation": "搭配：“感受”后接情绪或印象，不说“感受弟弟玩手机的机会”。"}], "explanations": {"剥夺": "正确。剥夺指硬把别人的机会拿走，符合“妈妈……弟弟机会”的语境。", "挑选": "搭配：“挑选”后接东西或人，不说“挑选机会”，句子不通。", "欣赏": "语义：“欣赏”指觉得好而赞赏，“机会”不能被欣赏，句子说不通。", "感受": "搭配：“感受”后接情绪或印象，不说“感受弟弟玩手机的机会”。"}, "sentence_index": 6, "correct_answer": "剥夺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他剥夺了宝贵的时间。", "explanation": "这里应该用〈浪费〉。剥夺指硬把别人的东西拿走，自己白白耗费时间要用浪费。"}, {"text": "这场雨剥夺了比赛的日期。", "explanation": "这里应该用〈推迟〉。日期可以推迟或改期，但不能被剥夺。"}, {"text": "老师剥夺了学生的意见。", "explanation": "这里应该用〈忽视〉。忽视是不重视，不是硬夺走，所以不能说剥夺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93563, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子玩耍的机会被大人把剥夺了。", "corrected_sentence": "孩子玩耍的机会被大人剥夺了。", "error_description": "“被”字句中已有“被”，不能再用“把”。应去掉“把”，改为“孩子玩耍的机会被大人剥夺了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93563, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有剥夺了我的机会。", "corrected_sentence": "他没有剥夺我的机会。", "error_description": "错误在于“没有”否定时，动词后面不能再加“了”，应说“没有剥夺我的机会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
