INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93564, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用强制手段夺去，使失去权利或财物。", "primary_collocate": null, "pronunciation": "bō duó", "ipa": "pɔ˥ twɔ˧˥", "syllable_count": 2, "sentences": [{"text": "法律不允许任何人剥夺别人的自由。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院剥夺了他的权利。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家可以剥夺罪犯的一些权利。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人可以剥夺你说话的权利。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司剥夺了他的发言权。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官剥夺了他开车的资格。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家剥夺了女人投票的权利。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犯了罪，法院剥夺了他的自由。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不能剥夺工人休息的权利。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争剥夺了很多孩子上学的权利。", "target_word": "剥夺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "剥夺了", "label": "体标"}, {"form": "剥夺过", "label": "体标"}, {"form": "剝奪", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用法律或强制手段夺去权利、自由或资格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0d775a5-892d-44cd-bef3-8500762883a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剥夺", "is_correct": true, "explanation": "正确。剥夺指用强制手段夺去别人的权利，符合“法律不允许……”的语境。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指自己得到好处，与“法律不允许任何人……别人的自由”的语境相悖。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”后接任务，不说“完成别人的自由”。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”与“法律不允许任何人……”的语境矛盾，句子在语义上荒谬。"}], "explanations": {"剥夺": "正确。剥夺指用强制手段夺去别人的权利，符合“法律不允许……”的语境。", "享受": "语义：“享受”指自己得到好处，与“法律不允许任何人……别人的自由”的语境相悖。", "完成": "搭配：“完成”后接任务，不说“完成别人的自由”。", "保护": "语义：“保护”与“法律不允许任何人……”的语境矛盾，句子在语义上荒谬。"}, "sentence_index": 0, "correct_answer": "剥夺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司剥夺了工人的损失。", "explanation": "这里应该用〈赔偿〉。剥夺的对象是别人拥有的权利，“损失”不能被夺走，要说赔偿。"}, {"text": "他剥夺了好成绩。", "explanation": "这里应该用〈取得〉。剥夺是夺去别人拥有的东西，自己取得成绩要用取得。"}, {"text": "这项改革剥夺了不公平。", "explanation": "这里应该用〈消除〉。不公平不是可以被夺走的东西，只能说消除。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剥夺", "is_correct": true, "explanation": "正确。剥夺指用强制手段夺去别人的权利，符合“这个国家……女人投票权利”的语境。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赞赏，“权利”不能被欣赏，句子说不通。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：“挑选”后接具体的东西，不说“挑选投票的权利”。"}, {"text": "感受", "is_correct": false, "explanation": "搭配：“感受”后接情绪或感觉，不说“感受女人投票的权利”。"}], "explanations": {"剥夺": "正确。剥夺指用强制手段夺去别人的权利，符合“这个国家……女人投票权利”的语境。", "欣赏": "语义：“欣赏”指赞赏，“权利”不能被欣赏，句子说不通。", "挑选": "搭配：“挑选”后接具体的东西，不说“挑选投票的权利”。", "感受": "搭配：“感受”后接情绪或感觉，不说“感受女人投票的权利”。"}, "sentence_index": 6, "correct_answer": "剥夺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "选民剥夺了投票的权利。", "explanation": "这里应该用〈行使〉。剥夺是夺走别人的权利，权利的拥有者自己使用要用行使。"}, {"text": "他主动剥夺了上诉的权利。", "explanation": "这里应该用〈放弃〉。剥夺是别人用强制手段夺去，自己主动不要某种权利要用放弃。"}, {"text": "学生剥夺了受教育的权利。", "explanation": "这里应该用〈享有〉。剥夺是他人强行夺去，学生自己拥有权利要用享有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "任何人都不能随意把剥夺别人的人身自由。", "corrected_sentence": "任何人都不能随意剥夺别人的人身自由。", "error_description": "“把”字要放在宾语前面，这里“把”直接接动词“剥夺”，位置错误。应去掉“把”，改为“任何人都不能随意剥夺别人的人身自由”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de161b46-baf2-4fe9-b247-beefca44367c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
