INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93565, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手下是听你的话、替你做事的人。", "primary_collocate": null, "pronunciation": "shǒu xià", "ipa": "ʂou˨˩˦ ɕia˥˩", "syllable_count": 2, "sentences": [{"text": "老板让手下去把东西送到客人家。", "target_word": "手下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有很多手下，大家都听他的话。", "target_word": "手下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个老大的手下很听话，从不说不。", "target_word": "手下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我让手下去买早饭了。", "target_word": "手下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他带着两名手下走进了办公室。", "target_word": "手下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理的手下每天都替他打电话。", "target_word": "手下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把工作交给手下，自己去休息了。", "target_word": "手下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很生气，骂了手下一顿。", "target_word": "手下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的手下做事太慢，快催催他们。", "target_word": "手下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的手下都怕他，没有人敢说话。", "target_word": "手下", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "手下人", "label": "复合"}], "register": "口语", "sense_fingerprint": "听从某人吩咐、替他办事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80c6695f-4d15-45b9-91eb-7195eb7df105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93565, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手下", "is_correct": true, "explanation": "手下：替人办事、听人吩咐的人，读 shǒu xià，与听到的读音一致。"}, {"text": "收下", "is_correct": false, "explanation": "shōu（第一声）与 shǒu（第三声）声调不同，意思是收下、接受。"}, {"text": "手写", "is_correct": false, "explanation": "shǒu xiě 与 shǒu xià 韵母、声调不同，意思是用手书写。"}, {"text": "树下", "is_correct": false, "explanation": "shù（第四声）与 shǒu（第三声）韵母、声调不同，意思是树的下面。"}], "explanations": {"手下": "手下：替人办事、听人吩咐的人，读 shǒu xià，与听到的读音一致。", "收下": "shōu（第一声）与 shǒu（第三声）声调不同，意思是收下、接受。", "手写": "shǒu xiě 与 shǒu xià 韵母、声调不同，意思是用手书写。", "树下": "shù（第四声）与 shǒu（第三声）韵母、声调不同，意思是树的下面。"}, "sentence_index": null, "correct_answer": "手下"}, "level_3": {"options": [{"text": "上级", "is_correct": false, "explanation": "语义：“上级”是比老板更高的领导，老板不会让上级去送东西。"}, {"text": "顾客", "is_correct": false, "explanation": "语义：“顾客”是来买东西的人，不会替老板去送东西，句意不通。"}, {"text": "箱子", "is_correct": false, "explanation": "搭配：“让……去”要求能行动的人，“箱子”不能主动去办事。"}, {"text": "手下", "is_correct": true, "explanation": "手下：替老板办事的下属，能被老板派去送东西，与语境相符。"}], "explanations": {"上级": "语义：“上级”是比老板更高的领导，老板不会让上级去送东西。", "顾客": "语义：“顾客”是来买东西的人，不会替老板去送东西，句意不通。", "箱子": "搭配：“让……去”要求能行动的人，“箱子”不能主动去办事。", "手下": "手下：替老板办事的下属，能被老板派去送东西，与语境相符。"}, "sentence_index": 0, "correct_answer": "手下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我是这家公司的手下，负责管理所有员工。", "explanation": "这里应该用〈领导〉（指管理者）。“手下”指听从别人指挥、替人做事的人，与“负责管理所有员工”的身份相反。"}, {"text": "他终于下定决心，手下去做这件事。", "explanation": "这里应该用〈下手〉（动手、开始做）。“手下”指听从别人指挥的人，不能表示开始动手去做事情。"}, {"text": "他是我的手下，我每天都要听他的安排。", "explanation": "这里应该用〈上司〉（指管理我的人）。“手下”指听我指挥、替我做事的人，与“我要听他的安排”相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93565, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对手", "is_correct": false, "explanation": "语义：“对手”是竞争的一方，老板不会把工作交给对手。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：“敌人”是对立的一方，不会接受工作，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“交给”的对象要能承接任务，“窗户”不能接受工作。"}, {"text": "手下", "is_correct": true, "explanation": "手下：接受老板安排的下属，能承接工作，与语境相符。"}], "explanations": {"对手": "语义：“对手”是竞争的一方，老板不会把工作交给对手。", "敌人": "语义：“敌人”是对立的一方，不会接受工作，句意不通。", "窗户": "搭配：“交给”的对象要能承接任务，“窗户”不能接受工作。", "手下": "手下：接受老板安排的下属，能承接工作，与语境相符。"}, "sentence_index": 6, "correct_answer": "手下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子是我的手下，每天替我开门关门。", "explanation": "这里应该用〈员工〉（指人）。“手下”指听从指挥的人，不能用来指椅子。"}, {"text": "我的手下是公司的老板，我做什么都要听他的。", "explanation": "这里应该用〈上司〉（指管理我的人）。“手下”指听我指挥的人，不能指我要服从的老板。"}, {"text": "我的手下是我的老师，每天教我做饭。", "explanation": "这里应该用〈师傅〉（指教我的人）。“手下”指在工作中听我指挥的人，不指教我的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93565, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理身边有一只手下，专门负责整理文件。", "corrected_sentence": "经理身边有一名手下，专门负责整理文件。", "error_description": "量词错误。“手下”指人，应用量词“名”，不能用指动物或物品的“只”。错误形式：一只手下；正确形式：一名手下。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93565, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理把任务交手下，自己去开会了。", "corrected_sentence": "经理把任务交给手下，自己去开会了。", "error_description": "动词搭配错误：“把任务交给手下”中，“交”后须带“给”引出接受者，不能省略为“交手下”。错误形式：把任务交手下；正确形式：把任务交给手下。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af6b323-532f-447d-ab82-ecad054e84b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
