INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93568, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93568, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "新颖独特的想法或构思。", "primary_collocate": null, "pronunciation": "chuàng yì", "ipa": "tʂʰuaŋ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "这个广告很有创意。", "target_word": "创意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师的创意让大家眼前一亮。", "target_word": "创意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要有创意的年轻人。", "target_word": "创意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的创意来自日常生活。", "target_word": "创意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜单充满了创意。", "target_word": "创意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的创意不一定要花很多钱。", "target_word": "创意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的创意画了出来。", "target_word": "创意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份方案缺少创意，老板不满意。", "target_word": "创意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的创意常常让老师吃惊。", "target_word": "创意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛要看谁的创意更好。", "target_word": "创意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "创意产业", "label": "复合"}], "register": "通用", "sense_fingerprint": "新颖独特的想法或构思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168ad27f-59af-419a-aeff-3d9250db54ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创意", "is_correct": true, "explanation": "创意指新颖独特的想法或构思，“很有创意”说广告有新意。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”说人的轻重，不用于形容广告。"}, {"text": "耳朵", "is_correct": false, "explanation": "语义：“耳朵”是身体器官，广告没有耳朵可以“有”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”说人或生物的岁数，不用于形容广告。"}], "explanations": {"创意": "创意指新颖独特的想法或构思，“很有创意”说广告有新意。", "体重": "体貌：“体重”说人的轻重，不用于形容广告。", "耳朵": "语义：“耳朵”是身体器官，广告没有耳朵可以“有”。", "年龄": "语义：“年龄”说人或生物的岁数，不用于形容广告。"}, "sentence_index": 0, "correct_answer": "创意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次实验取得了很大的创意。", "explanation": "这里应该用〈成果〉。创意是新颖独特的想法，不能说“取得”；实验取得的是成果。"}, {"text": "他对工作的创意很认真。", "explanation": "这里应该用〈态度〉。创意指新颖的想法，不能用“认真”形容；对工作认真是态度。"}, {"text": "他的创意一米八。", "explanation": "这里应该用〈身高〉。创意是抽象的想法，没有高矮之分；人的高度要说“身高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创意", "is_correct": true, "explanation": "创意指新颖独特的想法，可以用画把它表现出来。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：画出来的是图像，歌曲是用来听的，不能说“画出来”。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：工资是领的钱数，不能说“把自己的工资画了出来”。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是一种活动，不是可以用“画”表现的东西。"}], "explanations": {"创意": "创意指新颖独特的想法，可以用画把它表现出来。", "歌曲": "搭配：画出来的是图像，歌曲是用来听的，不能说“画出来”。", "工资": "搭配：工资是领的钱数，不能说“把自己的工资画了出来”。", "考试": "语义：“考试”是一种活动，不是可以用“画”表现的东西。"}, "sentence_index": 6, "correct_answer": "创意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛要看谁的创意更快。", "explanation": "这里应该用〈速度〉。创意是想法，没有快慢之分；比赛比的是“速度”。"}, {"text": "这次比赛要看谁的创意更重。", "explanation": "这里应该用〈体重〉。创意没有轻重之分；比较轻重要说“体重”。"}, {"text": "这次比赛要看谁的创意更标准。", "explanation": "这里应该用〈发音〉。创意是想法，不能说标准不标准；朗读比赛比的是“发音”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一条好创意。", "corrected_sentence": "这是一个好创意。", "error_description": "量词错误：“创意”应用量词“个”，“条”用于细长的东西，如河流、裤子等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们有很多新创意们。", "corrected_sentence": "孩子们有很多新创意。", "error_description": "词尾错误：“创意”是抽象名词，不能加“们”表复数，应说“新创意”；“们”只用于指人的名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
