INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93569, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打制是用锤子敲打，做成一个东西。", "primary_collocate": null, "pronunciation": "dǎ zhì", "ipa": "ta˨˩˦ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "他拿着锤子，慢慢打制一把小刀。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给我打制了一个铁盒子。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个铁门是工人们打制的。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁匠一天能打制三把镰刀。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用铜打制了一只小鸟。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这口铁锅打制得很结实。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅在院子里打制马蹄铁。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想自己打制一把菜刀。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工匠把铁条打制成一把钥匙。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些银器都是老师傅手工打制的。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打制了", "label": "完成体"}, {"form": "打制着", "label": "持续体"}, {"form": "打制过", "label": "经历体"}, {"form": "打制成", "label": "结果补语"}], "register": "书面", "sense_fingerprint": "打制|用锤子敲打做成东西|动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2661f93-1077-4bd1-98fe-0202873548b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93569, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打制", "is_correct": true, "explanation": "“打制”指用锤子敲打做成东西，与“拿着锤子，慢慢……一把小刀”相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用液体，不能“喝一把小刀”。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍”是拍打，不是敲打成型，与做成小刀的意思不符。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”是用气流冲出，与用锤子做刀的动作冲突。"}], "explanations": {"打制": "“打制”指用锤子敲打做成东西，与“拿着锤子，慢慢……一把小刀”相符。", "喝": "语义：“喝”指饮用液体，不能“喝一把小刀”。", "拍": "语义：“拍”是拍打，不是敲打成型，与做成小刀的意思不符。", "吹": "语义：“吹”是用气流冲出，与用锤子做刀的动作冲突。"}, "sentence_index": 0, "correct_answer": "打制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈一天能打制三条围巾。", "explanation": "这里应该用〈织〉。打制是用锤子敲打做成金属器物，围巾要用织。"}, {"text": "农民一天能打制三亩稻子。", "explanation": "这里应该用〈割〉。打制是敲打做成器物，收割稻子要用割。"}, {"text": "面包师一天能打制三百个面包。", "explanation": "这里应该用〈烤〉。打制是敲打锻造的方法，面包要用烤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93569, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打制", "is_correct": true, "explanation": "“打制”指用锤子敲打做成马蹄铁，与“师傅在院子里……马蹄铁”相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发声歌唱，与打制马蹄铁的动作不符。"}, {"text": "栽", "is_correct": false, "explanation": "搭配：“栽”多用于植物，不说在院子里栽马蹄铁。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与用锤子做铁器的意思完全不符。"}], "explanations": {"打制": "“打制”指用锤子敲打做成马蹄铁，与“师傅在院子里……马蹄铁”相符。", "唱": "语义：“唱”是发声歌唱，与打制马蹄铁的动作不符。", "栽": "搭配：“栽”多用于植物，不说在院子里栽马蹄铁。", "吃": "语义：“吃”指进食，与用锤子做铁器的意思完全不符。"}, "sentence_index": 6, "correct_answer": "打制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人打制了很多书。", "explanation": "这里应该用〈印刷〉。打制是敲打做成器物，书籍要用印刷。"}, {"text": "裁缝打制了一个蛋糕。", "explanation": "这里应该用〈烤制〉。打制是敲打锻造的方法，蛋糕要靠烤。"}, {"text": "他打制了屋顶的漏洞。", "explanation": "这里应该用〈修补〉。打制是做出新器物，填补漏洞要用修补。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93569, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸给我打制着过一个铁盒子。", "corrected_sentence": "爸爸给我打制过一个铁盒子。", "error_description": "体标错误：经历体“过”不能与持续体“着”同用，应去掉“着”，说“打制过”。错误：爸爸给我打制着过一个铁盒子。正确：爸爸给我打制过一个铁盒子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93569, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把铁锹打制很牢固。", "corrected_sentence": "这把铁锹打制得很牢固。", "error_description": "补语标记错误：“打制”后描述结果要用“得”，不能直接接形容词。错误：这把铁锹打制很牢固。正确：这把铁锹打制得很牢固。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
