INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93570, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用敲打、锻造的方法制作（器物）。", "primary_collocate": null, "pronunciation": "dǎ zhì", "ipa": "ta˨˩˦ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "老铁匠用铁打制了一把刀。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把铁锤是爷爷亲手打制的。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在店里打制银手镯。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人用石头打制出很多工具。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁匠正在打制一口大锅。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把剪刀是用好铁打制成的。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一块铜打制成了一个小碗。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅打制过很多把好刀。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人用石头打制石斧。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她请银匠为女儿打制一对耳环。", "target_word": "打制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打制了", "label": "完成体"}, {"form": "打制着", "label": "持续体"}, {"form": "打制过", "label": "经历体"}, {"form": "打制成", "label": "结果补语"}], "register": "书面", "sense_fingerprint": "打制|敲打锻造制作器物|动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2661f93-1077-4bd1-98fe-0202873548b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93570, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打制", "is_correct": true, "explanation": "“打制”指用敲打、锻造的方法做成器物，与“用铁……了一把刀”相符。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”一般接布料、衣物，不说用铁缝刀。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”用于线和布料，不能用来表示用铁制作刀具。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”是书写文字，与用铁做成器物的意思不符。"}], "explanations": {"打制": "“打制”指用敲打、锻造的方法做成器物，与“用铁……了一把刀”相符。", "缝": "搭配：“缝”一般接布料、衣物，不说用铁缝刀。", "织": "搭配：“织”用于线和布料，不能用来表示用铁制作刀具。", "写": "语义：“写”是书写文字，与用铁做成器物的意思不符。"}, "sentence_index": 0, "correct_answer": "打制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村里人用竹子打制了很多筷子。", "explanation": "这里应该用〈削〉。竹筷是削出来的，打制是敲打锻造的方法，不能用于竹筷。"}, {"text": "村里的妇女打制了很多汤圆。", "explanation": "这里应该用〈搓〉。打制是敲打锻造的方法，汤圆要靠搓。"}, {"text": "他用纸打制了一只风筝。", "explanation": "这里应该用〈扎〉。打制是敲打锻造的方法，风筝等纸扎制品要用扎，不能说打制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打制", "is_correct": true, "explanation": "“打制”指用敲打锻造的方法做成器物，与“把一块铜……成了一个小碗”相符。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”是用刀斩断，与“打制成小碗”的加工方式不符。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：“剪”多用于布料、纸张，不说把铜剪成碗。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热烹饪，不能把铜煮成器物。"}], "explanations": {"打制": "“打制”指用敲打锻造的方法做成器物，与“把一块铜……成了一个小碗”相符。", "砍": "语义：“砍”是用刀斩断，与“打制成小碗”的加工方式不符。", "剪": "搭配：“剪”多用于布料、纸张，不说把铜剪成碗。", "煮": "语义：“煮”是加热烹饪，不能把铜煮成器物。"}, "sentence_index": 6, "correct_answer": "打制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把坏了的锁打制好了。", "explanation": "这里应该用〈修理〉。打制是做出新器物，修补旧锁要用修理。"}, {"text": "厨师打制了一瓶酱油。", "explanation": "这里应该用〈酿造〉。打制是敲打锻造的方法，酱油要靠发酵酿造，不能说打制。"}, {"text": "妈妈用布打制了一个枕头。", "explanation": "这里应该用〈缝制〉。打制是敲打锻造的方法，布料做成的枕头要用缝制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "铁匠一直打制了着一把新刀。", "corrected_sentence": "铁匠一直打制着一把新刀。", "error_description": "“打制”后同时用了“了”和“着”，两个体标重复。表示持续时只用“着”，应说“打制着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工匠把一块铁打制了一把斧头。", "corrected_sentence": "工匠把一块铁打制成了一把斧头。", "error_description": "“把”字句中“打制”后缺少结果补语“成”。应说“打制成了”，表示加工后变成某物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a8d0d4f-3eb8-4b72-92c8-34e04de74fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
