INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93571, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "因由是事情为什么会这样的原因。", "primary_collocate": null, "pronunciation": "yīn yóu", "ipa": "in˥ joʊ˧˥", "syllable_count": 2, "sentences": [{"text": "他没来开会，一定有他的因由。", "target_word": "因由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先说说这件事的因由。", "target_word": "因由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道他生气的因由。", "target_word": "因由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问了半天，才问清因由。", "target_word": "因由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的因由很简单。", "target_word": "因由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿意说出因由。", "target_word": "因由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想知道出错的因由。", "target_word": "因由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情的因由还没有查清楚。", "target_word": "因由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把迟到的因由写下来。", "target_word": "因由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说明了搬家的因由。", "target_word": "因由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "因由：事情为什么这样的原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4240d01-219b-4bd2-9ad0-703dd789f62b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93571, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因由", "is_correct": true, "explanation": "正确：“因由”指事情的原因，与“一定有他的……”相合。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”指时刻或长度，不能表示没来开会的原因。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”指称呼，与没来开会的原因无关。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”说外形，不能作为没来开会的原因。"}], "explanations": {"因由": "正确：“因由”指事情的原因，与“一定有他的……”相合。", "时间": "语义：“时间”指时刻或长度，不能表示没来开会的原因。", "名字": "语义：“名字”指称呼，与没来开会的原因无关。", "身高": "体貌：“身高”说外形，不能作为没来开会的原因。"}, "sentence_index": 0, "correct_answer": "因由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个木箱是用因由做的。", "explanation": "“因由”只表示原因，不指材料；这里应该用“木材”。"}, {"text": "这个因由跑得很快。", "explanation": "“因由”是抽象的原因，不会跑；这里是把它当成了动物或人。"}, {"text": "他吃了因由。", "explanation": "“因由”是抽象的原因，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93571, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因由", "is_correct": true, "explanation": "正确：“因由”指事情的原因，与“出错的”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能表示出错的原因。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”说身体的重量，与出错的原因无关。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”指称呼，不能表示出错的原因。"}], "explanations": {"因由": "正确：“因由”指事情的原因，与“出错的”相合。", "颜色": "语义：“颜色”不能表示出错的原因。", "体重": "体貌：“体重”说身体的重量，与出错的原因无关。", "名字": "语义：“名字”指称呼，不能表示出错的原因。"}, "sentence_index": 6, "correct_answer": "因由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次因由很红。", "explanation": "“因由”是事情的原因，不能用来形容颜色，这里是把它当成了有颜色的东西。"}, {"text": "他去了因由。", "explanation": "“因由”是事情的原因，不指地方，这里是把它当成了目的地。"}, {"text": "他的因由很甜。", "explanation": "“因由”是事情的原因，不能用来形容味道，这里是把它当成了食物的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93571, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没来上课，一定有他的因由们。", "corrected_sentence": "他没来上课，一定有他的因由。", "error_description": "词形错误：“因由”是抽象名词，不能加“们”表示复数，应说“他的因由”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93571, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说出了一只迟到的因由。", "corrected_sentence": "他说出了一个迟到的因由。", "error_description": "量词错误：“因由”是抽象名词，量词应用“个”，不能用“只”（“只”多用于动物等）。应说“一个迟到的因由”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b431ff-c275-4f98-a714-7a32d5659a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
