INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93573, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扶贫是帮助很穷的人，让他们过上好日子。", "primary_collocate": null, "pronunciation": "fú pín", "ipa": "fu˧˥ pʰin˧˥", "syllable_count": 2, "sentences": [{"text": "政府在山区扶贫已经十年了。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用自己的钱去扶贫。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司派人到农村扶贫。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的老师去山里扶贫了。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家很重视扶贫，想让大家都过上好日子。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扶贫的目的是让穷人过好日子。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大学毕业后，回家乡扶贫。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扶贫要先帮农民找到工作。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老板每年都出钱扶贫。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的人都说，扶贫让他们的生活好多了。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扶贫工作", "label": "复合"}, {"form": "精准扶贫", "label": "复合"}], "register": "通用", "sense_fingerprint": "帮助穷人过上好日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbbcbc0-280a-4f0c-a3f1-46de88612a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93573, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”的主体须是人，政府不能结婚，与句子主语冲突。"}, {"text": "扶贫", "is_correct": true, "explanation": "扶贫：政府在山区帮助贫困人口摆脱贫困，与“已经十年了”的持续义相合。"}, {"text": "减肥", "is_correct": false, "explanation": "语义：“减肥”针对人的体形，政府没有体形可减。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”的动作主体须是人或动物，政府不会在山区睡觉十年。"}], "explanations": {"结婚": "语义：“结婚”的主体须是人，政府不能结婚，与句子主语冲突。", "扶贫": "扶贫：政府在山区帮助贫困人口摆脱贫困，与“已经十年了”的持续义相合。", "减肥": "语义：“减肥”针对人的体形，政府没有体形可减。", "睡觉": "语义：“睡觉”的动作主体须是人或动物，政府不会在山区睡觉十年。"}, "sentence_index": 0, "correct_answer": "扶贫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个村去年靠种茶叶，终于扶贫了。", "explanation": "这里应该用〈脱贫〉。脱贫指贫困者自己摆脱贫困；“扶贫”是别人帮助穷人，不能说村子自己扶贫。"}, {"text": "春节前，工厂扶贫了一批新机器。", "explanation": "这里应该用〈购置〉。买进设备说购置；“扶贫”的对象是人或地区，不用于机器。"}, {"text": "地震后，救援人员扶贫了很多被困的人。", "explanation": "这里应该用〈救助〉。紧急抢救被困者说救助；“扶贫”不用于应急救险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93573, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退休", "is_correct": false, "explanation": "语义：刚大学毕业的人不可能退休，与“大学毕业后”矛盾。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”发生在毕业之前，不能说毕业后回乡出生。"}, {"text": "怀孕", "is_correct": false, "explanation": "语义：“怀孕”是女性的身体状况，句子主语“他”不能怀孕。"}, {"text": "扶贫", "is_correct": true, "explanation": "扶贫：大学毕业后回家乡帮助贫困人口脱贫，语义通顺。"}], "explanations": {"退休": "语义：刚大学毕业的人不可能退休，与“大学毕业后”矛盾。", "出生": "语义：“出生”发生在毕业之前，不能说毕业后回乡出生。", "怀孕": "语义：“怀孕”是女性的身体状况，句子主语“他”不能怀孕。", "扶贫": "扶贫：大学毕业后回家乡帮助贫困人口脱贫，语义通顺。"}, "sentence_index": 6, "correct_answer": "扶贫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要扶贫这片荒地。", "explanation": "这里应该用〈开发〉。开发用于土地和资源；“扶贫”的对象须是贫困的人或地区，不能用于荒地。"}, {"text": "这家企业下个月扶贫一款新饮料。", "explanation": "这里应该用〈推出〉。新产品面世说推出；“扶贫”的对象是贫困的人或地区，不用于产品。"}, {"text": "市里正在扶贫这条污染严重的河。", "explanation": "这里应该用〈治理〉。河流污染要说治理；“扶贫”的对象是人，不用于河流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93573, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "县里的干部明年去农村扶贫了。", "corrected_sentence": "县里的干部明年去农村扶贫。", "error_description": "错误在“扶贫”后的“了”：“明年”指将来，动作尚未发生，不能用“了”，应为“明年去农村扶贫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93573, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家企业明年还要去这个村扶贫过。", "corrected_sentence": "这家企业明年还要去这个村扶贫。", "error_description": "了／过错用：“明年”指将来，“过”表示已有的经历，不能用于将来；应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93574, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93574, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93574, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扶助贫困地区或贫困人口，帮助其摆脱贫困。", "primary_collocate": null, "pronunciation": "fú pín", "ipa": "fu˧˥ pʰin˧˥", "syllable_count": 2, "sentences": [{"text": "政府在贫困地区长期扶贫，成效明显。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县扶贫多年，村民的收入明显提高了。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业到贫困地区扶贫，帮农民发展产业。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家扶贫的目标是让贫困人口摆脱贫困。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在贫困山区扶贫三年，村里变化很大。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些干部每个月都到村里扶贫，看看村民的情况。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学生们利用假期到农村扶贫。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔资金要用于扶贫，不能浪费。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生都在为扶贫奔走。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司通过网上卖货来扶贫。", "target_word": "扶贫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扶贫工作", "label": "复合"}, {"form": "精准扶贫", "label": "复合"}], "register": "正式", "sense_fingerprint": "扶助贫困地区或人口摆脱贫困", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbbcbc0-280a-4f0c-a3f1-46de88612a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撒谎", "is_correct": false, "explanation": "语义：“撒谎”指说假话，政府不会“长期撒谎”换来“成效明显”，搭配不通。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：“吵架”是争执的行为，不能用在“长期……，成效明显”这类做事的语境中。"}, {"text": "扶贫", "is_correct": true, "explanation": "扶贫：政府在贫困地区长期帮助贫困人口脱贫，与“成效明显”相合。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”不是政府的工作方式，“长期哭，成效明显”说不通。"}], "explanations": {"撒谎": "语义：“撒谎”指说假话，政府不会“长期撒谎”换来“成效明显”，搭配不通。", "吵架": "语义：“吵架”是争执的行为，不能用在“长期……，成效明显”这类做事的语境中。", "扶贫": "扶贫：政府在贫困地区长期帮助贫困人口脱贫，与“成效明显”相合。", "哭": "语义：“哭”不是政府的工作方式，“长期哭，成效明显”说不通。"}, "sentence_index": 0, "correct_answer": "扶贫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府扶贫新兴产业的发展。", "explanation": "这里应该用〈扶持〉。扶持指支持产业发展；“扶贫”的对象是贫困地区或贫困人口，不用于产业。"}, {"text": "矿井坍塌后，救援队扶贫了被困的矿工。", "explanation": "这里应该用〈救助〉。紧急抢救被困者说救助；“扶贫”指长期帮助脱贫，不用于应急救险。"}, {"text": "那位农民靠自己的努力终于扶贫了。", "explanation": "这里应该用〈脱贫〉。脱贫指贫困者自己摆脱贫困；“扶贫”是外力帮助，不能用于自己脱贫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退休", "is_correct": false, "explanation": "语义：大学生不可能退休，与“利用假期”的语境不合。"}, {"text": "扶贫", "is_correct": true, "explanation": "扶贫：大学生利用假期到农村帮助贫困人口脱贫，语义通顺。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”不是人能主动完成的动作，与“利用假期”矛盾。"}, {"text": "降落", "is_correct": false, "explanation": "搭配：“降落”多指飞机等落地，不说人降落到农村。"}], "explanations": {"退休": "语义：大学生不可能退休，与“利用假期”的语境不合。", "扶贫": "扶贫：大学生利用假期到农村帮助贫困人口脱贫，语义通顺。", "出生": "语义：“出生”不是人能主动完成的动作，与“利用假期”矛盾。", "降落": "搭配：“降落”多指飞机等落地，不说人降落到农村。"}, "sentence_index": 6, "correct_answer": "扶贫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春节期间，领导去医院扶贫病人。", "explanation": "这里应该用〈慰问〉。看望表示关心要说慰问；“扶贫”指帮助穷人脱贫，不用于看望病人。"}, {"text": "学校扶贫了这次比赛的经费。", "explanation": "这里应该用〈资助〉。资助经费、项目要说资助；“扶贫”的对象是人或贫困地区。"}, {"text": "市里要扶贫这片脏乱的街区。", "explanation": "这里应该用〈整治〉。脏乱的环境、街区要说整治；“扶贫”的对象是贫困的人或地区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位老板以前不到山区扶贫过。", "corrected_sentence": "那位老板以前没到山区扶贫过。", "error_description": "否定词错用：“扶贫过”表示有过的经历，否定经历要用“没”，不能用“不”，应把“不到山区扶贫过”改为“没到山区扶贫过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每个假期都回村里扶贫着。", "corrected_sentence": "她每个假期都回村里扶贫。", "error_description": "体标错用：“每个假期”指经常性的动作，不能用表示持续状态的“着”，应去掉“着”，说“回村里扶贫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93575, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93575, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93575, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国际关系是不同国家之间怎么相处，是朋友还是不和。", "primary_collocate": null, "pronunciation": "guó jì guān xì", "ipa": "kuɔ˧˥ tɕi˥˩ kuan˥ ɕi˥˩", "syllable_count": 4, "sentences": [{"text": "国际关系好的时候，两国来往很多。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在国际关系有点紧张。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际关系就像朋友，有时好，有时不好。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说，国际关系终于变好了。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际关系不好，旅游的人也会变少。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际关系好，两国的人都能安心做生意。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的国际关系需要互相帮助。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，国际关系一直很平静。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国吵架以后，国际关系变得很冷。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得国际关系和朋友关系有点像。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "国际关系学", "label": "复合"}], "register": "中性", "sense_fingerprint": "不同国家之间相处得好不好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa8a7dd2-9f6a-4ef8-b570-0eaeae1a1cd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93575, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际关系", "is_correct": true, "explanation": "国际关系指国家之间的相处状况，关系好的时候两国来往自然多，与句意相符。"}, {"text": "头发", "is_correct": false, "explanation": "语义：头发的好坏与两国之间的来往没有关系，句意说不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机的状况与两国来往多少无关，与句中的语境冲突。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业好的时候”无法引出“两国来往很多”，“作业”不能作为两国来往的前提。"}], "explanations": {"国际关系": "国际关系指国家之间的相处状况，关系好的时候两国来往自然多，与句意相符。", "头发": "语义：头发的好坏与两国之间的来往没有关系，句意说不通。", "手机": "语义：手机的状况与两国来往多少无关，与句中的语境冲突。", "作业": "搭配：“作业好的时候”无法引出“两国来往很多”，“作业”不能作为两国来往的前提。"}, "sentence_index": 0, "correct_answer": "国际关系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和同学的国际关系终于变好了，我们又和好了。", "explanation": "这里应该用〈人际关系〉。国际关系指国家之间的关系，同学之间的关系要用人际关系。"}, {"text": "我和他的国际关系一直很密切，常常一起出去玩。", "explanation": "这里应该用〈交往〉。国际关系指国家之间的相处，两个人之间的往来要用交往。"}, {"text": "我和爸爸的国际关系终于变好了，我们又能好好聊天了。", "explanation": "这里应该用〈感情〉。国际关系用于国家之间，父子之间的情感要用感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93575, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际关系", "is_correct": true, "explanation": "国际关系指国家之间的相处状况，好的国际关系需要双方互相帮助，与句意相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不会需要互相帮助，句意说不通。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“需要互相帮助”的主体应是人或国家，“电视”不能这样搭配。"}, {"text": "雨", "is_correct": false, "explanation": "语义：“雨”是天气现象，不能“互相帮助”，与句意冲突。"}], "explanations": {"国际关系": "国际关系指国家之间的相处状况，好的国际关系需要双方互相帮助，与句意相符。", "桌子": "语义：“桌子”是家具，不会需要互相帮助，句意说不通。", "电视": "搭配：“需要互相帮助”的主体应是人或国家，“电视”不能这样搭配。", "雨": "语义：“雨”是天气现象，不能“互相帮助”，与句意冲突。"}, "sentence_index": 6, "correct_answer": "国际关系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和邻居的国际关系很好，经常互相帮忙。", "explanation": "这里应该用〈邻里关系〉。国际关系指国家之间的关系，邻居之间的关系要用邻里关系。"}, {"text": "我和他的国际关系很深，像亲兄弟一样。", "explanation": "这里应该用〈友谊〉。国际关系用于国家之间，两个人之间的交情要用友谊。"}, {"text": "父母和孩子之间的国际关系很亲密。", "explanation": "这里应该用〈亲子关系〉。国际关系指国家之间的关系，父母与孩子之间的关系要用亲子关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现在国际关系地和谐。", "corrected_sentence": "现在国际关系很和谐。", "error_description": "错误形式：“现在国际关系地和谐”。正确形式：“现在国际关系很和谐”。“和谐”在此作谓语，前面应加程度副词“很”，不能用结构助词“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要国际关系改善好。", "corrected_sentence": "我们要把国际关系改善好。", "error_description": "错误形式：“我们要国际关系改善好”，漏掉了“把”字。正确形式：“我们要把国际关系改善好”。表示处置、使“国际关系”改善好，需要用“把”字结构，把宾语提到动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
