INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家与国家之间在政治、经济、文化等方面的相互关系。", "primary_collocate": null, "pronunciation": "guó jì guān xì", "ipa": "kuɔ˧˥ tɕi˥˩ kuan˥ ɕi˥˩", "syllable_count": 4, "sentences": [{"text": "经济合作能让国际关系更加稳定。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际关系会影响各国的经济。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授研究国际关系三十年了。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争会让国际关系变得紧张。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年来，国际关系发生了很大变化。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文化交流可以改善国际关系。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际关系中，经济和政治都很重要。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想当一名研究国际关系的专家。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际关系的好坏会影响文化交流。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我常看报纸上关于国际关系的新闻。", "target_word": "国际关系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "国际关系学", "label": "复合"}], "register": "书面", "sense_fingerprint": "国家之间在政治、经济、文化等方面的相互关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa8a7dd2-9f6a-4ef8-b570-0eaeae1a1cd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际关系", "is_correct": true, "explanation": "国际关系指国家之间在政治、经济、文化等方面的相互关系，经济合作能使其更稳定，与句意相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，与国家之间的经济合作无关，句意说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，经济合作不会让冰箱“更加稳定”，与句意不合。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景物，与国家之间的经济合作无关。"}], "explanations": {"国际关系": "国际关系指国家之间在政治、经济、文化等方面的相互关系，经济合作能使其更稳定，与句意相符。", "厨房": "语义：厨房是做饭的地方，与国家之间的经济合作无关，句意说不通。", "冰箱": "语义：冰箱是家电，经济合作不会让冰箱“更加稳定”，与句意不合。", "天空": "语义：天空是自然景物，与国家之间的经济合作无关。"}, "sentence_index": 0, "correct_answer": "国际关系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的国际关系很好，大家经常一起出去玩。", "explanation": "这里应该用〈人际关系〉。国际关系指国家与国家之间的关系，同学之间的关系要用人际关系。"}, {"text": "我和室友的国际关系一直很融洽。", "explanation": "这里应该用〈相处〉。国际关系只指国家之间的关系，室友之间的关系说“相处”更自然。"}, {"text": "我们两个人的国际关系很深，像亲兄弟一样。", "explanation": "这里应该用〈友谊〉。国际关系用于国家之间，两个人之间的情谊要用友谊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际关系", "is_correct": true, "explanation": "国际关系指国家之间的相互关系，经济和政治都是其中的重要内容，与句意相符。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：“饮食”与两国的经济、政治关系无关，放在这里句意说不通。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：“音乐”不属于两国经济和政治关系的范畴，与句中语境冲突。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气中”后接“经济和政治都很重要”不能成立，“天气”与这类内容不搭配。"}], "explanations": {"国际关系": "国际关系指国家之间的相互关系，经济和政治都是其中的重要内容，与句意相符。", "饮食": "语义：“饮食”与两国的经济、政治关系无关，放在这里句意说不通。", "音乐": "语义：“音乐”不属于两国经济和政治关系的范畴，与句中语境冲突。", "天气": "搭配：“天气中”后接“经济和政治都很重要”不能成立，“天气”与这类内容不搭配。"}, "sentence_index": 6, "correct_answer": "国际关系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们家的国际关系很和睦，大家都很开心。", "explanation": "这里应该用〈家庭关系〉。国际关系指国家之间的关系，家人之间的关系要用家庭关系。"}, {"text": "公司和员工的国际关系最近很和谐。", "explanation": "这里应该用〈劳资关系〉。国际关系指国家之间的关系，公司与员工之间的关系要用劳资关系。"}, {"text": "我和邻居的国际关系很好，平时常互相照应。", "explanation": "这里应该用〈邻里关系〉。国际关系指国家之间的关系，邻居之间的关系要用邻里关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最近两国地国际关系很友好。", "corrected_sentence": "最近两国的国际关系很友好。", "error_description": "错误形式：“两国地国际关系”。正确形式：“两国的国际关系”。“地”用于修饰动词、形容词，不用于名词前的定语，此处修饰名词“国际关系”应用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国的国际关系改善地很快。", "corrected_sentence": "两国的国际关系改善得很快。", "error_description": "错误在补语标记：“地”修饰动词，不能用来补充“改善”的程度，应用“得”。正确说法是“改善得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce4a8c77-222a-44cd-98bf-9fd5cf8c2c99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93577, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
