INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93577, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事是造字的一种办法，用符号表示意思。", "primary_collocate": null, "pronunciation": "zhǐ shì", "ipa": "ʈʂʅ˨˩˦ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "指事是造字的一种办法。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用一个小符号表示意思，这就是指事。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人想到了指事这个办法来造字。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“上”字用指事的办法造出来。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指事不画东西，只用符号。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上问：什么是指事？", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉字时，我常常分不清指事和会意。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指事这个办法很有意思。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用“下”字讲指事。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得指事比象形难懂。", "target_word": "指事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指事字", "label": "复合"}], "register": "中性", "sense_fingerprint": "用符号表示意思的造字办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30121eb2-4bca-4011-9a89-398f42fd683f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93577, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指事", "is_correct": true, "explanation": "正确。指事是用符号表示意思的造字办法，读 zhǐ shì。"}, {"text": "指使", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，指使的意思是支使别人做事。"}, {"text": "制式", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，制式指规定的样式。"}, {"text": "直视", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，直视的意思是直接看。"}, {"text": "史事", "is_correct": false, "explanation": "shǐ（第三声）与 zhǐ（第三声）声母不同（sh 与 zh），史事指历史上的事情。"}], "explanations": {"指事": "正确。指事是用符号表示意思的造字办法，读 zhǐ shì。", "指使": "shǐ（第三声）与 shì（第四声）声调不同，指使的意思是支使别人做事。", "制式": "zhì（第四声）与 zhǐ（第三声）声调不同，制式指规定的样式。", "直视": "zhí（第二声）与 zhǐ（第三声）声调不同，直视的意思是直接看。", "史事": "shǐ（第三声）与 zhǐ（第三声）声母不同（sh 与 zh），史事指历史上的事情。"}, "sentence_index": null, "correct_answer": "指事"}, "level_3": {"options": [{"text": "指事", "is_correct": true, "explanation": "正确。指事就是用符号表示意思的造字办法。"}, {"text": "偏旁", "is_correct": false, "explanation": "语义：偏旁是汉字的组成部件，不是造字的办法，“偏旁是造字的一种办法”说不通。"}, {"text": "词语", "is_correct": false, "explanation": "语义：词语是词的总称，不是造字的办法。"}, {"text": "注音", "is_correct": false, "explanation": "搭配：注音是标注读音，不能作“造字的一种办法”。"}], "explanations": {"指事": "正确。指事就是用符号表示意思的造字办法。", "偏旁": "语义：偏旁是汉字的组成部件，不是造字的办法，“偏旁是造字的一种办法”说不通。", "词语": "语义：词语是词的总称，不是造字的办法。", "注音": "搭配：注音是标注读音，不能作“造字的一种办法”。"}, "sentence_index": 0, "correct_answer": "指事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“山”字是画出山的样子，是用指事的办法造出来的。", "explanation": "这里应该用〈象形〉。“山”画出山的样子，属于象形；指事是用符号表示抽象意思，不画具体事物。"}, {"text": "“休”字是人靠在树边，是用指事的办法造出来的。", "explanation": "这里应该用〈会意〉。“休”由“人”和“木”合成，表示休息，属于会意；指事要用符号，不靠组合。"}, {"text": "“河”字一边表示意思，一边表示读音，是用指事的办法造出来的。", "explanation": "这里应该用〈形声〉。“河”由形旁和声旁组成，属于形声；指事不表示读音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93577, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "指事", "is_correct": true, "explanation": "正确。指事是用符号表示意思的造字办法，读 zhǐ shì。"}, {"text": "执事", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，执事指旧时办事的人或从事某种职务。"}, {"text": "知事", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，知事指旧时的地方官。"}, {"text": "志士", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，志士指有远大志向的人。"}], "explanations": {"指事": "正确。指事是用符号表示意思的造字办法，读 zhǐ shì。", "执事": "zhí（第二声）与 zhǐ（第三声）声调不同，执事指旧时办事的人或从事某种职务。", "知事": "zhī（第一声）与 zhǐ（第三声）声调不同，知事指旧时的地方官。", "志士": "zhì（第四声）与 zhǐ（第三声）声调不同，志士指有远大志向的人。"}, "sentence_index": null, "correct_answer": "指事"}, "level_3": {"options": [{"text": "指事", "is_correct": true, "explanation": "正确。“指事”与“会意”是需要分清的两种造字法。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“分不清……和……”并列的应是造字法，乐器不是造字法。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与“会意”不是同类概念，不能和它并列被分不清。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“分不清……和……”要求并列的两项是同类概念，天气与会意不能并列。"}], "explanations": {"指事": "正确。“指事”与“会意”是需要分清的两种造字法。", "乐器": "语义：“分不清……和……”并列的应是造字法，乐器不是造字法。", "颜色": "语义：颜色与“会意”不是同类概念，不能和它并列被分不清。", "天气": "搭配：“分不清……和……”要求并列的两项是同类概念，天气与会意不能并列。"}, "sentence_index": 6, "correct_answer": "指事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“考”和“老”互相解释，属于指事。", "explanation": "这里应该用〈转注〉。“考”“老”互训，属于转注；指事是用符号表示抽象意思的造字法。"}, {"text": "“然”字借来表示“然后”，属于指事。", "explanation": "这里应该用〈假借〉。“然”借来表示“然后”，属于假借；指事是用符号表示抽象意思。"}, {"text": "红色是喜庆的指事。", "explanation": "这里应该用〈象征〉。红色是喜庆的象征；指事是造字的办法，不是表示喜庆的标志。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“一”字是用一只指事造出来的。", "corrected_sentence": "“一”字是用指事造出来的。", "error_description": "量词错误：“只”用于动物等，指事是造字的方法，不能用“只”来数。正确的说法是“用指事造出来的”，不加量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“上”字是把指事造出来的。", "corrected_sentence": "“上”字是用指事造出来的。", "error_description": "介词错误：引出造字办法要用“用”，应说“用指事造出来的”。“把”只能引出被处置的对象，“指事”是造字办法，不能被“造出来”，所以“把指事造出来”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
