INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93580, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "土地及其附着的建筑物等不动产。", "primary_collocate": null, "pronunciation": "dì chǎn", "ipa": "ti˥˩ tʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "地产属于不动产，不能随便搬走。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律保护个人合法的地产。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把地产登记在妻子名下。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔地产的所有权已经转让。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司持有大量地产。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家对地产收税。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他继承了父亲留下的地产。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买卖地产需要签订合同。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地产的价值很高。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行可以接受地产作为抵押。", "target_word": "地产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "房地产", "label": "复合"}, {"form": "地产商", "label": "复合"}], "register": "书面语", "sense_fingerprint": "土地及附着建筑物等不动产", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168ad27f-59af-419a-aeff-3d9250db54ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地产", "is_correct": true, "explanation": "正确。“地产属于不动产”指土地和建筑，“不能随便搬走”与之相符。"}, {"text": "股票", "is_correct": false, "explanation": "语义：股票属于动产，不属于不动产，与“属于不动产”冲突。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车可以移动，与“不能随便搬走”冲突。"}, {"text": "存款", "is_correct": false, "explanation": "搭配：“存款”不指实物，不能与“属于不动产”搭配。"}], "explanations": {"地产": "正确。“地产属于不动产”指土地和建筑，“不能随便搬走”与之相符。", "股票": "语义：股票属于动产，不属于不动产，与“属于不动产”冲突。", "汽车": "语义：汽车可以移动，与“不能随便搬走”冲突。", "存款": "搭配：“存款”不指实物，不能与“属于不动产”搭配。"}, "sentence_index": 0, "correct_answer": "地产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批机器属于地产，可以随便搬走。", "explanation": "这里应该用〈动产〉。机器可以移动，属于动产；地产是不动产，不能随便搬走。"}, {"text": "他的地产主要是存款和股票。", "explanation": "这里应该用〈财产〉。地产指土地和建筑，不包括存款和股票。"}, {"text": "他把地产放进了洗衣机。", "explanation": "这里应该用〈衣服〉。地产是土地和建筑，不能放进洗衣机，洗的应是〈衣服〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地产", "is_correct": true, "explanation": "正确。“继承了父亲留下的地产”指继承下来的土地和房屋，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被继承。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是可以被继承下来的财产，与句意冲突。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高一般说“遗传”，不说“继承留下的身高”。"}], "explanations": {"地产": "正确。“继承了父亲留下的地产”指继承下来的土地和房屋，符合句意。", "空气": "语义：空气不能被继承。", "时间": "语义：时间不是可以被继承下来的财产，与句意冲突。", "身高": "搭配：身高一般说“遗传”，不说“继承留下的身高”。"}, "sentence_index": 6, "correct_answer": "地产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的地产是医生。", "explanation": "这里应该用〈职业〉。地产是土地和建筑，不能用来说明人的职业。"}, {"text": "他家的客厅铺了一块地产。", "explanation": "这里应该用〈地毯〉。地产指土地和建筑，不能用来铺在地面上，铺地面的应是〈地毯〉。"}, {"text": "这个地产已经看完了，很有意思。", "explanation": "这里应该用〈电影〉。地产是土地和建筑，不能说看完，看完的应是〈电影〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲去世后，这匹地产归我了。", "corrected_sentence": "父亲去世后，这块地产归我了。", "error_description": "量词错误：“地产”的量词应为“块”。“匹”多用于马等牲畜和布匹，这里错用于地产。正确形式：父亲去世后，这块地产归我了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他卖了一块的地产给邻居。", "corrected_sentence": "他卖了一块地产给邻居。", "error_description": "定语标记错误：数量词“一块”与名词“地产”之间不能加“的”，应为“一块地产”。正确形式：他卖了一块地产给邻居。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
