INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93582, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "依照日子；每日（计算或做某事）。", "primary_collocate": null, "pronunciation": "àn rì", "ipa": "an⁵¹ ʐ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "房租按日计算，住三天交三天的钱。", "target_word": "按日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作按日算钱，干一天给一天。", "target_word": "按日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "利息是按日计算的。", "target_word": "按日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租车公司按日收费，一天一百块。", "target_word": "按日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们按日分配工作，每天不一样。", "target_word": "按日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店按日统计住客的人数。", "target_word": "按日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园按日限制进来的人数。", "target_word": "按日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们按日付房钱，不想一次付很多。", "target_word": "按日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店按日换菜单，今天吃的和昨天不同。", "target_word": "按日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板按日检查仓库里的货。", "target_word": "按日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "按日：副词，依照日子，以天为单位计算或做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53d5679f-77fa-4bf4-9eb8-f2e6cf29bb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "按日", "is_correct": true, "explanation": "按日指依照日子计算，与“住三天交三天的钱”的按天结算一致。"}, {"text": "按月", "is_correct": false, "explanation": "语义：按月计算与“住三天交三天的钱”的按天结算矛盾。"}, {"text": "随意", "is_correct": false, "explanation": "搭配：房租的计算有固定方式，“随意计算房租”不搭配。"}, {"text": "按年", "is_correct": false, "explanation": "语义：按年计算与“住三天交三天的钱”的按天结算冲突。"}], "explanations": {"按日": "按日指依照日子计算，与“住三天交三天的钱”的按天结算一致。", "按月": "语义：按月计算与“住三天交三天的钱”的按天结算矛盾。", "随意": "搭配：房租的计算有固定方式，“随意计算房租”不搭配。", "按年": "语义：按年计算与“住三天交三天的钱”的按天结算冲突。"}, "sentence_index": 0, "correct_answer": "按日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司按日收费，一年一次。", "explanation": "这里应该用〈按年〉。按日指依照天数计费，与“一年一次”矛盾，按年计费才与整句相符。"}, {"text": "这笔服务费按日收取，不分天数。", "explanation": "这里应该用〈一次性〉。按日指依照天数，与“不分天数”矛盾，一次性收取才与整句相符。"}, {"text": "这家健身房按日收费，不按天算。", "explanation": "这里应该用〈包月〉。按日就是按天计算，与“不按天算”矛盾，包月收费才与整句相符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "按日", "is_correct": true, "explanation": "按日指依照日子进行，“公园按日限制进来的人数”表示每天都做这件事。"}, {"text": "逐个", "is_correct": false, "explanation": "搭配：“逐个”指一个一个地，不与“限制人数”这类总量控制搭配。"}, {"text": "随手", "is_correct": false, "explanation": "搭配：“随手”指顺便、不经意，不与“限制人数”这类有规定的管理行为搭配。"}, {"text": "随便", "is_correct": false, "explanation": "语义：随便指随意，与“限制进来的人数”的规定性冲突。"}], "explanations": {"按日": "按日指依照日子进行，“公园按日限制进来的人数”表示每天都做这件事。", "逐个": "搭配：“逐个”指一个一个地，不与“限制人数”这类总量控制搭配。", "随手": "搭配：“随手”指顺便、不经意，不与“限制人数”这类有规定的管理行为搭配。", "随便": "语义：随便指随意，与“限制进来的人数”的规定性冲突。"}, "sentence_index": 6, "correct_answer": "按日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店主按日核对账本，每季度一次。", "explanation": "这里应该用〈按季〉。按日指每天都这样做，与“每季度一次”矛盾，按季核对才与整句相符。"}, {"text": "老板按日盘点库存，一年才一次。", "explanation": "这里应该用〈偶尔〉。按日指每天都这样做，与“一年才一次”矛盾，偶尔盘点才与整句相符。"}, {"text": "老板按日清点货物，每周只清点一次。", "explanation": "这里应该用〈按周〉。按日指每天都这样做，与“每周只清点一次”矛盾，按周清点才与整句相符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家旅馆房费按日了计算，住三天交三天的钱。", "corrected_sentence": "这家旅馆房费按日计算，住三天交三天的钱。", "error_description": "错误在“按日了”。“了”表示完成，不能放在副词“按日”和动词“计算”之间；“按日”是副词，应直接修饰动词，应说“按日计算”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店员按日了盘点货架上的商品。", "corrected_sentence": "店员按日盘点货架上的商品。", "error_description": "错误在“按日了”。“了”表示完成，不能放在副词“按日”和动词“盘点”之间；“按日”是副词，应直接修饰动词，应说“按日盘点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
