INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93585, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93585, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "摔是人或东西重重地掉在地上。", "primary_collocate": null, "pronunciation": "shuāi", "ipa": "ʂuaɪ̯⁵⁵", "syllable_count": 1, "sentences": [{"text": "他从树上摔下来，疼得直叫。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫从桌子上摔到了地上。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩没站稳，重重地摔在地上。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从马背上摔下来，腿受了伤。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梯子倒了，工人从上面摔了下来。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她脚下一滑，摔进了水里。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个苹果从高高的树上摔到草地上。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子从床上摔下来了，哭个不停。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只花瓶从架子上摔到地上了。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车的人从桥上摔到了河里，路人马上跑过去。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摔了", "label": "完成体"}, {"form": "摔过", "label": "经历体"}, {"form": "摔倒", "label": "复合"}, {"form": "摔跤", "label": "复合"}], "register": "口语", "sense_fingerprint": "摔：动词，人或东西从高处重重地掉到地上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53d5679f-77fa-4bf4-9eb8-f2e6cf29bb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93585, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "摔", "is_correct": true, "explanation": "摔（shuāi，第一声）指从高处重重地掉到地上，与所听到的读音一致。"}, {"text": "甩", "is_correct": false, "explanation": "甩（shuǎi，第三声）与 shuāi（第一声）声调不同，意思是挥动、扔出。"}, {"text": "率", "is_correct": false, "explanation": "率（shuài，第四声）与 shuāi（第一声）声调不同，意思是比率、速度，如效率。"}, {"text": "刷", "is_correct": false, "explanation": "刷（shuā）与 shuāi 韵母不同（a 与 ai），意思是用刷子擦洗。"}], "explanations": {"摔": "摔（shuāi，第一声）指从高处重重地掉到地上，与所听到的读音一致。", "甩": "甩（shuǎi，第三声）与 shuāi（第一声）声调不同，意思是挥动、扔出。", "率": "率（shuài，第四声）与 shuāi（第一声）声调不同，意思是比率、速度，如效率。", "刷": "刷（shuā）与 shuāi 韵母不同（a 与 ai），意思是用刷子擦洗。"}, "sentence_index": null, "correct_answer": "摔"}, "level_3": {"options": [{"text": "摔", "is_correct": true, "explanation": "摔：表示从高处重重落下，与“疼得直叫”的结果相符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写下来”是书写记录，“从树上写下来”说不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“从树上……下来”搭配表示落下。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪，与从树上落下的动作毫无关联。"}], "explanations": {"摔": "摔：表示从高处重重落下，与“疼得直叫”的结果相符。", "写": "语义：“写下来”是书写记录，“从树上写下来”说不通。", "洗": "搭配：“洗”不能与“从树上……下来”搭配表示落下。", "煮": "语义：“煮”是烹饪，与从树上落下的动作毫无关联。"}, "sentence_index": 0, "correct_answer": "摔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花瓣从枝头摔下来，落了一地。", "explanation": "这里应该用〈掉〉。摔强调重重地跌落、撞到地面，花瓣轻柔，应说“掉”。"}, {"text": "他把跌倒的孩子摔起来，轻声安慰。", "explanation": "这里应该用〈扶〉。摔是使人重重落下，扶是轻轻支撑着使人站起，二者意思相反。"}, {"text": "雨滴从屋檐上摔下来，滴在地上。", "explanation": "这里应该用〈落〉。摔指重重地跌落、撞到地面，雨滴很轻，应说“落”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93585, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "摔", "is_correct": true, "explanation": "摔（shuāi，第一声）指从高处重重地掉到地上，与所听到的读音一致。"}, {"text": "帅", "is_correct": false, "explanation": "帅（shuài，第四声）与 shuāi（第一声）声调不同，意思是英俊、统帅。"}, {"text": "拴", "is_correct": false, "explanation": "拴（shuān）韵母 an 与 shuāi 的 ai 不同，意思是用绳子系住。"}, {"text": "甩", "is_correct": false, "explanation": "甩（shuǎi，第三声）与 shuāi（第一声）声调不同，意思是挥动、扔出。"}], "explanations": {"摔": "摔（shuāi，第一声）指从高处重重地掉到地上，与所听到的读音一致。", "帅": "帅（shuài，第四声）与 shuāi（第一声）声调不同，意思是英俊、统帅。", "拴": "拴（shuān）韵母 an 与 shuāi 的 ai 不同，意思是用绳子系住。", "甩": "甩（shuǎi，第三声）与 shuāi（第一声）声调不同，意思是挥动、扔出。"}, "sentence_index": null, "correct_answer": "摔"}, "level_3": {"options": [{"text": "摔", "is_correct": true, "explanation": "摔：指苹果从高处重重地落到草地上，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发声，不能表示人倒落在地上，句子不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与“在草地上”的落地动作无关，句子说不通。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”不能与“在草地上”搭配表示落点。"}], "explanations": {"摔": "摔：指苹果从高处重重地落到草地上，符合句意。", "唱": "语义：“唱”是发声，不能表示人倒落在地上，句子不通。", "吃": "语义：“吃”与“在草地上”的落地动作无关，句子说不通。", "煮": "搭配：“煮”不能与“在草地上”搭配表示落点。"}, "sentence_index": 6, "correct_answer": "摔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他年轻时吃过不少摔打，如今很懂得做人的道理。", "explanation": "此句中的“摔”指“摔打”，即经受磨炼，是另一个义项，与“重重地掉在地上”无关。"}, {"text": "她一进门就摔脸子，谁也不理。", "explanation": "此句中的“摔”指“摔脸子”，即显出不高兴的样子，是另一个义项，与“重重地掉在地上”无关。"}, {"text": "那次失败让他摔了一个大跟头，他却没有放弃。", "explanation": "此句中的“摔”指遭受挫折，是引申义，与“重重地掉在地上”不是同一义项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93585, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她从床上摔来下，头碰到了桌角。", "corrected_sentence": "她从床上摔下来，头碰到了桌角。", "error_description": "“下来”是“摔”的趋向补语，应说“摔下来”；“摔来下”把两个趋向成分的顺序颠倒了，不符合汉语语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93585, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一下子摔了倒，膝盖擦破了。", "corrected_sentence": "他一下子摔倒了，膝盖擦破了。", "error_description": "结果补语“倒”应紧跟在“摔”后面，说“摔倒了”；“摔了倒”把“了”插在中间，语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93586, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93586, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93586, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体失去平衡跌倒；使物体落地破损。", "primary_collocate": null, "pronunciation": "shuāi", "ipa": "ʂuaɪ̯⁵⁵", "syllable_count": 1, "sentences": [{"text": "下雨路滑，他在门口摔了一跤。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小弟弟跑得太快，一下子摔了。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不小心把杯子摔了，水洒了一地。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰上很滑，我摔了两次。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生气地把玩具摔了。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑车时摔得很厉害，腿疼了好几天。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点儿，别把手机摔了。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼梯太黑，奶奶摔了一下。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘子从桌上掉下去，摔了。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他滑冰时摔过很多次。", "target_word": "摔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摔了", "label": "完成体"}, {"form": "摔过", "label": "经历体"}, {"form": "摔倒", "label": "复合"}, {"form": "摔跤", "label": "复合"}], "register": "口语", "sense_fingerprint": "摔：动词，人失去平衡跌倒，或使东西落地摔坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53d5679f-77fa-4bf4-9eb8-f2e6cf29bb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93586, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "摔", "is_correct": true, "explanation": "摔（shuāi，第一声）指身体失去平衡跌倒，或使东西落地破损，与所听到的读音一致。"}, {"text": "甩", "is_correct": false, "explanation": "甩（shuǎi，第三声）与 shuāi（第一声）声调不同，意思是挥动、扔出，不是跌倒。"}, {"text": "刷", "is_correct": false, "explanation": "刷（shuā）与 shuāi 韵母不同（a 与 ai），意思是用刷子擦洗。"}, {"text": "帅", "is_correct": false, "explanation": "帅（shuài，第四声）与 shuāi（第一声）声调不同，意思是英俊、统帅。"}], "explanations": {"摔": "摔（shuāi，第一声）指身体失去平衡跌倒，或使东西落地破损，与所听到的读音一致。", "甩": "甩（shuǎi，第三声）与 shuāi（第一声）声调不同，意思是挥动、扔出，不是跌倒。", "刷": "刷（shuā）与 shuāi 韵母不同（a 与 ai），意思是用刷子擦洗。", "帅": "帅（shuài，第四声）与 shuāi（第一声）声调不同，意思是英俊、统帅。"}, "sentence_index": null, "correct_answer": "摔"}, "level_3": {"options": [{"text": "摔", "is_correct": true, "explanation": "摔：与“一跤”搭配表示跌倒，符合“下雨路滑”的语境。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛出的动作，与“一跤”（跌倒）语义不符，句子说不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗，“他在门口洗了一跤”无法成立。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”不能与“一跤”搭配，“写了一跤”不是合法的说法。"}], "explanations": {"摔": "摔：与“一跤”搭配表示跌倒，符合“下雨路滑”的语境。", "扔": "语义：“扔”是抛出的动作，与“一跤”（跌倒）语义不符，句子说不通。", "洗": "语义：“洗”是清洗，“他在门口洗了一跤”无法成立。", "写": "搭配：“写”不能与“一跤”搭配，“写了一跤”不是合法的说法。"}, "sentence_index": 0, "correct_answer": "摔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一片树叶从树上摔了下来。", "explanation": "这里应该用〈掉〉。摔强调重重地跌落、撞到地面，树叶轻飘，只能说“掉”。"}, {"text": "他把老人摔起来，让她坐在椅子上。", "explanation": "这里应该用〈扶〉。摔是使人或物重重落下，扶是支撑着使人站起，二者意思相反。"}, {"text": "他把哑铃摔起来，练了一上午。", "explanation": "这里应该用〈举〉。摔指重重地落下，把哑铃向上托起要说“举”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93586, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "摔", "is_correct": true, "explanation": "摔（shuāi，第一声）指身体失去平衡跌倒，或使东西落地破损，与所听到的读音一致。"}, {"text": "率", "is_correct": false, "explanation": "率（shuài，第四声）与 shuāi（第一声）声调不同，意思是比例、效率。"}, {"text": "拴", "is_correct": false, "explanation": "拴（shuān）韵母 an 与 shuāi 的 ai 不同，意思是用绳子系住。"}, {"text": "甩", "is_correct": false, "explanation": "甩（shuǎi，第三声）与 shuāi（第一声）声调不同，意思是挥动、扔出。"}], "explanations": {"摔": "摔（shuāi，第一声）指身体失去平衡跌倒，或使东西落地破损，与所听到的读音一致。", "率": "率（shuài，第四声）与 shuāi（第一声）声调不同，意思是比例、效率。", "拴": "拴（shuān）韵母 an 与 shuāi 的 ai 不同，意思是用绳子系住。", "甩": "甩（shuǎi，第三声）与 shuāi（第一声）声调不同，意思是挥动、扔出。"}, "sentence_index": null, "correct_answer": "摔"}, "level_3": {"options": [{"text": "摔", "is_correct": true, "explanation": "摔：指手机落地受损，与“小心点儿”的语境一致。"}, {"text": "吃", "is_correct": false, "explanation": "语义：手机不能吃，“吃”与“手机”语义冲突。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”只用于食物或水等，不能与“手机”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声歌唱，无法对手机施加动作，句子不通。"}], "explanations": {"摔": "摔：指手机落地受损，与“小心点儿”的语境一致。", "吃": "语义：手机不能吃，“吃”与“手机”语义冲突。", "煮": "搭配：“煮”只用于食物或水等，不能与“手机”搭配。", "唱": "语义：“唱”指发声歌唱，无法对手机施加动作，句子不通。"}, "sentence_index": 6, "correct_answer": "摔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从小就经受摔打，什么苦都能吃。", "explanation": "此句中的“摔”指“摔打”，即经受磨炼，是另一个义项，与“跌倒”无关。"}, {"text": "他一听这话就摔脸子，转身回了屋。", "explanation": "此句中的“摔”指“摔脸子”，即显出不高兴的样子，是另一个义项，与“跌倒”无关。"}, {"text": "这次挫折让他摔了一个大跟头，但他很快就振作了起来。", "explanation": "此句中的“摔”指遭受挫折，是引申义，与“身体失去平衡跌倒”不是同一义项。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天从楼梯上摔很厉害，腿到现在还疼。", "corrected_sentence": "他昨天从楼梯上摔得很厉害，腿到现在还疼。", "error_description": "“摔”后面接表示程度的补语时要用“得”连接，应说“摔得很厉害”；“摔很厉害”漏掉了“得”，不符合汉语习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小心点儿，别把杯子摔了碎。", "corrected_sentence": "小心点儿，别把杯子摔碎了。", "error_description": "结果补语“碎”应紧跟在“摔”后面，说“摔碎了”；“摔了碎”把“了”插在中间，语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
