INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93587, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "婚礼是两个人结为夫妻时，大家聚在一起庆祝的典礼。", "primary_collocate": null, "pronunciation": "hūn lǐ", "ipa": "xu̯ən˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "周六我去参加朋友的婚礼。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼上大家都很开心。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新娘在婚礼上穿了白色的裙子。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼上我们坐在第一排。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的婚礼上来了一百多位客人。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼开始前，客人已经坐好了。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在婚礼上唱了一首歌。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥的婚礼很热闹。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼结束后，大家一起拍照。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次看到中国人的婚礼。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "婚礼现场", "label": "复合"}], "register": "中性", "sense_fingerprint": "婚礼：新人结婚时亲友聚在一起庆祝的典礼场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1163fc0d-9628-401a-8cdf-c361cf20c442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93587, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "婚礼", "is_correct": true, "explanation": "婚礼：结婚时举行的典礼，可以被参加，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“参加”后接活动类名词，“手机”不能被参加。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是物品，不是可以参加的活动。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能被参加，与“参加朋友的”不合。"}], "explanations": {"婚礼": "婚礼：结婚时举行的典礼，可以被参加，符合句意。", "手机": "搭配：“参加”后接活动类名词，“手机”不能被参加。", "行李": "语义：行李是物品，不是可以参加的活动。", "房子": "语义：房子不能被参加，与“参加朋友的”不合。"}, "sentence_index": 0, "correct_answer": "婚礼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们的婚礼维持了十年。", "explanation": "这里应该用〈婚姻〉。“婚礼”指结婚的典礼，是一次性的活动，不能说维持多久；婚后的关系要用“婚姻”。"}, {"text": "我们参加了一只婚礼。", "explanation": "这里量词应该用〈场〉。婚礼要用“场”计量，“只”用于动物等。"}, {"text": "我们在婚礼前为死者默哀。", "explanation": "这里应该用〈葬礼〉。为死者默哀属于丧事场合，婚礼是喜庆的结婚典礼，不能用于此处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93587, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "婚礼", "is_correct": true, "explanation": "婚礼：可以作为唱歌的场合，符合句意。"}, {"text": "考卷", "is_correct": false, "explanation": "语义：考卷是答题的纸，不能作为唱歌的场合。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“在……上唱歌”要求场所或舞台，“冰箱”不能与“唱歌”搭配。"}, {"text": "作业本", "is_correct": false, "explanation": "语义：作业本是写作业用的，与唱歌的场合无关。"}], "explanations": {"婚礼": "婚礼：可以作为唱歌的场合，符合句意。", "考卷": "语义：考卷是答题的纸，不能作为唱歌的场合。", "冰箱": "搭配：“在……上唱歌”要求场所或舞台，“冰箱”不能与“唱歌”搭配。", "作业本": "语义：作业本是写作业用的，与唱歌的场合无关。"}, "sentence_index": 6, "correct_answer": "婚礼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新娘穿着婚礼走进了教堂。", "explanation": "这里应该用〈婚纱〉。“婚礼”指结婚的典礼，不指礼服；新娘身上穿的礼服要用“婚纱”。"}, {"text": "开幕婚礼十点开始。", "explanation": "这里应该用〈仪式〉。“婚礼”特指结婚，开幕活动要用“仪式”。"}, {"text": "我们去参加毕业婚礼。", "explanation": "这里应该用〈典礼〉。毕业活动要用“毕业典礼”，“婚礼”只指结婚的典礼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93587, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们参加了一本婚礼。", "corrected_sentence": "我们参加了一场婚礼。", "error_description": "量词用错了。“本”用于书本等，婚礼要用“场”计量，应为“一场婚礼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93587, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在婚礼的后去了海边。", "corrected_sentence": "我们在婚礼后去了海边。", "error_description": "“后”作方位词直接跟在“婚礼”之后，表示“婚礼之后”，中间不加“的”。此句多加了“的”，应为“在婚礼后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
