INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93588, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "举行结婚仪式的典礼。", "primary_collocate": null, "pronunciation": "hūn lǐ", "ipa": "xu̯ən˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们打算明年春天举行婚礼。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼定在十月一号。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边办婚礼。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼的时间是下午三点。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的婚礼在教堂举行。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了婚礼，她买了新鞋。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们请了两位朋友帮忙办婚礼。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，婚礼改到了下周。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想办一场小小的婚礼。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不想花太多钱办婚礼。", "target_word": "婚礼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "婚礼现场", "label": "复合"}], "register": "中性", "sense_fingerprint": "婚礼：举办、安排的结婚仪式，强调筹备和举行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1163fc0d-9628-401a-8cdf-c361cf20c442') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "婚礼", "is_correct": true, "explanation": "婚礼：可以被举行的仪式，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“举行”后接活动类名词，“手机”不能被举行。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是活动，不能举行。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，与“举行”的活动不合。"}], "explanations": {"婚礼": "婚礼：可以被举行的仪式，符合句意。", "手机": "搭配：“举行”后接活动类名词，“手机”不能被举行。", "房子": "语义：房子不是活动，不能举行。", "书包": "语义：书包是物品，与“举行”的活动不合。"}, "sentence_index": 0, "correct_answer": "婚礼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们的婚礼很稳定。", "explanation": "这里应该用〈婚姻〉。“婚礼”是一次性的仪式，不能形容稳定；婚后的状态要用“婚姻”。"}, {"text": "我们办了一只婚礼。", "explanation": "这里量词应该用〈场〉。“只”用于动物等，婚礼要用“场”计量。"}, {"text": "他是我的婚礼。", "explanation": "这里应该用〈新郎〉。“婚礼”指活动，不能指人；指新人之一要用“新郎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "婚礼", "is_correct": true, "explanation": "婚礼：可以办的活动，符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“办”一般不与“作业”搭配，作业要说“做”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能被办。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，不是可以办的事情。"}], "explanations": {"婚礼": "婚礼：可以办的活动，符合句意。", "作业": "搭配：“办”一般不与“作业”搭配，作业要说“做”。", "冰箱": "语义：冰箱是家电，不能被办。", "眼镜": "语义：眼镜是物品，不是可以办的事情。"}, "sentence_index": 6, "correct_answer": "婚礼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校举办了开学婚礼。", "explanation": "这里应该用〈典礼〉。“婚礼”只指结婚的仪式，开学活动要用“典礼”。"}, {"text": "婚礼是中国最重要的节日。", "explanation": "这里应该用〈春节〉。“婚礼”是结婚的仪式，不是全国性的节日。"}, {"text": "签约婚礼很隆重。", "explanation": "这里应该用〈仪式〉。签约活动要用“仪式”，“婚礼”只指结婚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们明年在海边举行过婚礼。", "corrected_sentence": "他们明年在海边举行婚礼。", "error_description": "“过”表示过去的经历，不能和将来时间“明年”一起用。应去掉“过”，说“明年在海边举行婚礼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在婚礼前了一个月去拍了照片。", "corrected_sentence": "他们在婚礼前一个月去拍了照片。", "error_description": "“前”作方位词，后面不能加“了”，此句在“前”后多加了“了”，应去掉，说“在婚礼前一个月”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c16b96a-33b3-4dc2-b1bd-a9a3cb8f5391') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
