INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93589, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "政客是靠说话来争取当官的人。", "primary_collocate": null, "pronunciation": "zhèng kè", "ipa": "ʈʂɤŋ⁵¹ kʰɤ⁵¹", "syllable_count": 2, "sentences": [{"text": "那位政客在台上说了很多好听的话。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政客常常用好听的话来争取大家的票。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政客每次选举前都到街上讲话。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太相信只会说话的政客。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位政客为了当官，到处找人拉票。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政客在电视上说要给大家更好的生活。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个政客一开口，台下就有人鼓掌。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选举快到了，政客们到处讲话。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，政客的话不能全信。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不喜欢那些只想当官的政客。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位政客", "label": "量词"}, {"form": "一个政客", "label": "量词"}], "register": "中性", "sense_fingerprint": "政客：名词，靠说话争取选票、想当官的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53d5679f-77fa-4bf4-9eb8-f2e6cf29bb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93589, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政客", "is_correct": true, "explanation": "政客：指靠说话争取官位的人，能在台上讲话，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会在台上说话，与“说了很多好听的话”相矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子无法说话，“那位桌子在台上说了很多话”不成立。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“那位”只用于人，不能修饰“花”。"}], "explanations": {"政客": "政客：指靠说话争取官位的人，能在台上讲话，符合句意。", "石头": "语义：石头不会在台上说话，与“说了很多好听的话”相矛盾。", "桌子": "语义：桌子无法说话，“那位桌子在台上说了很多话”不成立。", "花": "搭配：“那位”只用于人，不能修饰“花”。"}, "sentence_index": 0, "correct_answer": "政客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位政客每天都在工地上搬砖，干得很辛苦。", "explanation": "这里应该用〈工人〉。政客指靠说话争取官位的人，不能用来称呼在工地搬砖的人。"}, {"text": "这位政客每天都站在讲台上，耐心地教我们写字。", "explanation": "这里应该用〈老师〉。政客指以政治为职业、靠说话争取官位的人，不能用来称呼教书的人。"}, {"text": "这位政客每天都在医院里，认真地为病人检查身体。", "explanation": "这里应该用〈医生〉。政客不是医务人员，“政客”不能指为病人看病的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93589, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政客", "is_correct": true, "explanation": "政客：一开口讲话、台下鼓掌，符合句意。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不会开口说话，与“一开口”的句意冲突。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯没有说话的能力，“一开口”无法成立。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“一开口”一般用于能说话的人，不能与“窗户”搭配，句意不通。"}], "explanations": {"政客": "政客：一开口讲话、台下鼓掌，符合句意。", "闹钟": "语义：闹钟不会开口说话，与“一开口”的句意冲突。", "台灯": "语义：台灯没有说话的能力，“一开口”无法成立。", "窗户": "搭配：“一开口”一般用于能说话的人，不能与“窗户”搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "政客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位政客每天都在厨房里做菜，手艺很好。", "explanation": "这里应该用〈厨师〉。政客指靠说话争取官位的人，不能用来称呼在厨房做菜的人。"}, {"text": "这位政客每天都给客人剪头发，手艺很好。", "explanation": "这里应该用〈理发师〉。政客指靠说话争取官位的人，不能用来称呼给客人剪头发的人。"}, {"text": "这位政客每天都在公司里算账，从不出错。", "explanation": "这里应该用〈会计〉。政客指靠说话争取官位的人，不能用来称呼负责算账的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个只想当官政客一直在台上讲话。", "corrected_sentence": "那个只想当官的政客一直在台上讲话。", "error_description": "错误在“只想当官政客”。“只想当官的”修饰“政客”，中间的定语标记“的”不能省，应说“那个只想当官的政客”；“只想当官政客”缺少“的”，不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我认识一张政客，他很会讲话。", "corrected_sentence": "我认识一位政客，他很会讲话。", "error_description": "“政客”指人，量词应用“位”或“个”；“张”用于平面的物品，不能用来计量指人的名词，应说“一位政客”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
