INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93590, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以政治为职业、热衷权谋的人（多含贬义）。", "primary_collocate": null, "pronunciation": "zhèng kè", "ipa": "ʈʂɤŋ⁵¹ kʰɤ⁵¹", "syllable_count": 2, "sentences": [{"text": "这个政客为了权力，什么手段都用。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是为民办事的人，而是玩弄权谋的政客。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政客们常常为了自己的利益互相斗争。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们都说他是个只会耍手段的政客。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位政客靠着权谋一步步爬上高位。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政客今天的朋友，明天可能变成敌人。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了多年政客，早就学会了耍手段。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讽刺了一个满脑子权谋的政客。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓最讨厌心里只有权力的政客。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸批评这个政客说一套做一套。", "target_word": "政客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位政客", "label": "量词"}, {"form": "一个政客", "label": "量词"}], "register": "书面", "sense_fingerprint": "政客：名词，以政治为职业、热衷权谋的人，多含贬义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53d5679f-77fa-4bf4-9eb8-f2e6cf29bb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93590, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政客", "is_correct": true, "explanation": "政客：热衷权谋、为权力不择手段的人，与句意一致。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有权力欲望，无法“为了权力”而行动。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会为权力而行动，句子不通。"}, {"text": "花", "is_correct": false, "explanation": "配价：“为了权力”需要有意志的施事，花不能充当这一角色。"}], "explanations": {"政客": "政客：热衷权谋、为权力不择手段的人，与句意一致。", "石头": "语义：石头没有权力欲望，无法“为了权力”而行动。", "桌子": "语义：桌子不会为权力而行动，句子不通。", "花": "配价：“为了权力”需要有意志的施事，花不能充当这一角色。"}, "sentence_index": 0, "correct_answer": "政客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位政客一直在诊所里为贫困地区的孩子看病，大家都很信任他。", "explanation": "这里应该用〈医生〉。政客指热衷权谋的人，不能用来称呼为孩子看病的人。"}, {"text": "这位政客每天都在田里插秧，腰都直不起来。", "explanation": "这里应该用〈农民〉。政客指热衷权谋的人，不能用来称呼在田里插秧的人。"}, {"text": "这位政客每天都在书店里整理书架，熟悉每本书的位置。", "explanation": "这里应该用〈店员〉。政客指热衷权谋的人，不能用来称呼在书店整理书架的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政客", "is_correct": true, "explanation": "政客：指以政治为职业、热衷权谋的人，“当了多年政客”符合句意。"}, {"text": "电灯", "is_correct": false, "explanation": "语义：电灯是器物，不能当职业，“当了多年电灯”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“当了多年”要求担任某种职业的人，窗户无法充当这一角色。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是器物，不能担任职业，“当了多年雨伞”说不通。"}], "explanations": {"政客": "政客：指以政治为职业、热衷权谋的人，“当了多年政客”符合句意。", "电灯": "语义：电灯是器物，不能当职业，“当了多年电灯”说不通。", "窗户": "配价：“当了多年”要求担任某种职业的人，窗户无法充当这一角色。", "雨伞": "语义：雨伞是器物，不能担任职业，“当了多年雨伞”说不通。"}, "sentence_index": 6, "correct_answer": "政客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位政客每天都在花园里浇花，花开得很好。", "explanation": "这里应该用〈园丁〉。政客指热衷权谋的人，不能用来称呼负责浇花的人。"}, {"text": "这位政客每天都在店里踩缝纫机，衣服做得很快。", "explanation": "这里应该用〈裁缝〉。政客指热衷权谋的人，不能用来称呼在店里做衣服的人。"}, {"text": "这位政客每天都在病房里给病人打针。", "explanation": "这里应该用〈护士〉。政客指热衷权谋的人，不能用来称呼给病人打针的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位靠耍手段上位政客，最后还是被人揭穿了。", "corrected_sentence": "这位靠耍手段上位的政客，最后还是被人揭穿了。", "error_description": "“靠耍手段上位的”是修饰“政客”的定语，二者之间必须加“的”；漏掉“的”，应说“靠耍手段上位的政客”，不能说“靠耍手段上位政客”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老先生其实是一台政客，手段很高明。", "corrected_sentence": "这位老先生其实是一位政客，手段很高明。", "error_description": "“政客”指人，量词应用“位”或“个”；“台”用于机器等器物，不能用来计量指人的名词，应说“一位政客”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16c1a515-6aa4-46f8-8cfa-144c69fe6488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
