INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93591, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "一次种植到收成的农时周期，一年可种一季或两季。", "primary_collocate": null, "pronunciation": "jì", "ipa": "tɕi˥˩", "syllable_count": 1, "sentences": [{"text": "我们这里一年能种两季水稻。", "target_word": "季", "complexity_tier": "T3", "furigana": "wǒ men zhè lǐ yì nián néng zhòng liǎng jì shuǐ dào.", "sentence_source": "generated"}, {"text": "这一季稻子长得很好。", "target_word": "季", "complexity_tier": "T3", "furigana": "zhè yí jì dào zi zhǎng de hěn hǎo.", "sentence_source": "generated"}, {"text": "今年的小麦这一季收成不错。", "target_word": "季", "complexity_tier": "T3", "furigana": "jīn nián de xiǎo mài zhè yí jì shōu chéng bú cuò.", "sentence_source": "generated"}, {"text": "这里冬天太冷，一年只能种一季庄稼。", "target_word": "季", "complexity_tier": "T3", "furigana": "zhè lǐ dōng tiān tài lěng, yì nián zhǐ néng zhòng yí jì zhuāng jia.", "sentence_source": "generated"}, {"text": "今年雨水多，这一季蔬菜长得很快。", "target_word": "季", "complexity_tier": "T3", "furigana": "jīn nián yǔ shuǐ duō, zhè yí jì shū cài zhǎng de hěn kuài.", "sentence_source": "generated"}, {"text": "麦子收了，我们接着种下一季。", "target_word": "季", "complexity_tier": "T3", "furigana": "mài zi shōu le, wǒ men jiē zhe zhòng xià yí jì.", "sentence_source": "generated"}, {"text": "这一季的棉花收成不太好。", "target_word": "季", "complexity_tier": "T3", "furigana": "zhè yí jì de mián huā shōu chéng bú tài hǎo.", "sentence_source": "generated"}, {"text": "他们家今年种了两季菜。", "target_word": "季", "complexity_tier": "T3", "furigana": "tā men jiā jīn nián zhòng le liǎng jì cài.", "sentence_source": "generated"}, {"text": "这一季我们多施了一点肥，希望收成好。", "target_word": "季", "complexity_tier": "T3", "furigana": "zhè yí jì wǒ men duō shī le yì diǎn féi, xī wàng shōu chéng hǎo.", "sentence_source": "generated"}, {"text": "这一季的玉米产量比去年高。", "target_word": "季", "complexity_tier": "T3", "furigana": "zhè yí jì de yù mǐ chǎn liàng bǐ qù nián gāo.", "sentence_source": "generated"}], "morphological_forms": [{"form": "季节", "label": "复合"}, {"form": "四季", "label": "复合"}, {"form": "季度", "label": "复合"}], "register": "中性", "sense_fingerprint": "一次种植或收成的农时周期，如一年种两季水稻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '432c6f3e-dab6-42df-a5ff-3707d97e69dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93591, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "季", "is_correct": true, "explanation": "正确：「季」是一年中的一段时间，也指一次种植或收成的周期。"}, {"text": "鸡", "is_correct": false, "explanation": "声调不同：jī（第一声）与 jì（第四声）不同，意思是鸡。"}, {"text": "集", "is_correct": false, "explanation": "声调不同：jí（第二声）与 jì（第四声）不同，意思是集合。"}, {"text": "几", "is_correct": false, "explanation": "声调不同：jǐ（第三声）与 jì（第四声）不同，意思是几个。"}, {"text": "机", "is_correct": false, "explanation": "声调不同：jī（第一声）与 jì（第四声）不同，意思是机器。"}, {"text": "戏", "is_correct": false, "explanation": "声母不同：xì 的声母是 x，与 jì 的 j 不同，声调相同，意思是戏剧。"}], "explanations": {"季": "正确：「季」是一年中的一段时间，也指一次种植或收成的周期。", "鸡": "声调不同：jī（第一声）与 jì（第四声）不同，意思是鸡。", "集": "声调不同：jí（第二声）与 jì（第四声）不同，意思是集合。", "几": "声调不同：jǐ（第三声）与 jì（第四声）不同，意思是几个。", "机": "声调不同：jī（第一声）与 jì（第四声）不同，意思是机器。", "戏": "声母不同：xì 的声母是 x，与 jì 的 j 不同，声调相同，意思是戏剧。"}, "sentence_index": null, "correct_answer": "季"}, "level_3": {"options": [{"text": "季", "is_correct": true, "explanation": "正确：「季」作量词，表示一年中的一次种植周期，与「一年能种两」相符。"}, {"text": "棵", "is_correct": false, "explanation": "语义：「棵」量单株植物，「一年能种两棵」表达不了一年两收的意思。"}, {"text": "本", "is_correct": false, "explanation": "搭配：「本」量书本，不能用来量水稻。"}, {"text": "辆", "is_correct": false, "explanation": "搭配：「辆」量车辆，不能用来量水稻。"}], "explanations": {"季": "正确：「季」作量词，表示一年中的一次种植周期，与「一年能种两」相符。", "棵": "语义：「棵」量单株植物，「一年能种两棵」表达不了一年两收的意思。", "本": "搭配：「本」量书本，不能用来量水稻。", "辆": "搭配：「辆」量车辆，不能用来量水稻。"}, "sentence_index": 0, "correct_answer": "季"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了一季新鞋。", "explanation": "这里应该用〈双〉。季是时段，不能用来量鞋；成对的鞋要用双。"}, {"text": "我们中午吃了一季饭。", "explanation": "这里应该用〈顿〉。季是时段，不能用来量饭；吃饭的次数要用顿。"}, {"text": "这一季是我的生日。", "explanation": "这里应该用〈天〉。季是较长的时段，指具体某一天要用天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93591, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "季", "is_correct": true, "explanation": "正确：「季」是一年中的一段时间，也指一次种植或收成的周期。"}, {"text": "击", "is_correct": false, "explanation": "声调不同：jī（第一声）与 jì（第四声）不同，意思是击打。"}, {"text": "挤", "is_correct": false, "explanation": "声调不同：jǐ（第三声）与 jì（第四声）不同，意思是挤压。"}, {"text": "籍", "is_correct": false, "explanation": "声调不同：jí（第二声）与 jì（第四声）不同，意思是书籍。"}, {"text": "戏", "is_correct": false, "explanation": "声母不同：xì 的声母是 x，与 jì 的 j 不同，声调相同，意思是戏剧。"}], "explanations": {"季": "正确：「季」是一年中的一段时间，也指一次种植或收成的周期。", "击": "声调不同：jī（第一声）与 jì（第四声）不同，意思是击打。", "挤": "声调不同：jǐ（第三声）与 jì（第四声）不同，意思是挤压。", "籍": "声调不同：jí（第二声）与 jì（第四声）不同，意思是书籍。", "戏": "声母不同：xì 的声母是 x，与 jì 的 j 不同，声调相同，意思是戏剧。"}, "sentence_index": null, "correct_answer": "季"}, "level_3": {"options": [{"text": "季", "is_correct": true, "explanation": "正确：「季」指一次种植到收成的周期，与「这一」和「棉花收成」相符。"}, {"text": "夜", "is_correct": false, "explanation": "语义：「夜」指一个晚上，棉花收成不按一夜计算。"}, {"text": "张", "is_correct": false, "explanation": "搭配：「张」量平面的东西，不能用来量「收成」。"}, {"text": "套", "is_correct": false, "explanation": "搭配：「套」量成套的东西，不能用来量「收成」。"}], "explanations": {"季": "正确：「季」指一次种植到收成的周期，与「这一」和「棉花收成」相符。", "夜": "语义：「夜」指一个晚上，棉花收成不按一夜计算。", "张": "搭配：「张」量平面的东西，不能用来量「收成」。", "套": "搭配：「套」量成套的东西，不能用来量「收成」。"}, "sentence_index": 6, "correct_answer": "季"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家买了一季猫。", "explanation": "这里应该用〈只〉。季是时段，不能用来量猫；量猫要用只。"}, {"text": "一季鸟在天上飞。", "explanation": "这里应该用〈群〉。季不能用来量成群的鸟，成群的动物要用群。"}, {"text": "我们班来了一季新老师。", "explanation": "这里应该用〈位〉。季是时段，不能用来量人，量人要用位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93591, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村子一年能种两个季玉米，收成很好。", "corrected_sentence": "我们村子一年能种两季玉米，收成很好。", "error_description": "错误：「两个季」。「季」作量词时数词后直接接「季」，不能加「个」，应说「两季」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93591, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "第二季的玉米产量比第一个季高。", "corrected_sentence": "第二季的玉米产量比第一季高。", "error_description": "错误：「第一个季」。作序数「第一季」时不加「个」，应说「第一季」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
