INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93592, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "电视剧、节目或比赛按时间分成的一个播出或比赛阶段。", "primary_collocate": null, "pronunciation": "jì", "ipa": "tɕi˥˩", "syllable_count": 1, "sentences": [{"text": "这部电视剧已经拍了三季。", "target_word": "季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第二季比第一季更好看。", "target_word": "季", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个节目第一季最好看。", "target_word": "季", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新一季的比赛下个月开始。", "target_word": "季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上一季我们队输了很多场。", "target_word": "季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在这一季里进了二十个球。", "target_word": "季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最爱看的节目马上要播下一季了。", "target_word": "季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一季的选手都很年轻。", "target_word": "季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一季节目一共有十二集。", "target_word": "季", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球员们说，这一季一定要拿冠军。", "target_word": "季", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "赛季", "label": "复合"}], "register": "中性", "sense_fingerprint": "电视剧、节目或比赛的一个阶段，如第二季、新一季比赛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '432c6f3e-dab6-42df-a5ff-3707d97e69dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93592, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "季", "is_correct": true, "explanation": "正确答案：季（jì），指电视剧、节目或比赛的一个阶段。"}, {"text": "机", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，意思是飞机、机器。"}, {"text": "几", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，意思是几个、几次。"}, {"text": "气", "is_correct": false, "explanation": "qì 与 jì 声母不同（q 与 j），声调相同，意思是空气。"}, {"text": "进", "is_correct": false, "explanation": "jìn 比 jì 多一个韵尾 n，意思是进入。"}, {"text": "集", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是集合、聚集。"}, {"text": "静", "is_correct": false, "explanation": "jìng 比 jì 多一个鼻音韵尾 ng，意思是安静。"}], "explanations": {"季": "正确答案：季（jì），指电视剧、节目或比赛的一个阶段。", "机": "jī（第一声）与 jì（第四声）声调不同，意思是飞机、机器。", "几": "jǐ（第三声）与 jì（第四声）声调不同，意思是几个、几次。", "气": "qì 与 jì 声母不同（q 与 j），声调相同，意思是空气。", "进": "jìn 比 jì 多一个韵尾 n，意思是进入。", "集": "jí（第二声）与 jì（第四声）声调不同，意思是集合、聚集。", "静": "jìng 比 jì 多一个鼻音韵尾 ng，意思是安静。"}, "sentence_index": null, "correct_answer": "季"}, "level_3": {"options": [{"text": "季", "is_correct": true, "explanation": "正确：季。电视剧按播出的季数计，“三季”指三个播出周期。"}, {"text": "首", "is_correct": false, "explanation": "语义：“首”用于诗、歌曲，不能用来计量电视剧。"}, {"text": "支", "is_correct": false, "explanation": "搭配：“支”用于歌曲、队伍等，不用于计量电视剧。"}, {"text": "张", "is_correct": false, "explanation": "语义：“张”用于照片、票据等平面物件，与句中的电视剧不符。"}], "explanations": {"季": "正确：季。电视剧按播出的季数计，“三季”指三个播出周期。", "首": "语义：“首”用于诗、歌曲，不能用来计量电视剧。", "支": "搭配：“支”用于歌曲、队伍等，不用于计量电视剧。", "张": "语义：“张”用于照片、票据等平面物件，与句中的电视剧不符。"}, "sentence_index": 0, "correct_answer": "季"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他出生在抗战季。", "explanation": "这里应该用〈时期〉。季多指按气候划分的季节或比赛、节目的一段时期，历史阶段要用“时期”。"}, {"text": "我买了三季菜。", "explanation": "这里应该用〈次〉。季指一段时期，不用来计数买菜的次数；计次数要用“次”。"}, {"text": "这个人活了三季。", "explanation": "这里应该用〈年〉。季指节目或比赛的一个阶段，计算年数要用“年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93592, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "季", "is_correct": true, "explanation": "正确答案：季（jì），指电视剧、节目或比赛的一个阶段。"}, {"text": "鸡", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，意思是鸡。"}, {"text": "基", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，意思是基础、根基。"}, {"text": "及", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是及时、达到。"}, {"text": "戏", "is_correct": false, "explanation": "xì 与 jì 声母不同（x 与 j），声调相同，意思是戏剧。"}], "explanations": {"季": "正确答案：季（jì），指电视剧、节目或比赛的一个阶段。", "鸡": "jī（第一声）与 jì（第四声）声调不同，意思是鸡。", "基": "jī（第一声）与 jì（第四声）声调不同，意思是基础、根基。", "及": "jí（第二声）与 jì（第四声）声调不同，意思是及时、达到。", "戏": "xì 与 jì 声母不同（x 与 j），声调相同，意思是戏剧。"}, "sentence_index": null, "correct_answer": "季"}, "level_3": {"options": [{"text": "季", "is_correct": true, "explanation": "正确：季。节目按播出的季数计，“下一季”指下一个播出周期。"}, {"text": "幅", "is_correct": false, "explanation": "语义：“幅”用于画、布等平面作品，不用于节目。"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”只用于计量车辆，不能用于节目。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”用于山、桥、建筑等大型物体，与节目不符。"}], "explanations": {"季": "正确：季。节目按播出的季数计，“下一季”指下一个播出周期。", "幅": "语义：“幅”用于画、布等平面作品，不用于节目。", "辆": "搭配：“辆”只用于计量车辆，不能用于节目。", "座": "语义：“座”用于山、桥、建筑等大型物体，与节目不符。"}, "sentence_index": 6, "correct_answer": "季"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一季书。", "explanation": "这里应该用〈本〉。季不用来计量书，书用“本”计量。"}, {"text": "教室里坐着一季学生。", "explanation": "这里应该用〈个〉。季不用来计量人，学生用“个”或“名”计量。"}, {"text": "他看见一季狗。", "explanation": "这里应该用〈只〉。季不用来计量动物，一只狗用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一季比赛，我们队赢了三季。", "corrected_sentence": "这一季比赛，我们队赢了三场。", "error_description": "量词错误：季指一段时期，不能用来计量比赛的场次，应说“赢了三场”，不能说“赢了三季”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部剧已经播出了一只季。", "corrected_sentence": "这部剧已经播出了一季。", "error_description": "量词错误：“季”前的数量应直接用“一”，不能用“只”（“只”用于动物等）。应说“播出了一季”，不能说“播出了一只季”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4f56fe9-3aeb-45bc-8e67-c902b83d155d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
