INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93593, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政治改革是把国家管事情的办法改一改。", "primary_collocate": null, "pronunciation": "zhèng zhì gǎi gé", "ipa": "ʈʂɤŋ˥˩ ʈʂʅ˥˩ kaɪ˨˩˦ kɤ˧˥", "syllable_count": 4, "sentences": [{"text": "政治改革是改变国家管事情的办法。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家正在进行政治改革。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人关心这次政治改革。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政治改革让人民的生活变好了。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了那个国家的政治改革。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政治改革需要很长时间。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本书，说的是政治改革。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家为什么要做政治改革呢？", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政治改革以后，办事的办法不一样了。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在谈政治改革的事。", "target_word": "政治改革", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}], "register": "中性", "sense_fingerprint": "把国家管事情的办法改一改", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30121eb2-4bca-4011-9a89-398f42fd683f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93593, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政治改革", "is_correct": true, "explanation": "正确。“政治改革”就是改变国家管事情的办法。"}, {"text": "政府", "is_correct": false, "explanation": "语义：政府是负责管事的机构，不是改变管事办法的方式。"}, {"text": "农业", "is_correct": false, "explanation": "语义：农业是产业，不是国家管事情的办法。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“改变国家管事情的办法”不能用来解释天气，二者不搭配。"}], "explanations": {"政治改革": "正确。“政治改革”就是改变国家管事情的办法。", "政府": "语义：政府是负责管事的机构，不是改变管事办法的方式。", "农业": "语义：农业是产业，不是国家管事情的办法。", "天气": "搭配：“改变国家管事情的办法”不能用来解释天气，二者不搭配。"}, "sentence_index": 0, "correct_answer": "政治改革"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政治改革在国会里发表了演讲。", "explanation": "这里应该用〈政治家〉。政治家能在国会发表演讲，“政治改革”是改革的过程，不能作演讲的主语。"}, {"text": "政治改革在考试中得了满分。", "explanation": "这里应该用〈学生〉。能参加考试、得满分的是学生，“政治改革”是事件，不能参加考试。"}, {"text": "政治改革在电视辩论中回答了问题。", "explanation": "这里应该用〈候选人〉。能在辩论中回答问题的是候选人，“政治改革”不是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93593, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政治改革", "is_correct": true, "explanation": "正确。“说的是”后面接的是书的内容，“政治改革”是这本书的话题。"}, {"text": "页码", "is_correct": false, "explanation": "语义：页码是编排的数字，不是书的话题内容。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“说的是”后接的是名词性的话题，“非常”是副词，“说的是非常”不成话。"}, {"text": "问号", "is_correct": false, "explanation": "搭配：“说的是”后接的是内容或话题，问号是标点，不构成这样的搭配。"}], "explanations": {"政治改革": "正确。“说的是”后面接的是书的内容，“政治改革”是这本书的话题。", "页码": "语义：页码是编排的数字，不是书的话题内容。", "非常": "语法：“说的是”后接的是名词性的话题，“非常”是副词，“说的是非常”不成话。", "问号": "搭配：“说的是”后接的是内容或话题，问号是标点，不构成这样的搭配。"}, "sentence_index": 6, "correct_answer": "政治改革"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政治改革投票支持新的领导人。", "explanation": "这里应该用〈选民〉。选民才会投票，“政治改革”是事件，不会投票。"}, {"text": "政治改革在法庭上为被告辩护了。", "explanation": "这里应该用〈律师〉。能为被告辩护的是律师，“政治改革”是改革的过程，不是人，不能辩护。"}, {"text": "这个政治改革赢得了大多数席位。", "explanation": "这里应该用〈政党〉。席位是政党通过选举赢得的，“政治改革”不能赢得席位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93593, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把政治改革影响了很多人。", "corrected_sentence": "这次政治改革影响了很多人。", "error_description": "量词错误：“政治改革”是事件，应该用“次”；“把”用于有柄的器物，不能修饰它。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93593, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多国家都经历过一座政治改革。", "corrected_sentence": "很多国家都经历过一次政治改革。", "error_description": "量词错误：“座”用于山、桥、建筑等，“政治改革”是事件，应该用“次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0947fd28-abd9-4cad-b1dc-6c7adf83be9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
