INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93597, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旗是挂在杆子上，会随风飘的布。", "primary_collocate": null, "pronunciation": "qí", "ipa": "tɕʰi˧˥", "syllable_count": 1, "sentences": [{"text": "风一吹，旗就飘起来了。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旗在风中飘着。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天风很大，旗飘得很高。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶上的旗一直在动。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有风的时候，旗不会动。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见远处有一面旗在飘。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旗随着风向左边飘去。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杆子上的旗又旧又破。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抬头看着飘动的旗。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风停了以后，旗慢慢垂下来了。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "面", "label": "量词"}, {"form": "旗子", "label": "复合"}], "register": "中性", "sense_fingerprint": "挂在杆子上、随风飘动的布", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781e042f-01c8-4179-94a7-75f6a8a36a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93597, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "旗", "is_correct": true, "explanation": "旗（qí）：挂在杆子上、会随风飘的布。"}, {"text": "七", "is_correct": false, "explanation": "七（qī）：声调不同，qī 为第一声。意思是数字七。"}, {"text": "汽", "is_correct": false, "explanation": "汽（qì）：声调不同，qì 为第四声。意思是蒸汽、汽车。"}, {"text": "席", "is_correct": false, "explanation": "席（xí）：声母不同，x 与 q 的区别。意思是席位、席子。"}, {"text": "集", "is_correct": false, "explanation": "集（jí）：声母不同，j 与 q 的区别。意思是集合、集市。"}], "explanations": {"旗": "旗（qí）：挂在杆子上、会随风飘的布。", "七": "七（qī）：声调不同，qī 为第一声。意思是数字七。", "汽": "汽（qì）：声调不同，qì 为第四声。意思是蒸汽、汽车。", "席": "席（xí）：声母不同，x 与 q 的区别。意思是席位、席子。", "集": "集（jí）：声母不同，j 与 q 的区别。意思是集合、集市。"}, "sentence_index": null, "correct_answer": "旗"}, "level_3": {"options": [{"text": "旗", "is_correct": true, "explanation": "旗：随风飘起来的布，句意合理。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头很重，风吹不会让它飘起来。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会被风吹飘起来。"}, {"text": "铁锤", "is_correct": false, "explanation": "语义：铁锤很重，风吹不会让它飘起来。"}], "explanations": {"旗": "旗：随风飘起来的布，句意合理。", "石头": "语义：石头很重，风吹不会让它飘起来。", "桌子": "语义：桌子是家具，不会被风吹飘起来。", "铁锤": "语义：铁锤很重，风吹不会让它飘起来。"}, "sentence_index": 0, "correct_answer": "旗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用旗给手机充电。", "explanation": "这里应该用〈充电器〉。旗是布做的标志，不能用来充电；给手机充电要用充电器。"}, {"text": "他戴上了旗。", "explanation": "这里应该用〈手套〉。戴的是手套、帽子，旗不能戴。"}, {"text": "他拿旗切开了一个西瓜。", "explanation": "这里应该用〈刀〉。旗是布做的标志，不能用来切东西；切西瓜要用刀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93597, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "旗", "is_correct": true, "explanation": "旗（qí）：挂在杆子上、会随风飘的布。"}, {"text": "期", "is_correct": false, "explanation": "期（qī）：声调不同，qī 为第一声。意思是期限。"}, {"text": "起", "is_correct": false, "explanation": "起（qǐ）：声调不同，qǐ 为第三声。意思是起来、起身。"}, {"text": "习", "is_correct": false, "explanation": "习（xí）：声母不同，x 与 q 的区别。意思是练习、习惯。"}], "explanations": {"旗": "旗（qí）：挂在杆子上、会随风飘的布。", "期": "期（qī）：声调不同，qī 为第一声。意思是期限。", "起": "起（qǐ）：声调不同，qǐ 为第三声。意思是起来、起身。", "习": "习（xí）：声母不同，x 与 q 的区别。意思是练习、习惯。"}, "sentence_index": null, "correct_answer": "旗"}, "level_3": {"options": [{"text": "旗", "is_correct": true, "explanation": "旗：随风飘动的布，句意合理。"}, {"text": "卡车", "is_correct": false, "explanation": "语义：卡车很重，不会随着风飘去。"}, {"text": "石子", "is_correct": false, "explanation": "语义：石子很重，风吹不会让它飘去。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“飘”一般用于轻的东西，不说“窗户飘去”。"}], "explanations": {"旗": "旗：随风飘动的布，句意合理。", "卡车": "语义：卡车很重，不会随着风飘去。", "石子": "语义：石子很重，风吹不会让它飘去。", "窗户": "搭配：“飘”一般用于轻的东西，不说“窗户飘去”。"}, "sentence_index": 6, "correct_answer": "旗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿起旗扫地。", "explanation": "这里应该用〈扫帚〉。扫地要用扫帚，旗不能用来扫地。"}, {"text": "他用旗打开了门。", "explanation": "这里应该用〈钥匙〉。打开门要用钥匙，旗不能开门。"}, {"text": "他用旗写了一封信。", "explanation": "这里应该用〈笔〉。旗是布做的标志，不能用来写字；写信要用笔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93597, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风中飘着一只旗。", "corrected_sentence": "风中飘着一面旗。", "error_description": "量词错误：旗的量词应为“面”，“只”不能用于旗。正确说法：一面旗。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93597, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风中飘着两个旗。", "corrected_sentence": "风中飘着两面旗。", "error_description": "量词错误：旗的量词应为“面”，不能用“个”。正确说法：两面旗。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
