INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93598, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用布、纸等做成的方形或三角形标志物，挂在杆上。", "primary_collocate": null, "pronunciation": "qí", "ipa": "tɕʰi˧˥", "syllable_count": 1, "sentences": [{"text": "学校门口挂着一面旗。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那面旗是蓝色的。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旗挂在杆子上。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们手里拿着一面旗。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，他举起了旗。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面旗是用布做的。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶上有一面旗。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把旗放在桌子上。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旗上有一颗黄色的星。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们看着旗慢慢升上去。", "target_word": "旗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "面", "label": "量词"}, {"form": "旗子", "label": "复合"}], "register": "中性", "sense_fingerprint": "布或纸做成、挂在杆上的标志物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781e042f-01c8-4179-94a7-75f6a8a36a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93598, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "旗", "is_correct": true, "explanation": "旗（qí）：挂在杆子上的布制标志。"}, {"text": "期", "is_correct": false, "explanation": "期（qī）：声调不同，qī 为第一声，qí 为第二声。意思是期限。"}, {"text": "起", "is_correct": false, "explanation": "起（qǐ）：声调不同，qǐ 为第三声。意思是起来、起身。"}, {"text": "气", "is_correct": false, "explanation": "气（qì）：声调不同，qì 为第四声。意思是空气。"}, {"text": "习", "is_correct": false, "explanation": "习（xí）：声母不同，x 与 q 的区别。意思是练习、习惯。"}], "explanations": {"旗": "旗（qí）：挂在杆子上的布制标志。", "期": "期（qī）：声调不同，qī 为第一声，qí 为第二声。意思是期限。", "起": "起（qǐ）：声调不同，qǐ 为第三声。意思是起来、起身。", "气": "气（qì）：声调不同，qì 为第四声。意思是空气。", "习": "习（xí）：声母不同，x 与 q 的区别。意思是练习、习惯。"}, "sentence_index": null, "correct_answer": "旗"}, "level_3": {"options": [{"text": "旗", "is_correct": true, "explanation": "旗：挂在门口的标志物，量词“面”，句意合理。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙是砌成的，不能“挂”在校门口。"}, {"text": "湖", "is_correct": false, "explanation": "语义：湖是水域，不能挂在校门口。"}, {"text": "桥", "is_correct": false, "explanation": "语义：桥是建在河上的，不能“挂”在学校门口，量词也不用“面”。"}], "explanations": {"旗": "旗：挂在门口的标志物，量词“面”，句意合理。", "墙": "语义：墙是砌成的，不能“挂”在校门口。", "湖": "语义：湖是水域，不能挂在校门口。", "桥": "语义：桥是建在河上的，不能“挂”在学校门口，量词也不用“面”。"}, "sentence_index": 0, "correct_answer": "旗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用旗敲了敲门。", "explanation": "这里应该用〈木棍〉。旗是布做的标志物，不能拿来敲门；敲门要用木棍。"}, {"text": "她用红旗煮了一锅粥。", "explanation": "这里应该用〈锅〉。旗是布做的标志，不能用来煮东西；煮粥要用锅。"}, {"text": "他把旗当成板凳坐下了。", "explanation": "这里应该用〈板凳〉。旗是挂在杆子上的标志物，不能当板凳坐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93598, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "旗", "is_correct": true, "explanation": "旗（qí）：挂在杆子上的布制标志。"}, {"text": "七", "is_correct": false, "explanation": "七（qī）：声调不同，qī 为第一声。意思是数字七。"}, {"text": "汽", "is_correct": false, "explanation": "汽（qì）：声调不同，qì 为第四声。意思是蒸汽、汽车。"}, {"text": "席", "is_correct": false, "explanation": "席（xí）：声母不同，x 与 q 的区别。意思是席位、席子。"}, {"text": "集", "is_correct": false, "explanation": "集（jí）：声母不同，j 与 q 的区别。意思是集合、集市。"}, {"text": "企", "is_correct": false, "explanation": "企（qǐ）：声调不同，qǐ 为第三声。意思是企业。"}], "explanations": {"旗": "旗（qí）：挂在杆子上的布制标志。", "七": "七（qī）：声调不同，qī 为第一声。意思是数字七。", "汽": "汽（qì）：声调不同，qì 为第四声。意思是蒸汽、汽车。", "席": "席（xí）：声母不同，x 与 q 的区别。意思是席位、席子。", "集": "集（jí）：声母不同，j 与 q 的区别。意思是集合、集市。", "企": "企（qǐ）：声调不同，qǐ 为第三声。意思是企业。"}, "sentence_index": null, "correct_answer": "旗"}, "level_3": {"options": [{"text": "旗", "is_correct": true, "explanation": "旗：山顶上的标志物，量词“面”，句意合理。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板属于教室，山顶上不会有。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮挂在天上，不会立在山顶上。"}, {"text": "云", "is_correct": false, "explanation": "语义：云飘在天上，不是可以立起来的一面物件，句意不通。"}], "explanations": {"旗": "旗：山顶上的标志物，量词“面”，句意合理。", "黑板": "语义：黑板属于教室，山顶上不会有。", "月亮": "语义：月亮挂在天上，不会立在山顶上。", "云": "语义：云飘在天上，不是可以立起来的一面物件，句意不通。"}, "sentence_index": 6, "correct_answer": "旗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用这面旗切开了一个西瓜。", "explanation": "这里应该用〈刀〉。旗是布做的标志，不能用来切东西；切西瓜要用刀。"}, {"text": "他拿着这面旗吹出了一支曲子。", "explanation": "这里应该用〈笛子〉。旗是挂在杆子上的标志物，不是乐器；吹曲子要用笛子。"}, {"text": "他用旗量出了桌子的长度。", "explanation": "这里应该用〈尺子〉。旗不能用来测量；量桌子的长度要用尺子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教室里挂着一个旗。", "corrected_sentence": "教室里挂着一面旗。", "error_description": "量词错误：旗的量词应为“面”，不能用“个”。正确说法：一面旗。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "操场上飘着一个红旗。", "corrected_sentence": "操场上飘着一面红旗。", "error_description": "量词错误：旗的量词应为“面”，不能用“个”。正确说法：一面红旗。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
