INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93600, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工作职位；工作人员所在的工作位置。", "primary_collocate": null, "pronunciation": "gǎng wèi", "ipa": "kɑŋ˨˩˦ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司有三个空岗位。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想应聘销售岗位。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了一个新岗位。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岗位需要会说英语。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给毕业生提供了很多岗位。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岗位的工资不太高。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在财务岗位工作了五年。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岗位对经验没有要求。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司网站上写着各个岗位的要求。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为喜欢孩子，选了教师岗位。", "target_word": "岗位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "崗位", "label": "繁体"}], "register": "中性", "sense_fingerprint": "单位设置的工作职位，可应聘、可更换", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5996816f-6ae7-41cc-8154-694bc816de42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93600, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "岗位", "is_correct": true, "explanation": "正确：岗位指单位设置的工作职位，“空岗位”符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“空”修饰的是可以空缺的职位，工资不能空缺。"}, {"text": "思想", "is_correct": false, "explanation": "语义：思想不是可以空缺的职位，不能说“三个空思想”。"}, {"text": "毛衣", "is_correct": false, "explanation": "语义：毛衣不能说空缺，句子不通。"}], "explanations": {"岗位": "正确：岗位指单位设置的工作职位，“空岗位”符合句意。", "工资": "语义：“空”修饰的是可以空缺的职位，工资不能空缺。", "思想": "语义：思想不是可以空缺的职位，不能说“三个空思想”。", "毛衣": "语义：毛衣不能说空缺，句子不通。"}, "sentence_index": 0, "correct_answer": "岗位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司冰箱里放着很多岗位，需要冷藏。", "explanation": "这里应该用〈牛奶〉。岗位指工作职位，需要冷藏的是牛奶。"}, {"text": "公司仓库里堆着很多岗位，等待运输。", "explanation": "这里应该用〈货物〉。岗位指工作职位，仓库里堆着、等待运输的是货物。"}, {"text": "公司门口长满了岗位，需要经常修剪。", "explanation": "这里应该用〈草〉。岗位指工作职位，门口长满、需要修剪的是草。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "岗位", "is_correct": true, "explanation": "正确：岗位指工作职位，“财务岗位”符合句意。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：没有“财务公园”的说法，“财务”后应接职位或部门。"}, {"text": "草原", "is_correct": false, "explanation": "语义：草原不是工作单位，不能说在财务草原工作。"}, {"text": "语文", "is_correct": false, "explanation": "搭配：“财务”后应接职位或部门，语文不是。"}], "explanations": {"岗位": "正确：岗位指工作职位，“财务岗位”符合句意。", "公园": "搭配：没有“财务公园”的说法，“财务”后应接职位或部门。", "草原": "语义：草原不是工作单位，不能说在财务草原工作。", "语文": "搭配：“财务”后应接职位或部门，语文不是。"}, "sentence_index": 6, "correct_answer": "岗位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的货架上摆满了岗位，可以随便挑。", "explanation": "这里应该用〈商品〉。岗位指工作职位，货架上摆着、可以挑选的是商品。"}, {"text": "这家公司的橱窗里摆满了岗位，可以试穿。", "explanation": "这里应该用〈衣服〉。岗位指工作职位，橱窗里摆着、可以试穿的是衣服。"}, {"text": "这家公司的冰箱里放满了岗位，随时可以喝。", "explanation": "这里应该用〈饮料〉。岗位指工作职位，冰箱里放着、随时可以喝的是饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司空出了一份岗位。", "corrected_sentence": "公司空出了一个岗位。", "error_description": "错误：量词“份”；正确：“个”。“份”用于文件、食物等，岗位应用“个”，说“一个岗位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他换了一辆财务岗位。", "corrected_sentence": "他换了一个财务岗位。", "error_description": "错误：量词“辆”；正确：“个”。“辆”用于车辆，岗位应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c26786ad-fafc-4703-b82d-4eb6ee724bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
