INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93601, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "早餐是早上吃的饭。", "primary_collocate": null, "pronunciation": "zǎo cān", "ipa": "tsɑʊ̯˨˩ tsʰan˥", "syllable_count": 2, "sentences": [{"text": "我每天早上七点吃早餐。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我做了早餐。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早餐我喝了一杯牛奶。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在家附近的小店买早餐。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的早餐有面包和鸡蛋。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完早餐，我就去上班。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早餐很重要，你不要不吃。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟每天都吃着早餐看电视。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天早上我想吃中式早餐。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店的早餐很好吃。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "顿", "label": "量词"}, {"form": "早餐店", "label": "复合"}], "register": "中性", "sense_fingerprint": "早上吃的饭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55aaaa31-ecfe-4c48-a2a5-b97093244256') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93601, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早餐", "is_correct": true, "explanation": "早餐：指早上吃的饭，与“早上七点”相符。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭在中午吃，与“早上七点”矛盾。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：晚饭在晚上吃，与“早上七点”矛盾。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“吃”不搭配“饮料”，饮料应说“喝”。"}], "explanations": {"早餐": "早餐：指早上吃的饭，与“早上七点”相符。", "午饭": "语义：午饭在中午吃，与“早上七点”矛盾。", "晚饭": "语义：晚饭在晚上吃，与“早上七点”矛盾。", "饮料": "搭配：“吃”不搭配“饮料”，饮料应说“喝”。"}, "sentence_index": 0, "correct_answer": "早餐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天中午在公司吃早餐。", "explanation": "这里应该用〈午饭〉。早餐指早上吃的饭，中午吃的饭要说午饭。"}, {"text": "他在学校门口买了一只早餐。", "explanation": "这里应该用〈份〉或〈顿〉。早餐的量词不说“只”，“只”用于动物或成对物件中的一个。"}, {"text": "他每天深夜在小店吃早餐。", "explanation": "这里应该用〈夜宵〉。早餐指早上吃的饭，深夜吃的东西要说夜宵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93601, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早餐", "is_correct": true, "explanation": "早餐：指早上吃的饭，与“很重要，不要不吃”的语境相符。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是食物，与“你不要不吃”的“吃”不相容。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“吃”不搭配“饮料”，饮料应说“喝”。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能吃，与句中“不吃”的动作不相容。"}], "explanations": {"早餐": "早餐：指早上吃的饭，与“很重要，不要不吃”的语境相符。", "玩具": "语义：玩具不是食物，与“你不要不吃”的“吃”不相容。", "饮料": "搭配：“吃”不搭配“饮料”，饮料应说“喝”。", "书": "语义：书不能吃，与句中“不吃”的动作不相容。"}, "sentence_index": 6, "correct_answer": "早餐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上在家吃早餐。", "explanation": "这里应该用〈晚饭〉。早餐指早上吃的饭，晚上吃的饭要说晚饭。"}, {"text": "他买了一杯早餐。", "explanation": "这里应该用〈份〉或〈顿〉。“杯”用于盛在杯子里的饮品，早餐的量词不说“杯”。"}, {"text": "晚上十一点，我吃了早餐就去睡觉了。", "explanation": "这里应该用〈夜宵〉。早餐指早上吃的饭，深夜睡觉前吃的东西要说夜宵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93601, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只早餐。", "corrected_sentence": "我买了一份早餐。", "error_description": "“早餐”的量词用错：应说“一份早餐”或“一顿早餐”，不能用“只”。“只”用于动物或成对物件中的一个，不用于餐食。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93601, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给我做了一本早餐。", "corrected_sentence": "妈妈给我做了一顿早餐。", "error_description": "“早餐”的量词用错：“本”用于书籍等，不用于早餐，应说“一顿早餐”或“一份早餐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
