INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93602, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "早晨吃的一顿饭。", "primary_collocate": null, "pronunciation": "zǎo cān", "ipa": "tsɑʊ̯˨˩ tsʰan˥", "syllable_count": 2, "sentences": [{"text": "早餐是一天中的第一顿饭。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没吃过这么丰盛的早餐。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把早餐放在桌子上了。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他起得太晚，没来得及吃早餐。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她早上六点就开始做早餐。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早餐吃得好，一整天都有精神。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在学校吃过早餐了。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们早餐吃了什么。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们一家人一起吃早餐。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的早餐通常是豆浆和油条。", "target_word": "早餐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "顿", "label": "量词"}, {"form": "早餐店", "label": "复合"}], "register": "中性", "sense_fingerprint": "早晨的一顿饭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55aaaa31-ecfe-4c48-a2a5-b97093244256') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早餐", "is_correct": true, "explanation": "早餐：指早晨吃的一顿饭，与“一天中的第一顿饭”相符。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭在中午吃，不是一天中的第一顿饭。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：晚饭在晚上吃，不是一天中的第一顿饭。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“一顿”用于饭食，不搭配“饮料”。"}], "explanations": {"早餐": "早餐：指早晨吃的一顿饭，与“一天中的第一顿饭”相符。", "午饭": "语义：午饭在中午吃，不是一天中的第一顿饭。", "晚饭": "语义：晚饭在晚上吃，不是一天中的第一顿饭。", "饮料": "搭配：“一顿”用于饭食，不搭配“饮料”。"}, "sentence_index": 0, "correct_answer": "早餐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸晚上给我们做早餐。", "explanation": "这里应该用〈晚饭〉。早餐指早晨吃的一顿饭，晚上做的饭要说晚饭。"}, {"text": "她买了一本早餐。", "explanation": "这里应该用〈份〉或〈顿〉。“本”用于书籍，早餐的量词不说“本”。"}, {"text": "妈妈递给我一张早餐。", "explanation": "这里应该用〈份〉或〈顿〉。“张”用于纸张、票据等平面的东西，早餐作为一餐不用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早餐", "is_correct": true, "explanation": "早餐：指早上吃的饭，与“在学校吃过了”的语境相符。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“吃”不搭配“饮料”，饮料应说“喝”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能吃，与“吃过”不相容。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不能吃，与“吃过”不相容。"}], "explanations": {"早餐": "早餐：指早上吃的饭，与“在学校吃过了”的语境相符。", "饮料": "搭配：“吃”不搭配“饮料”，饮料应说“喝”。", "玩具": "语义：玩具不能吃，与“吃过”不相容。", "作业": "语义：作业不能吃，与“吃过”不相容。"}, "sentence_index": 6, "correct_answer": "早餐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我常在中午的食堂吃早餐。", "explanation": "这里应该用〈午饭〉。早餐指早晨吃的一顿饭，中午吃的饭要说午饭。"}, {"text": "他递给我一块早餐。", "explanation": "这里应该用〈份〉或〈顿〉。“块”用于块状物，早餐的量词不说“块”。"}, {"text": "他经常深夜吃早餐。", "explanation": "这里应该用〈宵夜〉。早餐指早晨吃的一顿饭，深夜吃的东西要说宵夜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸做了一只早餐。", "corrected_sentence": "爸爸做了一顿早餐。", "error_description": "“早餐”的量词用错：应说“一顿早餐”，不能用“只”。“只”用于动物或成对物件中的一个，不用于餐食。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
