INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93604, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因受到触动而产生同情、感激等情绪。", "primary_collocate": null, "pronunciation": "gǎn dòng", "ipa": "kan˨˩˦ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的话让我很感动。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子送给妈妈一朵花，妈妈很感动。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事感动了很多人。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的善意让大家都很感动。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，我们都感动得哭了。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为朋友做了这么多，朋友非常感动。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影感动过无数观众。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的努力感动了老师。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她感动地对帮助她的人说了谢谢。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱送给我，我真感动，也很感激。", "target_word": "感动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "感动了", "label": "体标"}, {"form": "感动过", "label": "体标"}], "register": "中性", "sense_fingerprint": "感动·动词·受到触动而产生同情、感激等情绪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168ad27f-59af-419a-aeff-3d9250db54ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93604, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感动", "is_correct": true, "explanation": "正确。“让我很感动”表示心里受到触动，符合句意。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：话语不会让人感冒，与句中的“他的话”冲突。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：话语不会引起咳嗽，与句中的因果关系不符。"}, {"text": "迷路", "is_correct": false, "explanation": "搭配：“迷路”是动宾结构，不能直接用“很”修饰。"}], "explanations": {"感动": "正确。“让我很感动”表示心里受到触动，符合句意。", "感冒": "语义：话语不会让人感冒，与句中的“他的话”冲突。", "咳嗽": "语义：话语不会引起咳嗽，与句中的因果关系不符。", "迷路": "搭配：“迷路”是动宾结构，不能直接用“很”修饰。"}, "sentence_index": 0, "correct_answer": "感动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手指感动了一下。", "explanation": "这里应该用〈抽动〉。感动表示受触动产生的情绪，手指的活动应说〈抽动〉。"}, {"text": "他被车撞了，我们都很感动。", "explanation": "这里应该用〈担心〉。感动表示被触动产生的同情、感激，朋友出事时应表示〈担心〉。"}, {"text": "他买了一台电脑，我很感动。", "explanation": "这里应该用〈羡慕〉。感动表示被触动产生的情绪，看到别人买东西应说〈羡慕〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感动", "is_correct": true, "explanation": "正确。“感动过”表示经历过被感动，符合“无数观众”的语境。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：电影不能喂养观众，与句意冲突。"}, {"text": "招待", "is_correct": false, "explanation": "搭配：“招待”的对象多为客人，一般不说电影招待观众。"}, {"text": "关闭", "is_correct": false, "explanation": "语义：电影不能关闭观众，与句中的“观众”不搭配。"}], "explanations": {"感动": "正确。“感动过”表示经历过被感动，符合“无数观众”的语境。", "喂养": "语义：电影不能喂养观众，与句意冲突。", "招待": "搭配：“招待”的对象多为客人，一般不说电影招待观众。", "关闭": "语义：电影不能关闭观众，与句中的“观众”不搭配。"}, "sentence_index": 6, "correct_answer": "感动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个笑话让我很感动。", "explanation": "这里应该用〈好笑〉。感动表示受触动产生的情绪，笑话让人发笑应说〈好笑〉。"}, {"text": "这次考试我很感动。", "explanation": "这里应该用〈失望〉。感动表示受触动，不表示考试失利后的失落。"}, {"text": "天气太冷，我很感动。", "explanation": "这里应该用〈难受〉。感动表示心里发热的情绪，天气太冷应说〈难受〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师的话让我特地感动。", "corrected_sentence": "老师的话让我特别感动。", "error_description": "程度副词错误：“感动”前应用程度副词“特别”，“特地”表示专门、有意，不能修饰“感动”。正确形式：老师的话让我特别感动。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那次演讲感动了过很多人。", "corrected_sentence": "那次演讲感动过很多人。", "error_description": "体标错误：“感动过”中的“过”表示经历，“了”不能插在“感动”和“过”之间。正确形式：那次演讲感动过很多人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
