INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93605, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "月报是每个月写一次或出一次的报告。", "primary_collocate": null, "pronunciation": "yuè bào", "ipa": "ɥe˥˩ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我每个月都要写一份月报。", "target_word": "月报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月报要在月底以前交给老师。", "target_word": "月报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的月报写得又清楚又短。", "target_word": "月报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的月报我还没写完。", "target_word": "月报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要我们在月报里写下工作情况。", "target_word": "月报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把这个月的事情都写进了月报。", "target_word": "月报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看过上个月的月报吗？", "target_word": "月报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月报里要写这个月做了什么。", "target_word": "月报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上我一直在改月报。", "target_word": "月报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们的月报都放在桌子上。", "target_word": "月报", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "月報", "label": "繁体"}], "register": "中性", "sense_fingerprint": "每月写一次的工作报告", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f40a4c9d-1fd0-4de3-94d1-c63055ba03a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93605, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日报", "is_correct": false, "explanation": "语义：日报是每天一次的，与“每个月”矛盾。"}, {"text": "月报", "is_correct": true, "explanation": "“每个月都要写”的工作报告，填“月报”。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：“写一份”用于文字材料，不说“写一份手套”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是文字材料，不能“写”。"}], "explanations": {"日报": "语义：日报是每天一次的，与“每个月”矛盾。", "月报": "“每个月都要写”的工作报告，填“月报”。", "手套": "搭配：“写一份”用于文字材料，不说“写一份手套”。", "蛋糕": "语义：蛋糕不是文字材料，不能“写”。"}, "sentence_index": 0, "correct_answer": "月报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都要写月报。", "explanation": "这里应该用〈日报〉。月报是每月一次，“每天都要写”应用日报。"}, {"text": "他在海边坐了一下午，写了一份月报，描写海浪的样子。", "explanation": "这里应该用〈散文〉。月报是记录工作情况的报告，用来描写海浪的应是散文。"}, {"text": "公司每年都要写一份月报。", "explanation": "这里应该用〈年报〉。月报每月一次，每年写一次的应是年报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0eb0521e-f62e-46f3-9f9f-cc04980c6a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93605, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月饼", "is_correct": false, "explanation": "搭配：“看过”多用于报刊、文件，不说“看过月饼”。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是物品，没有可以“看”的内容。"}, {"text": "戒指", "is_correct": false, "explanation": "语义：戒指不是可以阅读的材料，这里讲的是“看”文件。"}, {"text": "月报", "is_correct": true, "explanation": "“上个月的”定期材料，可以“看过”，填“月报”。"}], "explanations": {"月饼": "搭配：“看过”多用于报刊、文件，不说“看过月饼”。", "雨伞": "语义：雨伞是物品，没有可以“看”的内容。", "戒指": "语义：戒指不是可以阅读的材料，这里讲的是“看”文件。", "月报": "“上个月的”定期材料，可以“看过”，填“月报”。"}, "sentence_index": 6, "correct_answer": "月报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里写了一份月报，记下了新菜的做法。", "explanation": "这里应该用〈菜谱〉。月报是工作报告，记录菜的做法的应是菜谱。"}, {"text": "他写了一份月报，记录自己的心情。", "explanation": "这里应该用〈日记〉。月报记录工作情况，记录心情的应是日记。"}, {"text": "孩子在作文课上写了一份月报。", "explanation": "这里应该用〈作文〉。月报是工作报告，作文课上写的应是作文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0eb0521e-f62e-46f3-9f9f-cc04980c6a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只月报我已经写完了。", "corrected_sentence": "这份月报我已经写完了。", "error_description": "量词错误：“月报”是文字材料，应用“份”；“只”用于动物等，不用于文件，应为“这份月报”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0eb0521e-f62e-46f3-9f9f-cc04980c6a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我写过一只月报。", "corrected_sentence": "我写过一份月报。", "error_description": "量词错误：“月报”应用“份”，“只”不用于文件，应为“我写过一份月报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0eb0521e-f62e-46f3-9f9f-cc04980c6a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
