INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93607, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手里是在手掌心里面。", "primary_collocate": null, "pronunciation": "shǒu lǐ", "ipa": "ʂoʊ˨˩˦ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "他手里拿着一杯热茶。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩手里有一个红苹果。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我手里的伞被风吹坏了。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她手里抱着一只小猫。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师手里拿着一本新书。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钥匙放在手里看了看。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈手里提着两个大袋子。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟手里握着一枚硬币。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手里的冰淇淋化了。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你手里拿的是什么东西？", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "手裡", "label": "繁体"}], "register": "口语", "sense_fingerprint": "手掌心里面，指手中拿着或握着东西的具体位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8eb21289-7e21-4025-8e45-bb69550d4010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93607, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手里", "is_correct": true, "explanation": "正确答案：手里（shǒu lǐ）指手掌心里面。"}, {"text": "收礼", "is_correct": false, "explanation": "shōu（第一声）与 shǒu（第三声）声调不同，意思是收受礼物。"}, {"text": "手洗", "is_correct": false, "explanation": "lǐ 与 xǐ 声母不同，意思是用手清洗。"}, {"text": "手笔", "is_correct": false, "explanation": "lǐ 与 bǐ 声母不同，意思是亲笔写的字迹或文笔。"}, {"text": "水里", "is_correct": false, "explanation": "shǒu 与 shuǐ 的韵母不同，意思是在水中。"}], "explanations": {"手里": "正确答案：手里（shǒu lǐ）指手掌心里面。", "收礼": "shōu（第一声）与 shǒu（第三声）声调不同，意思是收受礼物。", "手洗": "lǐ 与 xǐ 声母不同，意思是用手清洗。", "手笔": "lǐ 与 bǐ 声母不同，意思是亲笔写的字迹或文笔。", "水里": "shǒu 与 shuǐ 的韵母不同，意思是在水中。"}, "sentence_index": null, "correct_answer": "手里"}, "level_3": {"options": [{"text": "手里", "is_correct": true, "explanation": "正确答案：“手里”指握在手掌中，与“拿着一杯热茶”相合。"}, {"text": "桌上", "is_correct": false, "explanation": "搭配：“拿着”的持物者应是手，不能说“桌上拿着一杯热茶”。"}, {"text": "地上", "is_correct": false, "explanation": "语义：“地上”指地面，人不能在地上拿着热茶。"}, {"text": "包里", "is_correct": false, "explanation": "语义：“包里”指袋子里面，不能说人在包里拿着茶杯。"}], "explanations": {"手里": "正确答案：“手里”指握在手掌中，与“拿着一杯热茶”相合。", "桌上": "搭配：“拿着”的持物者应是手，不能说“桌上拿着一杯热茶”。", "地上": "语义：“地上”指地面，人不能在地上拿着热茶。", "包里": "语义：“包里”指袋子里面，不能说人在包里拿着茶杯。"}, "sentence_index": 0, "correct_answer": "手里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他手里戴着一块手表。", "explanation": "这里应该用〈手上〉。戴手表是戴在手腕上，“手里”指握在掌中的东西，不能说“手里戴着”。"}, {"text": "他手里流着眼泪。", "explanation": "这里应该用〈眼里〉。眼泪是从眼睛里流出来的，“手里”指握在掌中的东西，不能说“手里流着眼泪”。"}, {"text": "他手里含着一块糖。", "explanation": "这里应该用〈嘴里〉。含东西是在口中，“手里”指握在手掌中，不能说“手里含着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93607, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手里", "is_correct": true, "explanation": "正确答案：手里（shǒu lǐ）指手掌心里面。"}, {"text": "寿礼", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是祝寿的礼物。"}, {"text": "受理", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受并处理案件或申请。"}, {"text": "受礼", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受礼物。"}, {"text": "手底", "is_correct": false, "explanation": "lǐ 与 dǐ 声母不同，意思是手下、能力所及的范围。"}], "explanations": {"手里": "正确答案：手里（shǒu lǐ）指手掌心里面。", "寿礼": "shòu（第四声）与 shǒu（第三声）声调不同，意思是祝寿的礼物。", "受理": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受并处理案件或申请。", "受礼": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受礼物。", "手底": "lǐ 与 dǐ 声母不同，意思是手下、能力所及的范围。"}, "sentence_index": null, "correct_answer": "手里"}, "level_3": {"options": [{"text": "手里", "is_correct": true, "explanation": "正确答案：“手里”指握在手中，与“提着两个大袋子”相合。"}, {"text": "怀里", "is_correct": false, "explanation": "搭配：“提着”需要用手，不能说“怀里提着”。"}, {"text": "脑子里", "is_correct": false, "explanation": "语义：“脑子里”指头脑中，不能说人在脑子里提着东西。"}, {"text": "口袋里", "is_correct": false, "explanation": "语义：口袋装不下两个大袋子，“口袋里提着”不通。"}], "explanations": {"手里": "正确答案：“手里”指握在手中，与“提着两个大袋子”相合。", "怀里": "搭配：“提着”需要用手，不能说“怀里提着”。", "脑子里": "语义：“脑子里”指头脑中，不能说人在脑子里提着东西。", "口袋里": "语义：口袋装不下两个大袋子，“口袋里提着”不通。"}, "sentence_index": 6, "correct_answer": "手里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事我一直记在手里。", "explanation": "这里应该用〈脑子里〉。记在脑中指记住，“手里”指握在掌中的东西，不能说“记在手里”。"}, {"text": "他手里装着一箱书。", "explanation": "这里应该用〈箱子里〉。装是把东西放在容器内，“手里”指握在掌中，不能作容器，不能说“手里装着一箱书”。"}, {"text": "他的心情都写在手里。", "explanation": "这里应该用〈脸上〉。心情写在脸上，“手里”不能指表情显露的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93607, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶把手里拿着一把扇子。", "corrected_sentence": "奶奶手里拿着一把扇子。", "error_description": "多余的“把”：“把”须引出被处置的受事宾语，而“手里”是方位词，不能作“把”的宾语；去掉“把”，说“奶奶手里拿着一把扇子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93607, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈手里的拿着一把伞。", "corrected_sentence": "妈妈手里拿着一把伞。", "error_description": "“手里”后多加了“的”：“手里”作状语修饰“拿着”，应说“妈妈手里拿着一把伞”，加“的”会使“手里的”变成定语，与动词连用不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
