INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93608, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "手中；手的掌握之中。", "primary_collocate": null, "pronunciation": "shǒu lǐ", "ipa": "ʂoʊ˨˩˦ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司的大权在他手里。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事现在在经理手里。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的股票大多在他手里。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的结果就在你们手里。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店现在落到别人手里了。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些消息现在都在他手里。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的未来在父母手里。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文件已经到了警察手里。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后的机会在我们手里。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个决定现在在老板手里。", "target_word": "手里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "手裡", "label": "繁体"}], "register": "口语", "sense_fingerprint": "比喻掌握、控制、归属于某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8eb21289-7e21-4025-8e45-bb69550d4010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93608, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手里", "is_correct": true, "explanation": "正确答案：手里（shǒu lǐ），这里指在某人的掌握、控制之中。"}, {"text": "收礼", "is_correct": false, "explanation": "shōu（第一声）与 shǒu（第三声）声调不同，意思是收受礼物。"}, {"text": "手洗", "is_correct": false, "explanation": "lǐ 与 xǐ 声母不同，意思是用手清洗。"}, {"text": "手笔", "is_correct": false, "explanation": "lǐ 与 bǐ 声母不同，意思是亲笔写的字迹或文笔。"}, {"text": "水里", "is_correct": false, "explanation": "shǒu 与 shuǐ 的韵母不同，意思是在水中。"}], "explanations": {"手里": "正确答案：手里（shǒu lǐ），这里指在某人的掌握、控制之中。", "收礼": "shōu（第一声）与 shǒu（第三声）声调不同，意思是收受礼物。", "手洗": "lǐ 与 xǐ 声母不同，意思是用手清洗。", "手笔": "lǐ 与 bǐ 声母不同，意思是亲笔写的字迹或文笔。", "水里": "shǒu 与 shuǐ 的韵母不同，意思是在水中。"}, "sentence_index": null, "correct_answer": "手里"}, "level_3": {"options": [{"text": "手里", "is_correct": true, "explanation": "正确答案：“手里”表示掌握、控制在某人之中，与“公司的大权”相合。"}, {"text": "脑子里", "is_correct": false, "explanation": "语义：大权是实际掌控，不能说装在他脑子里。"}, {"text": "口袋里", "is_correct": false, "explanation": "语义：公司的大权不能装在口袋里。"}, {"text": "眼里", "is_correct": false, "explanation": "搭配：“在……眼里”表示看法，不能说权力在眼里。"}], "explanations": {"手里": "正确答案：“手里”表示掌握、控制在某人之中，与“公司的大权”相合。", "脑子里": "语义：大权是实际掌控，不能说装在他脑子里。", "口袋里": "语义：公司的大权不能装在口袋里。", "眼里": "搭配：“在……眼里”表示看法，不能说权力在眼里。"}, "sentence_index": 0, "correct_answer": "手里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的话我一直记在手里。", "explanation": "这里应该用〈心里〉。“记在心里”表示牢记，“手里”表示掌握或控制，不能说“记在手里”。"}, {"text": "他手里生了一场大病。", "explanation": "这里应该用〈身上〉。生病是病在身体内，“手里”表示掌握、控制，不能指身体患病的位置。"}, {"text": "这件事他手里一直想着。", "explanation": "这里应该用〈脑子里〉。想是在头脑中进行，“手里”不能指思考的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93608, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手里", "is_correct": true, "explanation": "正确答案：手里（shǒu lǐ），这里指在某人的掌握、控制之中。"}, {"text": "寿礼", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是祝寿的礼物。"}, {"text": "受理", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受并处理案件或申请。"}, {"text": "受礼", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受礼物。"}, {"text": "手底", "is_correct": false, "explanation": "lǐ 与 dǐ 声母不同，意思是手下、能力所及的范围。"}], "explanations": {"手里": "正确答案：手里（shǒu lǐ），这里指在某人的掌握、控制之中。", "寿礼": "shòu（第四声）与 shǒu（第三声）声调不同，意思是祝寿的礼物。", "受理": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受并处理案件或申请。", "受礼": "shòu（第四声）与 shǒu（第三声）声调不同，意思是接受礼物。", "手底": "lǐ 与 dǐ 声母不同，意思是手下、能力所及的范围。"}, "sentence_index": null, "correct_answer": "手里"}, "level_3": {"options": [{"text": "手里", "is_correct": true, "explanation": "正确答案：“手里”表示掌握在父母之中，与“孩子的未来”相合。"}, {"text": "冰箱里", "is_correct": false, "explanation": "语义：未来不能存放在冰箱里。"}, {"text": "抽屉里", "is_correct": false, "explanation": "语义：未来不能放在抽屉里。"}, {"text": "脸上", "is_correct": false, "explanation": "体貌：“脸上”指面部，未来不在父母的脸上。"}], "explanations": {"手里": "正确答案：“手里”表示掌握在父母之中，与“孩子的未来”相合。", "冰箱里": "语义：未来不能存放在冰箱里。", "抽屉里": "语义：未来不能放在抽屉里。", "脸上": "体貌：“脸上”指面部，未来不在父母的脸上。"}, "sentence_index": 6, "correct_answer": "手里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们都在手里。", "explanation": "这里应该用〈家里〉。“手里”表示掌握、控制，不能指人所在的处所，不能说“孩子们都在手里”。"}, {"text": "他手里说了一句话。", "explanation": "这里应该用〈嘴里〉。说话是用嘴，“手里”表示掌握、控制，不能指说话的位置。"}, {"text": "这份渴望写在他手里。", "explanation": "这里应该用〈眼里〉。渴望要在眼神中流露，“手里”不能指表情显露的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔钱现在会计手里。", "corrected_sentence": "这笔钱现在在会计手里。", "error_description": "漏掉介词“在”：应说“在会计手里”，缺“在”则“现在会计手里”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份合同的签字权经理手里。", "corrected_sentence": "这份合同的签字权在经理手里。", "error_description": "漏掉介词“在”：应说“在经理手里”，缺“在”则“经理手里”不能作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68d7de29-b264-4f0f-812e-a378a075c2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93609, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无罪", "is_correct": true, "explanation": "反义：“有罪”与“无罪”正相对，指是否犯了罪行。"}, {"text": "高兴", "is_correct": false, "explanation": "无反义关系：“高兴”说心情，与罪行无关。"}, {"text": "聪明", "is_correct": false, "explanation": "无反义关系：“聪明”形容智力，与罪行无关。"}, {"text": "干净", "is_correct": false, "explanation": "无反义关系：“干净”指洁净，不指罪行。"}], "correct_answer": "无罪", "explanations": {"无罪": "反义：“有罪”与“无罪”正相对，指是否犯了罪行。", "高兴": "无反义关系：“高兴”说心情，与罪行无关。", "聪明": "无反义关系：“聪明”形容智力，与罪行无关。", "干净": "无反义关系：“干净”指洁净，不指罪行。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93609, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无罪", "is_correct": true, "explanation": "反义：“有罪”与“无罪”正相对，指是否犯了罪行。"}, {"text": "漂亮", "is_correct": false, "explanation": "无反义关系：“漂亮”形容外貌，与罪行无关。"}, {"text": "热闹", "is_correct": false, "explanation": "无反义关系：“热闹”形容场面，与罪行无关。"}, {"text": "安静", "is_correct": false, "explanation": "无反义关系：“安静”形容声音或心情，不与罪行相对。"}], "correct_answer": "无罪", "explanations": {"无罪": "反义：“有罪”与“无罪”正相对，指是否犯了罪行。", "漂亮": "无反义关系：“漂亮”形容外貌，与罪行无关。", "热闹": "无反义关系：“热闹”形容场面，与罪行无关。", "安静": "无反义关系：“安静”形容声音或心情，不与罪行相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93609, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有罪是做了坏事，犯了法。", "primary_collocate": null, "pronunciation": "yǒu zuì", "ipa": "iou˨˩ tsuei˥˩", "syllable_count": 2, "sentences": [{"text": "小偷偷了东西，所以他有罪。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在法庭上承认自己有罪。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说这个人有罪，要带他走。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骗了很多人的钱，法官说他有罪。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他知道自己有罪，不敢看警察。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁有罪，谁就要受到法律的处罚。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他撞了人还跑了，法院认为他有罪。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说那个坏人有罪。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有罪，所以要在监狱里待五年。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问：他做了什么，为什么有罪？", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "做了坏事、犯了法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b69c20c8-55e0-48cc-a4ad-ae6e68dd460f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93609, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清白", "is_correct": false, "explanation": "语义：“清白”指没有过错，与“小偷偷了东西”相反，句子不通。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外貌，不能因偷东西而说一个人漂亮。"}, {"text": "有罪", "is_correct": true, "explanation": "正确：偷东西是做了坏事，“有罪”与“所以”的因果相合。"}, {"text": "无罪", "is_correct": false, "explanation": "语义：“无罪”与“小偷偷了东西，所以”矛盾，偷东西的人不能说无罪。"}], "explanations": {"清白": "语义：“清白”指没有过错，与“小偷偷了东西”相反，句子不通。", "漂亮": "语义：“漂亮”形容外貌，不能因偷东西而说一个人漂亮。", "有罪": "正确：偷东西是做了坏事，“有罪”与“所以”的因果相合。", "无罪": "语义：“无罪”与“小偷偷了东西，所以”矛盾，偷东西的人不能说无罪。"}, "sentence_index": 0, "correct_answer": "有罪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把约会的时间说错了，他有罪，应该道歉。", "explanation": "这里应该用〈有错〉。有罪指犯了法，说错时间这种小过失只说有错。"}, {"text": "他在考场上拿了第一名，有罪，应该受到表扬。", "explanation": "这里应该用〈有功〉。有罪指做了坏事、犯了法；考第一名值得表扬，不说有罪。"}, {"text": "他在作业上犯了一个错，有罪，老师让他重做。", "explanation": "这里应该用〈疏忽〉。有罪指犯法，作业上的小过错只能算疏忽，不说有罪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93609, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年龄，不能用来判定他是否犯了法。"}, {"text": "有名", "is_correct": false, "explanation": "搭配：“有名”说名声，不能与“法院认为”搭配作判定。"}, {"text": "无辜", "is_correct": false, "explanation": "语义：“无辜”与“撞了人还跑了”矛盾，肇事逃逸者不能说无辜。"}, {"text": "有罪", "is_correct": true, "explanation": "正确：撞人后逃跑是犯法行为，“法院认为他有罪”与前句事实相合。"}], "explanations": {"年轻": "语义：“年轻”说年龄，不能用来判定他是否犯了法。", "有名": "搭配：“有名”说名声，不能与“法院认为”搭配作判定。", "无辜": "语义：“无辜”与“撞了人还跑了”矛盾，肇事逃逸者不能说无辜。", "有罪": "正确：撞人后逃跑是犯法行为，“法院认为他有罪”与前句事实相合。"}, "sentence_index": 6, "correct_answer": "有罪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在比赛里有罪，球队因此输了。", "explanation": "这里应该用〈失误〉。有罪指犯法，体育比赛中的失误只说失误。"}, {"text": "这次计算他有罪，老师让他重做。", "explanation": "这里应该用〈出错〉。有罪指犯法，计算出错只是小过失。"}, {"text": "他在课堂上大声说话，有罪。", "explanation": "这里应该用〈违纪〉。有罪只指触犯法律；课堂上大声说话属于违纪，由学校处理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93609, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他偷了别人的钱，所以他不有罪。", "corrected_sentence": "他偷了别人的钱，所以他有罪。", "error_description": "“有罪”的否定不能说“不有罪”，要说“没有罪”或“无罪”；“不”不能直接放在动词“有”前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93609, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他撞了人还逃跑，法院认定他很有罪。", "corrected_sentence": "他撞了人还逃跑，法院认定他有罪。", "error_description": "“有罪”是法院认定的结果，不能用“很”修饰。应说“法院认定他有罪”，不说“很有罪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93610, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无罪", "is_correct": true, "explanation": "反义：“有罪”与“无罪”正相对，指是否犯了罪行。"}, {"text": "漂亮", "is_correct": false, "explanation": "无反义关系：“漂亮”形容外貌，不指是否犯罪。"}, {"text": "聪明", "is_correct": false, "explanation": "无反义关系：“聪明”形容智力，与法律判定无关。"}, {"text": "干净", "is_correct": false, "explanation": "无反义关系：“干净”指洁净，不指罪行。"}], "correct_answer": "无罪", "explanations": {"无罪": "反义：“有罪”与“无罪”正相对，指是否犯了罪行。", "漂亮": "无反义关系：“漂亮”形容外貌，不指是否犯罪。", "聪明": "无反义关系：“聪明”形容智力，与法律判定无关。", "干净": "无反义关系：“干净”指洁净，不指罪行。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93610, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无罪", "is_correct": true, "explanation": "反义：“有罪”与“无罪”正相对，指是否犯了罪行。"}, {"text": "高兴", "is_correct": false, "explanation": "无反义关系：“高兴”说心情，与罪行无关。"}, {"text": "热闹", "is_correct": false, "explanation": "无反义关系：“热闹”形容场面，与罪行无关。"}, {"text": "安静", "is_correct": false, "explanation": "无反义关系：“安静”形容声音或心情，不与罪行相对。"}], "correct_answer": "无罪", "explanations": {"无罪": "反义：“有罪”与“无罪”正相对，指是否犯了罪行。", "高兴": "无反义关系：“高兴”说心情，与罪行无关。", "热闹": "无反义关系：“热闹”形容场面，与罪行无关。", "安静": "无反义关系：“安静”形容声音或心情，不与罪行相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93610, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "犯有罪行的；有违法行为的。", "primary_collocate": null, "pronunciation": "yǒu zuì", "ipa": "iou˨˩ tsuei˥˩", "syllable_count": 2, "sentences": [{"text": "法院判定他有罪，要关五年。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "证据很多，证明被告有罪。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官说他有罪，他低下了头。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陪审团一致认为他有罪。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承认自己有罪，向大家道歉。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁有罪，要由法院来决定。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商人有罪，因为他偷税漏税。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法庭宣布这位官员有罪。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有证据，法院不能说他有罪。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己没有罪，可是法官认为他有罪。", "target_word": "有罪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "犯有罪行、有违法行为的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b69c20c8-55e0-48cc-a4ad-ae6e68dd460f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93610, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无罪", "is_correct": false, "explanation": "语义：“无罪”与“要关五年”矛盾，法院判定无罪就不会关押，句子不通。"}, {"text": "有罪", "is_correct": true, "explanation": "正确：“有罪”是法院判定的结果，与“判定他”和“要关五年”相合。"}, {"text": "有名", "is_correct": false, "explanation": "搭配：“有名”说的是名声，不能与“判定”和“要关五年”搭配。"}, {"text": "有趣", "is_correct": false, "explanation": "语义：“有趣”说的是好玩，不能用来描述法院判定的结果。"}], "explanations": {"无罪": "语义：“无罪”与“要关五年”矛盾，法院判定无罪就不会关押，句子不通。", "有罪": "正确：“有罪”是法院判定的结果，与“判定他”和“要关五年”相合。", "有名": "搭配：“有名”说的是名声，不能与“判定”和“要关五年”搭配。", "有趣": "语义：“有趣”说的是好玩，不能用来描述法院判定的结果。"}, "sentence_index": 0, "correct_answer": "有罪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把会议时间记错了，他有罪，应该向大家道歉。", "explanation": "这里应该用〈有错〉。有罪指犯法、被判罪，忘记会议时间这类小过失只说有错。"}, {"text": "他帮老人过了马路，有罪，应该得到表扬。", "explanation": "这里应该用〈有功〉。有罪指违法或做坏事；帮老人过马路是好事，不说有罪。"}, {"text": "这次争论他有罪，我们都同意他的看法。", "explanation": "这里应该用〈有理〉。有罪指犯法；争论中道理站得住只说有理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93610, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外貌，不能用来判断一个商人是否犯罪。"}, {"text": "有罪", "is_correct": true, "explanation": "正确：偷税漏税构成罪行，“有罪”与“因为他偷税漏税”的原因相合。"}, {"text": "无辜", "is_correct": false, "explanation": "语义：“无辜”与“因为他偷税漏税”矛盾，偷税者不能说无辜。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年龄，与“因为他偷税漏税”的因果不合。"}], "explanations": {"漂亮": "语义：“漂亮”形容外貌，不能用来判断一个商人是否犯罪。", "有罪": "正确：偷税漏税构成罪行，“有罪”与“因为他偷税漏税”的原因相合。", "无辜": "语义：“无辜”与“因为他偷税漏税”矛盾，偷税者不能说无辜。", "年轻": "语义：“年轻”说年龄，与“因为他偷税漏税”的因果不合。"}, "sentence_index": 6, "correct_answer": "有罪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在考试中有罪，老师很生气。", "explanation": "这里应该用〈犯错〉。有罪指触犯法律被判罪，考试出错只说犯错。"}, {"text": "他在课堂上玩手机，有罪了。", "explanation": "这里应该用〈违纪〉。有罪只用于触犯法律的情形；课堂上玩手机属于违纪，由学校处理。"}, {"text": "他在比赛里有罪，裁判吹了哨。", "explanation": "这里应该用〈犯规〉。有罪指犯法；比赛中违反规则只说犯规，由裁判吹哨判罚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "证据确凿，法院认定他很有罪。", "corrected_sentence": "证据确凿，法院认定他有罪。", "error_description": "“有罪”是对是否犯罪的判定，不能用“很”修饰程度。应说“法院认定他有罪”，不说“很有罪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不有罪，所以法官放了他。", "corrected_sentence": "他没有罪，所以法官放了他。", "error_description": "“有”是动词，否定要用“没有”，应说“没有罪”，不能说“不有罪”；“不”不能直接用在动词“有”前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93612, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
