INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93612, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "收到；得到别人传来的东西或消息。", "primary_collocate": null, "pronunciation": "jiē dào", "ipa": "tɕjɛ˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我昨天接到了一封信。", "target_word": "接到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她接到朋友的电话，很高兴。", "target_word": "接到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理接到客人的消息就走了。", "target_word": "接到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还没接到学校的通知。", "target_word": "接到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天早上接到一个好消息。", "target_word": "接到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你接到我发的邮件了吗？", "target_word": "接到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们接到了老师的邀请。", "target_word": "接到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王接到家里的电话，马上回去了。", "target_word": "接到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没接到过这样的信。", "target_word": "接到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们接到通知，下午要开会。", "target_word": "接到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "接到了", "label": "完成体 了"}, {"form": "接到过", "label": "经历体 过"}], "register": "中性", "sense_fingerprint": "收到别人传来的电话、信件、通知或消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdffcdca-4576-4326-9e48-c5ba571a4003') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93612, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "接到", "is_correct": true, "explanation": "正确：“接到”指收到别人传来的东西或消息。"}, {"text": "借到", "is_correct": false, "explanation": "声调不同：“借到”（jiè dào，第四声）与“接到”（jiē dào，第一声）声调不同，意思是借得。"}, {"text": "借道", "is_correct": false, "explanation": "声调不同：“借道”（jiè dào，第四声）与“接到”（jiē dào，第一声）声调不同，意思是借路通过。"}, {"text": "接报", "is_correct": false, "explanation": "声母不同：“接报”的“报”（bào）与“到”（dào）声母不同，意思是接到报告。"}], "explanations": {"接到": "正确：“接到”指收到别人传来的东西或消息。", "借到": "声调不同：“借到”（jiè dào，第四声）与“接到”（jiē dào，第一声）声调不同，意思是借得。", "借道": "声调不同：“借道”（jiè dào，第四声）与“接到”（jiē dào，第一声）声调不同，意思是借路通过。", "接报": "声母不同：“接报”的“报”（bào）与“到”（dào）声母不同，意思是接到报告。"}, "sentence_index": null, "correct_answer": "接到"}, "level_3": {"options": [{"text": "接到", "is_correct": true, "explanation": "正确：“接到”表示收到，宾语是“一封信”，符合句意。"}, {"text": "跑到", "is_correct": false, "explanation": "语义：“跑到”表示跑着到达某处，后面要接地点，不能接“一封信”。"}, {"text": "放到", "is_correct": false, "explanation": "配价：“放到”需要说明放置的地点，句中没有地点，且语义不符。"}, {"text": "写到", "is_correct": false, "explanation": "语义：“写到”表示写的内容涉及某处，不能与“一封信”搭配表示收到信件。"}], "explanations": {"接到": "正确：“接到”表示收到，宾语是“一封信”，符合句意。", "跑到": "语义：“跑到”表示跑着到达某处，后面要接地点，不能接“一封信”。", "放到": "配价：“放到”需要说明放置的地点，句中没有地点，且语义不符。", "写到": "语义：“写到”表示写的内容涉及某处，不能与“一封信”搭配表示收到信件。"}, "sentence_index": 0, "correct_answer": "接到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把钥匙接到了口袋里。", "explanation": "这里应该用〈放〉。“接到”表示收到，不能表示把东西放进某处。"}, {"text": "我把礼物接到了朋友家。", "explanation": "这里应该用〈送到〉。“接到”表示收到，不能表示把礼物送往某处。"}, {"text": "老师把通知接到了每个人手里。", "explanation": "这里应该用〈送到〉。“接到”强调收到，不能表示把东西送到某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接到", "is_correct": true, "explanation": "正确：“接到”表示收到，符合“我们接到了老师的邀请”的语义。"}, {"text": "发出", "is_correct": false, "explanation": "语义：“发出”表示送出去，但邀请是老师发来的，我们不能“发出”老师的邀请。"}, {"text": "寄出", "is_correct": false, "explanation": "语义：“寄出”表示寄送出去，与“老师的邀请”的来源不符。"}, {"text": "放到", "is_correct": false, "explanation": "配价：“放到”需要说明放置的地点，句中没有地点，且语义不符。"}], "explanations": {"接到": "正确：“接到”表示收到，符合“我们接到了老师的邀请”的语义。", "发出": "语义：“发出”表示送出去，但邀请是老师发来的，我们不能“发出”老师的邀请。", "寄出": "语义：“寄出”表示寄送出去，与“老师的邀请”的来源不符。", "放到": "配价：“放到”需要说明放置的地点，句中没有地点，且语义不符。"}, "sentence_index": 6, "correct_answer": "接到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校接到我们下午开会。", "explanation": "这里应该用〈通知〉。“接到”的宾语是收到的东西或消息，不能接一个动作的内容。"}, {"text": "我把信接到了他家。", "explanation": "这里应该用〈寄到〉。“接到”表示收到，不能表示把信寄往某处。"}, {"text": "天上接到了一场大雨。", "explanation": "这里应该用〈下〉。“接到”表示收到，不能表示天上降下雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天没接到了老师的电话。", "corrected_sentence": "他昨天没接到老师的电话。", "error_description": "错误：“没接到了”多了“了”。“没”否定已发生的动作时，句末不能再加“了”，应去掉“了”，改为“没接到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天不接到老师的电话，很着急。", "corrected_sentence": "他昨天没接到老师的电话，很着急。", "error_description": "错误：过去没有发生的事应用“没”，不能用“不”。“不接到”应为“没接到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93613, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "虚假", "is_correct": true, "explanation": "虚假与“毫不虚假”正相反，是本真的反义词。"}, {"text": "勇敢", "is_correct": false, "explanation": "勇敢形容胆量，与本真的真实性无关，不构成反义。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速形容速度，与本真的含义无关，不构成反义。"}, {"text": "厚重", "is_correct": false, "explanation": "厚重形容质地或分量，与本真没有反义关系。"}], "correct_answer": "虚假", "explanations": {"虚假": "虚假与“毫不虚假”正相反，是本真的反义词。", "勇敢": "勇敢形容胆量，与本真的真实性无关，不构成反义。", "迅速": "迅速形容速度，与本真的含义无关，不构成反义。", "厚重": "厚重形容质地或分量，与本真没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0eb0521e-f62e-46f3-9f9f-cc04980c6a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
