INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93613, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "本真是一点不假，本来的样子。", "primary_collocate": null, "pronunciation": "běn zhēn", "ipa": "pən˨˩˦ ʈʂən˥", "syllable_count": 2, "sentences": [{"text": "她笑起来很本真。", "target_word": "本真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的心很本真。", "target_word": "本真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的生活还很本真。", "target_word": "本真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话很本真，从不骗人。", "target_word": "本真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢本真的人。", "target_word": "本真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片拍出了她本真的样子。", "target_word": "本真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌唱得很本真。", "target_word": "本真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的生活简单又本真。", "target_word": "本真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想活得更本真一些。", "target_word": "本真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画里的山水看起来很本真。", "target_word": "本真", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "毫不虚假、保持本来的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f40a4c9d-1fd0-4de3-94d1-c63055ba03a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93613, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本真", "is_correct": true, "explanation": "本真：毫不虚假，符合她笑起来自然、不做作的样子。"}, {"text": "宽阔", "is_correct": false, "explanation": "语义：宽阔形容面积或空间大，不能形容笑的样子。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：潮湿形容空气或物体含水多，不能形容笑的样子。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：矮小描述身材，不能用来形容笑起来的样子。"}], "explanations": {"本真": "本真：毫不虚假，符合她笑起来自然、不做作的样子。", "宽阔": "语义：宽阔形容面积或空间大，不能形容笑的样子。", "潮湿": "语义：潮湿形容空气或物体含水多，不能形容笑的样子。", "矮小": "体貌：矮小描述身材，不能用来形容笑起来的样子。"}, "sentence_index": 0, "correct_answer": "本真"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条新闻很本真。", "explanation": "这里应该用〈真实〉。本真强调不加修饰、保持原样，多用于人的性情、样貌或作品风格；新闻的真假要用真实。"}, {"text": "这班地铁很本真。", "explanation": "这里应该用〈准时〉。本真指未经修饰、保持原样，不指按时；地铁按时到站要用准时。"}, {"text": "这台仪器的测量很本真。", "explanation": "这里应该用〈精确〉。本真不用来说仪器的测量，测量的准确程度要用精确。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0eb0521e-f62e-46f3-9f9f-cc04980c6a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93613, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本真", "is_correct": true, "explanation": "本真：毫不虚假，符合歌曲原汁原味的唱法。"}, {"text": "繁华", "is_correct": false, "explanation": "语义：繁华形容地方热闹，不能用来形容唱歌的样子。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：冷清多说场所或气氛，不能说唱得很冷清。"}, {"text": "健壮", "is_correct": false, "explanation": "体貌：健壮描述身体状况，不能用来形容唱歌。"}], "explanations": {"本真": "本真：毫不虚假，符合歌曲原汁原味的唱法。", "繁华": "语义：繁华形容地方热闹，不能用来形容唱歌的样子。", "冷清": "搭配：冷清多说场所或气氛，不能说唱得很冷清。", "健壮": "体貌：健壮描述身体状况，不能用来形容唱歌。"}, "sentence_index": 6, "correct_answer": "本真"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做研究很本真。", "explanation": "这里应该用〈严谨〉。本真说性情或样貌不加修饰，治学、做研究的周密细致要用严谨。"}, {"text": "这项服务很本真。", "explanation": "这里应该用〈快捷〉。本真形容不加修饰的状态，服务速度快要用快捷。"}, {"text": "欢迎的气氛很本真。", "explanation": "这里应该用〈热烈〉。本真不用来形容气氛，场面的热情、兴奋要用热烈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0eb0521e-f62e-46f3-9f9f-cc04980c6a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93613, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这孩子的笑容很很本真。", "corrected_sentence": "这孩子的笑容很本真。", "error_description": "“很很本真”多出一个“很”：程度副词重复，正确形式为“很本真”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0eb0521e-f62e-46f3-9f9f-cc04980c6a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93613, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个本真人。", "corrected_sentence": "他是一个本真的人。", "error_description": "“一个本真人”缺少定语标记“的”：双音节性质形容词修饰名词时一般要加“的”，正确形式为“一个本真的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0eb0521e-f62e-46f3-9f9f-cc04980c6a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
