INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93617, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "本处是这个地方，说话人自己所在的地方。", "primary_collocate": null, "pronunciation": "běn chù", "ipa": "pən˨˩ ʈʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "本处禁止吸烟，请大家注意。", "target_word": "本处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本处不收现金，请用手机付款。", "target_word": "本处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本处是图书室，请保持安静。", "target_word": "本处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本处没有停车位，请您去前面停车。", "target_word": "本处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本处路滑，请小心慢行。", "target_word": "本处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本处每天早上八点开门。", "target_word": "本处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本处不能拍照，谢谢你的合作。", "target_word": "本处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本处已经满员，请您换一家。", "target_word": "本处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本处提供免费的热水。", "target_word": "本处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在本处大声说话。", "target_word": "本处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "指说话人所在的这个地方，多用于告示、通知", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14564538-3a40-44fa-a32f-b1e6c7a259d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93617, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本处", "is_correct": true, "explanation": "正确：“本处”指说话人所在的地方，与告示中“禁止吸烟”的语境相合。"}, {"text": "他", "is_correct": false, "explanation": "语义：“他”指人，而句子说的是地点上的禁令，不能作告示的主语。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：“禁止吸烟，请大家注意”是对公众的告示，“自己”作主语无法构成这样的告示。"}, {"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”是疑问代词，问地点，而句子是陈述性的禁令。"}], "explanations": {"本处": "正确：“本处”指说话人所在的地方，与告示中“禁止吸烟”的语境相合。", "他": "语义：“他”指人，而句子说的是地点上的禁令，不能作告示的主语。", "自己": "搭配：“禁止吸烟，请大家注意”是对公众的告示，“自己”作主语无法构成这样的告示。", "哪里": "语义：“哪里”是疑问代词，问地点，而句子是陈述性的禁令。"}, "sentence_index": 0, "correct_answer": "本处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去过很多城市，本处的风景最让我难忘。", "explanation": "这里应该用〈那里〉。本处指说话人所在的这个地方；说别处的风景要用“那里”。"}, {"text": "我去年在上海读书，本处的同学都很热情。", "explanation": "这里应该用〈那里〉。本处指说话人所在的地方，说上海的同学要用“那里”，不能用“本处”。"}, {"text": "这本书我看过了，本处的内容很精彩。", "explanation": "这里应该用〈这本书〉。本处只指地方，不能指书，说书的内容要直接指向书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93617, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本处", "is_correct": true, "explanation": "正确：“本处”指说话人所在的地方，与“不能拍照”的规定相合。"}, {"text": "其他", "is_correct": false, "explanation": "搭配：“其他”作主语时通常要与“这些”“那些”等对照成分一起出现，这句中没有对照对象。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，问人，而句子是对场所的规定，不能作主语。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”是疑问代词，指事物，句子却是对场所的禁令，无法作主语。"}], "explanations": {"本处": "正确：“本处”指说话人所在的地方，与“不能拍照”的规定相合。", "其他": "搭配：“其他”作主语时通常要与“这些”“那些”等对照成分一起出现，这句中没有对照对象。", "谁": "语义：“谁”是疑问代词，问人，而句子是对场所的规定，不能作主语。", "什么": "语义：“什么”是疑问代词，指事物，句子却是对场所的禁令，无法作主语。"}, "sentence_index": 6, "correct_answer": "本处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "欢迎大家去本处参观。", "explanation": "这里应该用〈来〉。本处指说话人所在的地方，把人请到这里要说“来”，说“去”就成了离开这里。"}, {"text": "本处的学校离这儿很远，要坐车才能到。", "explanation": "这里应该用〈那所学校〉。本处指这里，与“离这儿很远”自相矛盾；说别处的学校要用“那所学校”。"}, {"text": "本处的昨天下了一场大雨。", "explanation": "这里应该去掉〈本处〉，直接说“昨天下了一场大雨”。本处只修饰地方，不修饰时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93617, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请大家本处排队。", "corrected_sentence": "请大家在本处排队。", "error_description": "错误：“本处排队”，缺少介词“在”。正确：“在本处排队”。“在本处”表示地点，是状语，要放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93617, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请不要在本处的地方停车。", "corrected_sentence": "请不要在本处停车。", "error_description": "错误：“本处的地方”。“本处”本身就指这个地方，后面不能再加“的地方”。正确：“在本处停车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93619, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93619, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93619, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "期望是盼着事情变得很好。", "primary_collocate": null, "pronunciation": "qī wàng", "ipa": "tɕʰi˥ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "大家都期望天气快点儿变好。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我期望明天的比赛一切顺利。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他期望病人很快好起来。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全家人期望着今年有个好收成。", "target_word": "期望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈期望我的身体越来越好。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们期望这次会议开得成功。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友期望他们的生活能慢慢变好。", "target_word": "期望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们期望雪下得再大一点儿。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她期望那件事别再出问题。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里人期望新路早日修好。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "期望着", "label": "体标"}, {"form": "期望过", "label": "体标"}, {"form": "期望值", "label": "复合"}], "register": "中性", "sense_fingerprint": "盼着某件事情顺利、变好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c42c51fa-068b-42d8-870b-2b763e4e5f46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93619, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "期望", "is_correct": true, "explanation": "正确答案。“期望”指盼着事情顺利、变好。"}, {"text": "七万", "is_correct": false, "explanation": "韵尾不同：wàn 与 wàng，声调相同，意思是数字七万。"}, {"text": "失望", "is_correct": false, "explanation": "声母不同：shī 与 qī，声调相同，意思是希望落空、感到不满意。"}, {"text": "资望", "is_correct": false, "explanation": "声母不同：zī 与 qī，声调相同，意思是声望和资历。"}], "explanations": {"期望": "正确答案。“期望”指盼着事情顺利、变好。", "七万": "韵尾不同：wàn 与 wàng，声调相同，意思是数字七万。", "失望": "声母不同：shī 与 qī，声调相同，意思是希望落空、感到不满意。", "资望": "声母不同：zī 与 qī，声调相同，意思是声望和资历。"}, "sentence_index": null, "correct_answer": "期望"}, "level_3": {"options": [{"text": "期望", "is_correct": true, "explanation": "“期望”表示盼着事情变好，与“快点儿变好”相符。"}, {"text": "观看", "is_correct": false, "explanation": "搭配：“观看”后接比赛、节目等可见的事物，不接“天气变好”。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指想起过去，与“快点儿变好”的将来矛盾。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”表示对过去的思念，与盼望将来变好不符。"}], "explanations": {"期望": "“期望”表示盼着事情变好，与“快点儿变好”相符。", "观看": "搭配：“观看”后接比赛、节目等可见的事物，不接“天气变好”。", "回忆": "语义：“回忆”指想起过去，与“快点儿变好”的将来矛盾。", "怀念": "语义：“怀念”表示对过去的思念，与盼望将来变好不符。"}, "sentence_index": 0, "correct_answer": "期望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我常常期望小时候住过的老房子。", "explanation": "这里应该用〈怀念〉。期望是盼着将来的事变好，对过去的地方表示想念要用〈怀念〉。"}, {"text": "他站在山顶期望远方的城市。", "explanation": "这里应该用〈眺望〉。期望不表示向远处看，看远方的城市要用〈眺望〉。"}, {"text": "妈妈期望我的成绩越来越差。", "explanation": "这里应该用〈担心〉。期望只用于盼着事情变好，妈妈不会盼望孩子成绩变差，这种不希望发生的情况要说〈担心〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93619, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "期望", "is_correct": true, "explanation": "“期望”表示盼着生活慢慢变好，与“能慢慢变好”相符。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”针对地方或展览，不能用于“生活变好”这样的状态。"}, {"text": "探望", "is_correct": false, "explanation": "搭配：“探望”后接人，不接“生活”这样的抽象事物。"}, {"text": "拜访", "is_correct": false, "explanation": "搭配：“拜访”的对象是人，不能拜访“他们的生活”。"}], "explanations": {"期望": "“期望”表示盼着生活慢慢变好，与“能慢慢变好”相符。", "参观": "语义：“参观”针对地方或展览，不能用于“生活变好”这样的状态。", "探望": "搭配：“探望”后接人，不接“生活”这样的抽象事物。", "拜访": "搭配：“拜访”的对象是人，不能拜访“他们的生活”。"}, "sentence_index": 6, "correct_answer": "期望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我期望他会晚到。", "explanation": "这里应该用〈预料〉。期望表示盼望好的结果，不能用来说别人晚到这类不希望发生的事。"}, {"text": "学校期望学生必须遵守校规。", "explanation": "这里应该用〈要求〉。期望只表示盼望，不和“必须”连用；学校对学生提出必须做的事要用〈要求〉。"}, {"text": "妈妈期望我太晚回家。", "explanation": "这里应该用〈责备〉。期望表示盼望好的结果，妈妈不会希望孩子太晚回家，这种情况要说〈责备〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93619, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都期望了这场雨快点儿停。", "corrected_sentence": "大家都期望这场雨快点儿停。", "error_description": "这里说的是对将来的盼望，而“了”表示动作已经完成，二者时间不合，应去掉“了”，说“大家都期望这场雨快点儿停。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93619, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我期望了他很快好起来。", "corrected_sentence": "我期望他很快好起来。", "error_description": "这里说的是对将来的盼望，而“了”表示动作已经完成，二者时间不合，应去掉“了”，说“我期望他很快好起来。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
