INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93620, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "对未来的人或事抱有希望。", "primary_collocate": null, "pronunciation": "qī wàng", "ipa": "tɕʰi˥ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "父母期望孩子将来能成为医生。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都期望明年的生意会更好。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他期望着朋友早点儿回信。", "target_word": "期望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家期望新来的经理带来改变。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我期望下个月能去北京工作。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民期望今年的雨水多一点儿。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小就期望自己长大后当老师。", "target_word": "期望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司期望这个新产品卖得好。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我曾期望过出国读书，后来没去成。", "target_word": "期望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师期望你下次考试能进步。", "target_word": "期望", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "期望着", "label": "体标"}, {"form": "期望过", "label": "体标"}, {"form": "期望值", "label": "复合"}], "register": "中性", "sense_fingerprint": "对人或事的将来抱有希望，常带小句宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c42c51fa-068b-42d8-870b-2b763e4e5f46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93620, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "期望", "is_correct": true, "explanation": "正确答案。“期望”指对未来的人或事抱有希望。"}, {"text": "七万", "is_correct": false, "explanation": "韵尾不同：wàn 与 wàng，声调相同，意思是数字七万。"}, {"text": "失望", "is_correct": false, "explanation": "声母不同：shī 与 qī，声调相同，意思是希望落空、感到不满意。"}, {"text": "资望", "is_correct": false, "explanation": "声母不同：zī 与 qī，声调相同，意思是声望和资历。"}], "explanations": {"期望": "正确答案。“期望”指对未来的人或事抱有希望。", "七万": "韵尾不同：wàn 与 wàng，声调相同，意思是数字七万。", "失望": "声母不同：shī 与 qī，声调相同，意思是希望落空、感到不满意。", "资望": "声母不同：zī 与 qī，声调相同，意思是声望和资历。"}, "sentence_index": null, "correct_answer": "期望"}, "level_3": {"options": [{"text": "期望", "is_correct": true, "explanation": "“期望”表示对将来的事抱有希望，与“将来能成为医生”相符。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指想起过去的事，与“将来”矛盾。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能带“孩子将来能成为医生”这样的小句。"}, {"text": "责怪", "is_correct": false, "explanation": "语义：“责怪”针对已经发生的过错，不能用于尚未发生的将来。"}], "explanations": {"期望": "“期望”表示对将来的事抱有希望，与“将来能成为医生”相符。", "回忆": "语义：“回忆”指想起过去的事，与“将来”矛盾。", "参观": "搭配：“参观”的对象是场所或展览，不能带“孩子将来能成为医生”这样的小句。", "责怪": "语义：“责怪”针对已经发生的过错，不能用于尚未发生的将来。"}, "sentence_index": 0, "correct_answer": "期望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子期望地看着桌上的蛋糕。", "explanation": "这里应该用〈期待〉。“期望”一般不加“地”修饰动作，表示盼望的神情要说“期待地看着”。"}, {"text": "他站在窗前期望远方。", "explanation": "这里应该用〈眺望〉。期望是对未来的希望，不表示向远处看，看远方要用〈眺望〉。"}, {"text": "根据天气情况，专家期望明天会下雨。", "explanation": "这里应该用〈预计〉。期望带有盼望的感情，对天气这类客观推断要用〈预计〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "期望", "is_correct": true, "explanation": "“期望”表示对将来的事抱有希望，与“长大后当老师”相符。"}, {"text": "探望", "is_correct": false, "explanation": "搭配：“探望”后接的是人，不能接“自己长大后当老师”这样的小句。"}, {"text": "体验", "is_correct": false, "explanation": "语义：“体验”指亲身经历已经存在的事，与“长大后”的将来矛盾。"}, {"text": "观察", "is_correct": false, "explanation": "语义：“观察”针对眼前可见的事，不能用于尚未发生的将来。"}], "explanations": {"期望": "“期望”表示对将来的事抱有希望，与“长大后当老师”相符。", "探望": "搭配：“探望”后接的是人，不能接“自己长大后当老师”这样的小句。", "体验": "语义：“体验”指亲身经历已经存在的事，与“长大后”的将来矛盾。", "观察": "语义：“观察”针对眼前可见的事，不能用于尚未发生的将来。"}, "sentence_index": 6, "correct_answer": "期望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我期望他会迟到。", "explanation": "这里应该用〈预期〉。期望表示盼望好的结果，不能用来说别人迟到这种不希望发生的事。"}, {"text": "老师期望我们必须在周五之前交完作业。", "explanation": "这里应该用〈要求〉。期望只表示盼望，不和“必须”连用；对别人提出必须做的事要用〈要求〉。"}, {"text": "我常常期望小时候的村子。", "explanation": "这里应该用〈怀念〉。期望指对将来的事抱有盼望，对过去的人或事表达想念要用〈怀念〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我期望了明年能去北京。", "corrected_sentence": "我期望明年能去北京。", "error_description": "这里说的是明年的事，是对将来的盼望，而“了”表示动作已经完成，二者时间不合，应去掉“了”，说“我期望明年能去北京。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我期望了他明天能来。", "corrected_sentence": "我期望他明天能来。", "error_description": "这里说的是明天的事，是对将来的盼望，而“了”表示动作已经完成，二者时间不合，应去掉“了”，说“我期望他明天能来。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400522be-af84-4e16-81ac-99f2e20030a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
