INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93625, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "此类是说像这样的一种。", "primary_collocate": null, "pronunciation": "cǐ lèi", "ipa": "tsʰɨ˨˩˦ leɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他说的此类话我听得太多了。", "target_word": "此类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此类小事不用麻烦老板。", "target_word": "此类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们几道此类题。", "target_word": "此类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店只卖此类衣服。", "target_word": "此类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很少买此类东西。", "target_word": "此类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从来不看此类节目。", "target_word": "此类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于此类天气，大家早已习惯。", "target_word": "此类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此类工作需要很多耐心。", "target_word": "此类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在研究此类机器。", "target_word": "此类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该帮助有此类困难的人。", "target_word": "此类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "指像上文所说的这样的一种事物或情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e36a8cdb-5406-47d1-930e-7fc5be5a3f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93625, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "此类", "is_correct": true, "explanation": "此类（cǐ lèi）指像上文所说的这样的一种，是正确答案。"}, {"text": "词类", "is_correct": false, "explanation": "词类（cí lèi）首音声调不同（第二声），意思是词的类别。"}, {"text": "子类", "is_correct": false, "explanation": "子类（zǐ lèi）声母 z 与 c 不同、声调相同，意思是下一级的类别。"}, {"text": "几类", "is_correct": false, "explanation": "几类（jǐ lèi）声母 j 与 c 不同、声调相同，意思是若干类。"}], "explanations": {"此类": "此类（cǐ lèi）指像上文所说的这样的一种，是正确答案。", "词类": "词类（cí lèi）首音声调不同（第二声），意思是词的类别。", "子类": "子类（zǐ lèi）声母 z 与 c 不同、声调相同，意思是下一级的类别。", "几类": "几类（jǐ lèi）声母 j 与 c 不同、声调相同，意思是若干类。"}, "sentence_index": null, "correct_answer": "此类"}, "level_3": {"options": [{"text": "此类", "is_correct": true, "explanation": "此类指像上文所说的这样的话，与句意相符，是正确答案。"}, {"text": "其", "is_correct": false, "explanation": "语域：「其」为文言用法，「他说的其话」不合现代汉语的表达。"}, {"text": "哪些", "is_correct": false, "explanation": "语义：「哪些」是疑问代词，使句子变成疑问，而「我听得太多了」是陈述。"}, {"text": "几", "is_correct": false, "explanation": "语法：「几」后须接量词，「他说的几话」不成立。"}], "explanations": {"此类": "此类指像上文所说的这样的话，与句意相符，是正确答案。", "其": "语域：「其」为文言用法，「他说的其话」不合现代汉语的表达。", "哪些": "语义：「哪些」是疑问代词，使句子变成疑问，而「我听得太多了」是陈述。", "几": "语法：「几」后须接量词，「他说的几话」不成立。"}, "sentence_index": 0, "correct_answer": "此类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "此类人叫王明，是我的同事。", "explanation": "此类指一类人，不能指某一个具体的人。这里说的是一个人，应该用〈这个人〉。"}, {"text": "此类人是我的哥哥，很会唱歌。", "explanation": "此类指一类人，不能指某个具体的人。说自己的哥哥，应该用〈这位〉。"}, {"text": "此类人昨天在教室里摔倒了，被送去了医院。", "explanation": "此类指一类人，不能指某个具体的人。这里说的是一位同学，应该用〈那位同学〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93625, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此类", "is_correct": true, "explanation": "此类指这一类天气，与「大家早已习惯」相符，是正确答案。"}, {"text": "都", "is_correct": false, "explanation": "词性：「都」是副词，不能直接修饰名词「天气」，「对于都天气」不成立。"}, {"text": "很", "is_correct": false, "explanation": "词性：「很」是副词，不能直接修饰名词「天气」，「对于很天气」不成立。"}, {"text": "几", "is_correct": false, "explanation": "语法：「几」后须接量词，「对于几天气」不成立。"}], "explanations": {"此类": "此类指这一类天气，与「大家早已习惯」相符，是正确答案。", "都": "词性：「都」是副词，不能直接修饰名词「天气」，「对于都天气」不成立。", "很": "词性：「很」是副词，不能直接修饰名词「天气」，「对于很天气」不成立。", "几": "语法：「几」后须接量词，「对于几天气」不成立。"}, "sentence_index": 6, "correct_answer": "此类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "此类人昨天在厨房里打碎了盘子。", "explanation": "此类指一类人，不能指某一个打碎盘子的人。这里应该用〈那个孩子〉。"}, {"text": "此类阿姨昨天来过我家。", "explanation": "此类指一类人，不能指某位具体的阿姨。这里应该用〈这位阿姨〉。"}, {"text": "此类李校长昨天在会上发了言。", "explanation": "此类指一类人，不能用来指某位具体的校长。这里应该用〈这位李校长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
