INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93626, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "此类", "is_correct": true, "explanation": "此类（cǐ lèi）指这一类事物，是正确答案。"}, {"text": "词类", "is_correct": false, "explanation": "词类（cí lèi）首音声调不同（第二声），意思是词的类别，与「此类」的指示意义不同。"}, {"text": "子类", "is_correct": false, "explanation": "子类（zǐ lèi）声母 z 与 c 不同、声调相同，意思是下一级的类别。"}, {"text": "几类", "is_correct": false, "explanation": "几类（jǐ lèi）声母 j 与 c 不同、声调相同，意思是若干类。"}], "explanations": {"此类": "此类（cǐ lèi）指这一类事物，是正确答案。", "词类": "词类（cí lèi）首音声调不同（第二声），意思是词的类别，与「此类」的指示意义不同。", "子类": "子类（zǐ lèi）声母 z 与 c 不同、声调相同，意思是下一级的类别。", "几类": "几类（jǐ lèi）声母 j 与 c 不同、声调相同，意思是若干类。"}, "sentence_index": null, "correct_answer": "此类"}, "level_3": {"options": [{"text": "此类", "is_correct": true, "explanation": "此类指这一类问题，与句中「很常见」的泛指语气相符，是正确答案。"}, {"text": "都", "is_correct": false, "explanation": "词性：「都」是副词，不能直接修饰名词「问题」，「都问题在生活中很常见」不成立。"}, {"text": "哪些", "is_correct": false, "explanation": "语义：「哪些」是疑问代词，会使句子变成疑问，与陈述句「在生活中很常见」不合。"}, {"text": "几", "is_correct": false, "explanation": "语法：「几」后须接量词，「几问题」不成立。"}], "explanations": {"此类": "此类指这一类问题，与句中「很常见」的泛指语气相符，是正确答案。", "都": "词性：「都」是副词，不能直接修饰名词「问题」，「都问题在生活中很常见」不成立。", "哪些": "语义：「哪些」是疑问代词，会使句子变成疑问，与陈述句「在生活中很常见」不合。", "几": "语法：「几」后须接量词，「几问题」不成立。"}, "sentence_index": 0, "correct_answer": "此类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "此类人叫王明，是我的同事。", "explanation": "此类指一类人，不能指某一个具体的人。这里说的是一个人，应该用〈这个人〉。"}, {"text": "此类人是我的哥哥，很会唱歌。", "explanation": "此类指一类人，不能指某个具体的人。说自己的哥哥，应该用〈这位〉。"}, {"text": "此类人昨天在教室里摔倒了，被送去了医院。", "explanation": "此类指一类人，不能指某个具体的人。这里说的是一位同学，应该用〈那位同学〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此类", "is_correct": true, "explanation": "此类指这一类行为，与「学校不允许」的禁止语境相符，是正确答案。"}, {"text": "已经", "is_correct": false, "explanation": "词性：「已经」是副词，修饰动词，不能直接修饰名词「行为」，「学校不允许已经行为」不成立。"}, {"text": "很", "is_correct": false, "explanation": "词性：「很」是副词，不能直接修饰名词「行为」，「学校不允许很行为」不成立。"}, {"text": "正在", "is_correct": false, "explanation": "词性：「正在」是副词，表示动作进行，须修饰动词，「学校不允许正在行为」不成立。"}], "explanations": {"此类": "此类指这一类行为，与「学校不允许」的禁止语境相符，是正确答案。", "已经": "词性：「已经」是副词，修饰动词，不能直接修饰名词「行为」，「学校不允许已经行为」不成立。", "很": "词性：「很」是副词，不能直接修饰名词「行为」，「学校不允许很行为」不成立。", "正在": "词性：「正在」是副词，表示动作进行，须修饰动词，「学校不允许正在行为」不成立。"}, "sentence_index": 6, "correct_answer": "此类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "此类厨师正是我的父亲。", "explanation": "此类指一类人，不能指某一个具体的人。这里说的是我的父亲，应该用〈这位〉。"}, {"text": "此类王先生昨天来看过我。", "explanation": "此类指一类人，不能用来指某一位具体的人。指这位王先生要说〈这位〉。"}, {"text": "此类赵医生今天给我看了病。", "explanation": "此类指一类人，不能指某一位具体的医生。这里应该用〈这位医生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂应该重视此类了问题。", "corrected_sentence": "工厂应该重视此类问题。", "error_description": "错误：「此类了问题」；正确：「此类问题」。「了」是动态助词，须紧跟动词，不能插在指示词「此类」与名词「问题」之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校很快处理了此类了行为。", "corrected_sentence": "学校很快处理了此类行为。", "error_description": "错误：「此类了行为」；正确：「此类行为」。「了」已紧跟动词「处理」，不能再插在「此类」与名词「行为」之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
