INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93627, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93627, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "与某件事一模一样。", "primary_collocate": null, "pronunciation": "zhèng rú", "ipa": "ʈʂɤŋ˥˩ ɻu˧˥", "syllable_count": 2, "sentences": [{"text": "这个结果正如我想的一样。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法正如我所想的一样。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情正如你猜的一样。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的风景正如照片上的一样美。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说的话正如妈妈说的一样。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的结果正如大家想的那样。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的天气正如天气预报说的一样。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜正如朋友说的一样好吃。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看到的正如你说的一样。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的情况正如医生说的那样。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "正如·连词·与某件事一模一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168ad27f-59af-419a-aeff-3d9250db54ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93627, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正如", "is_correct": true, "explanation": "正如：表示与“我想的”完全一致，即“一模一样”的义项。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，与“一样”所表示的相同含义矛盾。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：“而且”要连接并列成分，“这个结果而且我想的一样”不成立。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，此处没有因果关系。"}], "explanations": {"正如": "正如：表示与“我想的”完全一致，即“一模一样”的义项。", "或者": "语义：“或者”表示选择，与“一样”所表示的相同含义矛盾。", "而且": "搭配：“而且”要连接并列成分，“这个结果而且我想的一样”不成立。", "因此": "语义：“因此”表示因果，此处没有因果关系。"}, "sentence_index": 0, "correct_answer": "正如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "正如天气好，我们去了公园。", "explanation": "这里应该用〈因为〉。正如表示与某件事完全一样，不用来说明原因。"}, {"text": "正如他年纪大，还是每天跑步。", "explanation": "这里应该用〈虽然〉。正如表示完全一致的比照，不表示让步。"}, {"text": "正如明天下雨，我们就不去了。", "explanation": "这里应该用〈如果〉。正如只引出已知的情况，不引出假设条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93627, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正如", "is_correct": true, "explanation": "正如：引出与“天气预报说的”完全一致的情况。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，与“完全一致”的比照意思不合。"}, {"text": "并且", "is_correct": false, "explanation": "搭配：“并且”要连接并列成分，不能直接连接“今天的天气”与“天气预报说的一样”。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，天气预报说的内容不是天气状况的结果。"}], "explanations": {"正如": "正如：引出与“天气预报说的”完全一致的情况。", "然而": "语义：“然而”表示转折，与“完全一致”的比照意思不合。", "并且": "搭配：“并且”要连接并列成分，不能直接连接“今天的天气”与“天气预报说的一样”。", "所以": "语义：“所以”表示因果，天气预报说的内容不是天气状况的结果。"}, "sentence_index": 6, "correct_answer": "正如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他会唱歌，正如会跳舞。", "explanation": "这里应该用〈而且〉。正如表示与某件事完全一样，不用来表示递进。"}, {"text": "他很努力，正如考得不好。", "explanation": "这里应该用〈但是〉。正如表示与某件事完全一致，不表示转折。"}, {"text": "正如你努力，就一定能成功。", "explanation": "这里应该用〈只要〉。正如表示与已知情况一致，不引出条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93627, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事的结果正如他预料地一样。", "corrected_sentence": "这件事的结果正如他预料的一样。", "error_description": "结构错误：“预料”后修饰“一样”须用“的”，不能用“地”，应为“正如他预料的一样”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93627, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次的结果正如大家预想那样。", "corrected_sentence": "这次的结果正如大家预想的那样。", "error_description": "结构错误：“预想”修饰“那样”，中间需要“的”，应为“预想的那样”，不能说“预想那样”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
