INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93628, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "恰如；正好像。用来引出比照的事实或话语。", "primary_collocate": null, "pronunciation": "zhèng rú", "ipa": "ʈʂɤŋ˥˩ ɻu˧˥", "syllable_count": 2, "sentences": [{"text": "正如老师所说，学习要有耐心。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正如你所见，这里很安静。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正如大家所知，明天会下雨。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正如他说的那样，这件事不难。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正如树需要水，人也需要朋友。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正如我们所想，他今天没有来。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正如书上写的，这种花只开一天。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正如妈妈常说的，好习惯要早点养成。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正如鱼不能离开水，我们也不能没有空气。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正如天气预报说的，今天下了大雨。", "target_word": "正如", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "正如·连词·引出比照的事实或话语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168ad27f-59af-419a-aeff-3d9250db54ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93628, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正如", "is_correct": true, "explanation": "正如：引出比照的依据，即“老师所说”，表示“像……那样”。"}, {"text": "虽然", "is_correct": false, "explanation": "配价：“虽然”要求后面有“但是”等主句，这里只有从句，结构不完整。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”要承接前面已有的并列成分，此处没有可并列的句子，“而且老师所说”不成句。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，与“老师所说”的比照意思不合。"}], "explanations": {"正如": "正如：引出比照的依据，即“老师所说”，表示“像……那样”。", "虽然": "配价：“虽然”要求后面有“但是”等主句，这里只有从句，结构不完整。", "而且": "语义：“而且”要承接前面已有的并列成分，此处没有可并列的句子，“而且老师所说”不成句。", "但是": "语义：“但是”表示转折，与“老师所说”的比照意思不合。"}, "sentence_index": 0, "correct_answer": "正如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我到车站的时候，正如他也到了。", "explanation": "这里应该用〈正好〉。正如用于引出比照的事实，不表示碰巧。"}, {"text": "正如明天下雨，我们就不去了。", "explanation": "这里应该用〈如果〉。正如只引出已知的事实，不引出假设条件。"}, {"text": "正如下着雨，他还是去跑步了。", "explanation": "这里应该用〈虽然〉。正如表示比照，不表示让步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93628, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正如", "is_correct": true, "explanation": "正如：引出比照的依据，即“书上写的”，表示“像……那样”。"}, {"text": "尽管", "is_correct": false, "explanation": "配价：“尽管”要求后面有主句，这里只有从句，结构不完整。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，与“书上写的”这一依据的比照不合。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，书上写的内容不是这种花只开一天的结果。"}], "explanations": {"正如": "正如：引出比照的依据，即“书上写的”，表示“像……那样”。", "尽管": "配价：“尽管”要求后面有主句，这里只有从句，结构不完整。", "然而": "语义：“然而”表示转折，与“书上写的”这一依据的比照不合。", "所以": "语义：“所以”表示结果，书上写的内容不是这种花只开一天的结果。"}, "sentence_index": 6, "correct_answer": "正如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我正如吃饭，他就来了。", "explanation": "这里应该用〈正在〉。正如引出比照的事实，不表示动作正在进行。"}, {"text": "正如你努力，就一定能学好。", "explanation": "这里应该用〈只要〉。正如不引出条件。"}, {"text": "正如他病了，所以没来上课。", "explanation": "这里应该用〈因为〉。正如表示比照，不表示原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93628, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "正如我们料，比赛输了。", "corrected_sentence": "正如我们所料，比赛输了。", "error_description": "词语缺失：“料”前应有“所”，“正如我们料”不成句，应为“正如我们所料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93628, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "正如天气预报说所，今天下了大雨。", "corrected_sentence": "正如天气预报所说，今天下了大雨。", "error_description": "语序错误：“所”应紧接在动词前，应为“所说”，不能写成“说所”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
