INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93631, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "正当是对的，不是坏的，也是没有问题的。", "primary_collocate": null, "pronunciation": "zhèng dàng", "ipa": "ʈʂəŋ˥˩ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他有一份正当的工作，不做坏事。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些钱来路正当，你不用担心。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱看书是正当的爱好，不是坏习惯。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想用正当的方法赚钱，这很好。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个生意的做法很正当，大家都放心。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做的事都很正当，没有人说他不对。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，用正当的办法学习才有用。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说这是正当的生意，不怕别人看。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠正当的劳动养活家人。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我正当的收入，不是偷来的。", "target_word": "正当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不正当", "label": "复合"}, {"form": "正当防卫", "label": "复合"}, {"form": "正當", "label": "繁体"}], "register": "中性", "sense_fingerprint": "正当：做法、收入、爱好等是对的、不坏、没有问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd05d25bf-15fb-4699-a34e-f76e1fe1de8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93631, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正当", "is_correct": true, "explanation": "正确答案。正当（zhèng dàng）指合理合法、没有问题。"}, {"text": "政党", "is_correct": false, "explanation": "dǎng（第三声）与 dàng（第四声）声调不同，意思是政党。"}, {"text": "争当", "is_correct": false, "explanation": "zhēng 与 zhèng 声调不同，dāng 与 dàng 声调也不同，意思是争取担任。"}, {"text": "中档", "is_correct": false, "explanation": "zhōng（第一声）与 zhèng（第四声）韵母和声调都不同，意思是中等档次。"}], "explanations": {"正当": "正确答案。正当（zhèng dàng）指合理合法、没有问题。", "政党": "dǎng（第三声）与 dàng（第四声）声调不同，意思是政党。", "争当": "zhēng 与 zhèng 声调不同，dāng 与 dàng 声调也不同，意思是争取担任。", "中档": "zhōng（第一声）与 zhèng（第四声）韵母和声调都不同，意思是中等档次。"}, "sentence_index": null, "correct_answer": "正当"}, "level_3": {"options": [{"text": "正当", "is_correct": true, "explanation": "正确答案。“正当”指工作合理合法，与后文“不做坏事”一致。"}, {"text": "凶狠", "is_correct": false, "explanation": "语义：“凶狠”指残暴、恶劣，与后文“不做坏事”矛盾。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”说明情况或道理是否明白，不能修饰“工作”。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描述人的体形，不能用来形容工作。"}], "explanations": {"正当": "正确答案。“正当”指工作合理合法，与后文“不做坏事”一致。", "凶狠": "语义：“凶狠”指残暴、恶劣，与后文“不做坏事”矛盾。", "清楚": "搭配：“清楚”说明情况或道理是否明白，不能修饰“工作”。", "胖": "体貌：“胖”描述人的体形，不能用来形容工作。"}, "sentence_index": 0, "correct_answer": "正当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题的答案很正当。", "explanation": "这里应该用〈正确〉。“正当”说做法、理由合理合法，答案对错要用“正确”。"}, {"text": "孩子的心跳很正当。", "explanation": "这里应该用〈正常〉。“正当”说做法、理由合理合法，心跳是否正常要用“正常”。"}, {"text": "这批零件很正当。", "explanation": "这里应该用〈合格〉。“正当”说做法、理由合理合法，零件质量是否达标要用“合格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93631, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正当", "is_correct": true, "explanation": "正确答案。正当（zhèng dàng）指合理合法、没有问题。"}, {"text": "震荡", "is_correct": false, "explanation": "zhèn 与 zhèng 韵尾不同（n 与 ng），意思是震动、动荡。"}, {"text": "整党", "is_correct": false, "explanation": "zhěng 与 zhèng 声调不同，dǎng 与 dàng 声调也不同，意思是整顿党组织。"}, {"text": "政党", "is_correct": false, "explanation": "dǎng（第三声）与 dàng（第四声）声调不同，意思是政治团体。"}], "explanations": {"正当": "正确答案。正当（zhèng dàng）指合理合法、没有问题。", "震荡": "zhèn 与 zhèng 韵尾不同（n 与 ng），意思是震动、动荡。", "整党": "zhěng 与 zhèng 声调不同，dǎng 与 dàng 声调也不同，意思是整顿党组织。", "政党": "dǎng（第三声）与 dàng（第四声）声调不同，意思是政治团体。"}, "sentence_index": null, "correct_answer": "正当"}, "level_3": {"options": [{"text": "正当", "is_correct": true, "explanation": "正确答案。“正当”指办法合理，与“学习才有用”相符。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容人或物的体形，不能修饰“办法”。"}, {"text": "残暴", "is_correct": false, "explanation": "语义：“残暴”形容凶恶狠毒，修饰“办法”语义不通，与“学习才有用”无关。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说人的年龄，不能修饰“办法”。"}], "explanations": {"正当": "正确答案。“正当”指办法合理，与“学习才有用”相符。", "矮小": "体貌：“矮小”形容人或物的体形，不能修饰“办法”。", "残暴": "语义：“残暴”形容凶恶狠毒，修饰“办法”语义不通，与“学习才有用”无关。", "年轻": "搭配：“年轻”说人的年龄，不能修饰“办法”。"}, "sentence_index": 6, "correct_answer": "正当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个数字很正当。", "explanation": "这里应该用〈精确〉。“正当”说做法、理由合理合法，数字的准确程度要用“精确”。"}, {"text": "他的发音很正当。", "explanation": "这里应该用〈标准〉。“正当”说做法、理由合理合法，发音是否符合规范要用“标准”。"}, {"text": "字迹很正当。", "explanation": "这里应该用〈清晰〉。“正当”说做法、理由合理合法，字迹的清楚程度要用“清晰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_v