INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93631, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做的是正当得生意，不怕别人查。", "corrected_sentence": "他做的是正当的生意，不怕别人查。", "error_description": "助词错误：“正当”修饰名词时要用“的”，不用“得”，应说“正当的生意”，不说“正当得生意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
