INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93633, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "水准是做得好不好的高低。", "primary_collocate": null, "pronunciation": "shuǐ zhǔn", "ipa": "ʂueɪ˨˩˦ tʂuən˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的汉语水准很高。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的菜水准不错。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的水准比去年高多了。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的作文水准提高了。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的表演水准一般。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学校的教学水准很好。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画画的水准让大家吃惊。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的工作水准怎么这么低？", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试看出了大家的水准。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踢球的水准越来越高。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水準", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事或表现好坏的高低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781e042f-01c8-4179-94a7-75f6a8a36a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93633, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水准", "is_correct": true, "explanation": "正确。〈水准〉指做事或表现的高低，“汉语水准很高”说的是汉语能力高。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人身体的重量，不能说“汉语体重”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”说冷热，与语言能力无关。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身材的高矮，不能用来形容语言能力。"}], "explanations": {"水准": "正确。〈水准〉指做事或表现的高低，“汉语水准很高”说的是汉语能力高。", "体重": "搭配：“体重”指人身体的重量，不能说“汉语体重”。", "温度": "语义：“温度”说冷热，与语言能力无关。", "身高": "体貌：“身高”指身材的高矮，不能用来形容语言能力。"}, "sentence_index": 0, "correct_answer": "水准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有一只很高的水准。", "explanation": "这里应该用〈种〉或〈个〉。〈水准〉是抽象名词，〈只〉用于动物或成对物品中的一件，不能用来数水准。"}, {"text": "他这次的水准考得很好。", "explanation": "这里应该用〈成绩〉。考试的结果可以说“考得好”，要用〈成绩〉或〈分数〉；〈水准〉指做事的高低，不能作“考”的对象。"}, {"text": "这个箱子的水准很重，搬不动。", "explanation": "这里应该用〈分量〉。〈分量〉指物体的轻重，〈水准〉指做事或质量的高低，不能用来说箱子的轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93633, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水准", "is_correct": true, "explanation": "正确。〈水准〉指画画的好坏程度，“水准让大家吃惊”说画得好。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“电话”是通讯工具，与画画的好坏无关。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，与画画的好坏无关。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”指走路的动作，不能说“画画的脚步”。"}], "explanations": {"水准": "正确。〈水准〉指画画的好坏程度，“水准让大家吃惊”说画得好。", "电话": "语义：“电话”是通讯工具，与画画的好坏无关。", "体温": "语义：“体温”指身体的温度，与画画的好坏无关。", "脚步": "搭配：“脚步”指走路的动作，不能说“画画的脚步”。"}, "sentence_index": 6, "correct_answer": "水准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的水准很长。", "explanation": "这里应该用〈寿命〉。〈寿命〉指使用的年限，可以说“很长”；〈水准〉指做事或质量的高低，不能用来说机器用了多久。"}, {"text": "他这次水准考了很高的分数。", "explanation": "这里应该用〈分数〉或〈成绩〉。得分可以说“考了高分”，〈水准〉说做事的高低，不能用作“考”的宾语。"}, {"text": "他赢得了大家的水准。", "explanation": "这里应该用〈尊重〉。〈尊重〉是可以“赢得”的；〈水准〉指做事的高低，不能被“赢得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93633, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛的水准高很。", "corrected_sentence": "这次比赛的水准很高。", "error_description": "错误在“水准高很”：程度副词〈很〉应放在形容词〈高〉前面，应说“水准很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93633, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的画画水准不贵。", "corrected_sentence": "他的画画水准不错。", "error_description": "搭配错误：〈水准〉不能用“贵”来形容，应说“水准不错”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
