INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93634, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在某一方面所达到的程度或标准。", "primary_collocate": null, "pronunciation": "shuǐ zhǔn", "ipa": "ʂueɪ˨˩˦ tʂuən˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们的生活水准越来越高了。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的水准达到了国家要求。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人的收入水准比以前高。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的医疗水准很高。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想达到专业水准。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们的英语水准不一样。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的管理水准比同行高得多。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的服务水准让客人满意。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家的经济水准提高了很多。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保持现在的水准。", "target_word": "水准", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水準", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某方面达到的程度或标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781e042f-01c8-4179-94a7-75f6a8a36a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水准", "is_correct": true, "explanation": "正确。〈水准〉指某方面达到的程度，“生活水准越来越高”说生活的程度在提高。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人的身体重量，不能说“生活体重”。"}, {"text": "血压", "is_correct": false, "explanation": "语义：“血压”指血液的压力，与生活的状况无关。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”说身材的高矮，不能用来描述生活。"}], "explanations": {"水准": "正确。〈水准〉指某方面达到的程度，“生活水准越来越高”说生活的程度在提高。", "体重": "搭配：“体重”指人的身体重量，不能说“生活体重”。", "血压": "语义：“血压”指血液的压力，与生活的状况无关。", "身高": "体貌：“身高”说身材的高矮，不能用来描述生活。"}, "sentence_index": 0, "correct_answer": "水准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校有一条很高的水准。", "explanation": "这里应该用〈种〉或〈个〉。〈条〉用于细长的东西，〈水准〉是抽象名词，不能用〈条〉来数。"}, {"text": "这家酒店的水准很贵。", "explanation": "这里应该用〈价格〉。〈价格〉可以说“贵”，〈水准〉指达到的程度，不能用“贵”来形容。"}, {"text": "这台电脑的水准很重，背不动。", "explanation": "这里应该用〈重量〉。〈重量〉指物体的轻重，〈水准〉指达到的程度，不能用来说电脑的轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水准", "is_correct": true, "explanation": "正确。〈水准〉指管理达到的程度，“管理水准比同行高”说的是管理的程度。"}, {"text": "体积", "is_correct": false, "explanation": "语义：“体积”指物体占的空间，不能说“管理体积”。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：“亮度”用于光线或屏幕，不能说“管理亮度”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热，与管理的程度无关。"}], "explanations": {"水准": "正确。〈水准〉指管理达到的程度，“管理水准比同行高”说的是管理的程度。", "体积": "语义：“体积”指物体占的空间，不能说“管理体积”。", "亮度": "搭配：“亮度”用于光线或屏幕，不能说“管理亮度”。", "温度": "语义：“温度”指冷热，与管理的程度无关。"}, "sentence_index": 6, "correct_answer": "水准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的水准很快。", "explanation": "这里应该用〈速度〉。〈速度〉可以说“快”，〈水准〉指达到的程度，不能用“快”来形容。"}, {"text": "这件衣服的水准太大了，我穿不了。", "explanation": "这里应该用〈尺寸〉。〈尺寸〉指衣服的大小，可以说“太大”；〈水准〉指某方面达到的程度，不能用来说衣服的大小。"}, {"text": "他赢得了很好的水准。", "explanation": "这里应该用〈名声〉。〈名声〉可以“赢得”，〈水准〉表示达到的程度，不能说“赢得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的服务水准高很。", "corrected_sentence": "这家公司的服务水准很高。", "error_description": "错误在“水准高很”：程度副词〈很〉应放在形容词〈高〉前面，应说“服务水准很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校要增加教学水准。", "corrected_sentence": "学校要提高教学水准。", "error_description": "搭配错误：〈水准〉应与〈提高〉搭配，说“提高教学水准”，不能说“增加教学水准”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
