INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93635, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "没法是没有办法，做不了。", "primary_collocate": null, "pronunciation": "méi fǎ", "ipa": "mei˧˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "这道题太难，我没法做。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的腿很疼，没法走路。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一句话也不说，我们真没法帮他。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太远了，今天没法去。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音太小，我没法听清楚。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不告诉我，我没法决定。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业太多，今天我没法玩了。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很生气，我没法跟他谈。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有网，我没法查资料。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题，老师也没法回答。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没法儿", "label": "儿化词"}], "register": "口语", "sense_fingerprint": "想不出办法，事情做不了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdffcdca-4576-4326-9e48-c5ba571a4003') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93635, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没法", "is_correct": true, "explanation": "正确。“太难”说明客观上无法完成，只有“没法”能表达这一层意思。"}, {"text": "敢", "is_correct": false, "explanation": "搭配：“敢”表示有胆量去做，多用于冒险行为，不与“太难”这类难度描述搭配。"}, {"text": "爱", "is_correct": false, "explanation": "语义：“爱”表示喜欢，“这道题太难，我爱做”前后语义不协调。"}, {"text": "乐于", "is_correct": false, "explanation": "语义：“乐于”表示乐意去做，与“太难”所描述的困难情况相矛盾。"}], "explanations": {"没法": "正确。“太难”说明客观上无法完成，只有“没法”能表达这一层意思。", "敢": "搭配：“敢”表示有胆量去做，多用于冒险行为，不与“太难”这类难度描述搭配。", "爱": "语义：“爱”表示喜欢，“这道题太难，我爱做”前后语义不协调。", "乐于": "语义：“乐于”表示乐意去做，与“太难”所描述的困难情况相矛盾。"}, "sentence_index": 0, "correct_answer": "没法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天有空，也很想去，所以没法去。", "explanation": "这里应该用〈能〉。没法表示客观上做不到，而这里有空又想去，没有任何阻碍。"}, {"text": "今天的作业很简单，我没法做完。", "explanation": "这里应该用〈能〉。作业很简单，没有困难，不能说做不到。"}, {"text": "明天是周末，学校放假，你没法去上学。", "explanation": "这里应该用〈不用〉。没法表示做不到，而这里是放假、没有必要去上学，要用“不用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93635, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没法", "is_correct": true, "explanation": "正确。“作业太多”造成无法玩的客观限制，只有“没法”表达这一意思。"}, {"text": "能", "is_correct": false, "explanation": "语义：“能”表示有能力或许可，“作业太多，今天我能玩了”因果不通。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与“作业太多”引出的因果关系不搭，句意不通。"}, {"text": "愿", "is_correct": false, "explanation": "语义：“愿”表示愿意，“作业太多”与愿意玩的意思相矛盾，因果不通。"}], "explanations": {"没法": "正确。“作业太多”造成无法玩的客观限制，只有“没法”表达这一意思。", "能": "语义：“能”表示有能力或许可，“作业太多，今天我能玩了”因果不通。", "讨厌": "语义：“讨厌”表示厌恶，与“作业太多”引出的因果关系不搭，句意不通。", "愿": "语义：“愿”表示愿意，“作业太多”与愿意玩的意思相矛盾，因果不通。"}, "sentence_index": 6, "correct_answer": "没法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜很好吃，我也很饿，所以没法吃。", "explanation": "这里应该用〈想〉。没法表示客观上做不到，而这里既好吃又饿，没有阻碍。"}, {"text": "今天天气很好，你没法去公园散步。", "explanation": "这里应该用〈可以〉。没法表示客观上做不到，而这里天气很好，并没有阻碍，要用“可以”。"}, {"text": "他的腿很健康，没法走路。", "explanation": "这里应该用〈能〉。没法表示做不到，而这里他的腿很健康，能走路，要用“能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93635, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的脚扭伤了，我不没法跑步。", "corrected_sentence": "我的脚扭伤了，没法跑步。", "error_description": "错误在于“不”与“没法”重复否定。“没法”本身已含否定，应去掉“不”，改为“没法跑步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93635, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这周太忙了，我很没法陪你逛街。", "corrected_sentence": "这周太忙了，我没法陪你逛街。", "error_description": "错误在于“很”修饰“没法”。“没法”是表示做不到的否定说法，不能受程度副词修饰，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
