INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93636, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "没有办法；无法。", "primary_collocate": null, "pronunciation": "méi fǎ", "ipa": "mei˧˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "雨太大，我没法出门。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的电话关机了，我没法找到他。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么吵，我没法睡觉。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，我们没法准时到。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有钥匙，我们没法进屋。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电，我没法给你打电话。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太忙了，没法来参加会议。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情已经这样，我也没法再说什么。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生病了，妈妈没法上班。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱不够，我没法买这件衣服。", "target_word": "没法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没法儿", "label": "儿化词"}], "register": "口语", "sense_fingerprint": "因条件限制而没有办法做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdffcdca-4576-4326-9e48-c5ba571a4003') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93636, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没法", "is_correct": true, "explanation": "正确。“没法”表示因条件限制而无法做某事，与“雨太大”这一客观原因相合。"}, {"text": "能", "is_correct": false, "explanation": "语义：“能”表示有能力或许可，“雨太大，我能出门”前后因果不通，读起来像雨再大也能出去。"}, {"text": "爱", "is_correct": false, "explanation": "语义：“爱”表示喜欢，“雨太大，我爱出门”与前半句的因果关系不协调。"}, {"text": "敢", "is_correct": false, "explanation": "搭配：“敢”多用于有风险的主动行为，不与“雨太大”这类客观条件搭配。"}], "explanations": {"没法": "正确。“没法”表示因条件限制而无法做某事，与“雨太大”这一客观原因相合。", "能": "语义：“能”表示有能力或许可，“雨太大，我能出门”前后因果不通，读起来像雨再大也能出去。", "爱": "语义：“爱”表示喜欢，“雨太大，我爱出门”与前半句的因果关系不协调。", "敢": "搭配：“敢”多用于有风险的主动行为，不与“雨太大”这类客观条件搭配。"}, "sentence_index": 0, "correct_answer": "没法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门开着，我也有时间，所以没法进去。", "explanation": "这里应该用〈能〉。没法表示因条件限制做不到，而这里门开着又有时间，没有限制。"}, {"text": "明天天气很好，没法下雨。", "explanation": "这里应该用〈不会〉。没法表示客观上做不到，而这里是天气好、推测不会下雨，要用“不会”。"}, {"text": "明天不必来开会，所以我没法来。", "explanation": "这里应该用〈不来〉。没法表示客观上做不到，而这里只是没有必要来，并非做不到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93636, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没法", "is_correct": true, "explanation": "正确。“太忙了”造成无法出席，只有“没法”表示客观上做不到。"}, {"text": "乐意", "is_correct": false, "explanation": "语义：“乐意”表示情愿，与“太忙了”导致无法出席的因果关系不符。"}, {"text": "愿", "is_correct": false, "explanation": "语义：“愿”表示愿意，与“太忙了”导致无法出席的因果关系相矛盾。"}, {"text": "肯", "is_correct": false, "explanation": "搭配：“肯”表示同意或愿意接受，常用于“不肯”，不与“太忙了”这类客观条件搭配。"}], "explanations": {"没法": "正确。“太忙了”造成无法出席，只有“没法”表示客观上做不到。", "乐意": "语义：“乐意”表示情愿，与“太忙了”导致无法出席的因果关系不符。", "愿": "语义：“愿”表示愿意，与“太忙了”导致无法出席的因果关系相矛盾。", "肯": "搭配：“肯”表示同意或愿意接受，常用于“不肯”，不与“太忙了”这类客观条件搭配。"}, "sentence_index": 6, "correct_answer": "没法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天天气晴朗，我没法带伞出门。", "explanation": "这里应该用〈不带〉。没法表示客观上做不到，而这里只是天气好、没有必要带伞，要用“不带”。"}, {"text": "这张票是免费的，所以我没法买。", "explanation": "这里应该用〈不买〉。没法表示做不到，而这里是票本来免费、没有必要买，只是不去买。"}, {"text": "今天不用上班，你没法来公司。", "explanation": "这里应该用〈不来〉。没法表示客观上做不到，而这里只是不需要上班，并非不能来，要用“不来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
