INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月房租太贵，我很没法存钱。", "corrected_sentence": "这个月房租太贵，我没法存钱。", "error_description": "错误在于“很”修饰“没法”。“没法”是表示做不到的否定说法，不能受程度副词修饰，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
