INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93637, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有意义是做了也没什么用。", "primary_collocate": null, "pronunciation": "méi yǒu yì yì", "ipa": "mei̯˧˥ joʊ̯˨˩˦ i˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "现在后悔没有意义。", "target_word": "没有意义", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "事情已经这样了，哭也没有意义。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不努力，只是说话没有意义。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车已经走了，再跑也没有意义。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试已经结束了，担心没有意义。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不听你的，再说也没有意义。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有意义的事，我不想再做了。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不改变方法，一直练习也没有意义。", "target_word": "没有意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛已经输了，生气没有意义。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯都坏了，再等也没有意义。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做了也没用，白费力气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781e042f-01c8-4179-94a7-75f6a8a36a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93637, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没有意义", "is_correct": true, "explanation": "正确。〈没有意义〉指后悔也没用，与句子相符。"}, {"text": "好吃", "is_correct": false, "explanation": "搭配：“好吃”说食物的味道，不能用于“后悔”。"}, {"text": "发烫", "is_correct": false, "explanation": "语义：“发烫”指温度高，与后悔无关。"}, {"text": "绿色", "is_correct": false, "explanation": "搭配：“绿色”是颜色，不能用来形容“后悔”。"}], "explanations": {"没有意义": "正确。〈没有意义〉指后悔也没用，与句子相符。", "好吃": "搭配：“好吃”说食物的味道，不能用于“后悔”。", "发烫": "语义：“发烫”指温度高，与后悔无关。", "绿色": "搭配：“绿色”是颜色，不能用来形容“后悔”。"}, "sentence_index": 0, "correct_answer": "没有意义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饿了，吃饭也没有意义。", "explanation": "这里应该用〈有用〉。〈没有意义〉说做了也没用，饿了吃饭很有用，语境不符。"}, {"text": "这把剪刀没有意义，剪纸很方便。", "explanation": "这里应该用〈有用〉。〈没有意义〉说做了也没用，而后半句说剪纸很方便，前后矛盾。"}, {"text": "这台机器没有意义，能测出很小的误差。", "explanation": "这里应该用〈精密〉。〈没有意义〉说做了也没用，而这台机器能测出误差，两句前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93637, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没有意义", "is_correct": true, "explanation": "正确。〈没有意义〉修饰“事”，指做了也没用的事，与句子相符。"}, {"text": "宽敞", "is_correct": false, "explanation": "语义：“宽敞”说空间大，不能形容事情。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”指形状，与事情无关。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：“冷”说温度，不能用来形容事情。"}], "explanations": {"没有意义": "正确。〈没有意义〉修饰“事”，指做了也没用的事，与句子相符。", "宽敞": "语义：“宽敞”说空间大，不能形容事情。", "圆": "语义：“圆”指形状，与事情无关。", "冷": "搭配：“冷”说温度，不能用来形容事情。"}, "sentence_index": 6, "correct_answer": "没有意义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脚没有意义，走路很慢。", "explanation": "这里应该用〈很疼〉。〈没有意义〉说做了也没用或没有含义，不能用来形容脚的感觉。"}, {"text": "这杯茶的温度没有意义，可以喝了。", "explanation": "这里应该用〈正好〉。〈没有意义〉说做了也没用，不能用来说温度是否合适。"}, {"text": "这把尺子没有意义，量出了正确的长度。", "explanation": "这里应该用〈精确〉。〈没有意义〉说做了也没用，而这把尺子量出了正确的长度，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "后悔也没有意义过，还是向前看吧。", "corrected_sentence": "后悔也没有意义了，还是向前看吧。", "error_description": "错误在“过”：这里说现在后悔已经没用，〈没有意义〉后应该用〈了〉表示现在的情况，不能用〈过〉表示过去的经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
