INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93638, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有意义", "is_correct": true, "explanation": "正确。〈有意义〉与〈没有意义〉相反，指有价值或含义。"}, {"text": "漂亮", "is_correct": false, "explanation": "不是反义：〈漂亮〉形容外貌，与价值或含义无关。"}, {"text": "聪明", "is_correct": false, "explanation": "不是反义：〈聪明〉形容头脑，与此义无关。"}, {"text": "便宜", "is_correct": false, "explanation": "不是反义：〈便宜〉指价格低，与价值或含义无关。"}], "correct_answer": "有意义", "explanations": {"有意义": "正确。〈有意义〉与〈没有意义〉相反，指有价值或含义。", "漂亮": "不是反义：〈漂亮〉形容外貌，与价值或含义无关。", "聪明": "不是反义：〈聪明〉形容头脑，与此义无关。", "便宜": "不是反义：〈便宜〉指价格低，与价值或含义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
