INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93638, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有价值或实际用处；没有含义。", "primary_collocate": null, "pronunciation": "méi yǒu yì yì", "ipa": "mei̯˧˥ joʊ̯˨˩˦ i˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "这个词在这里没有意义。", "target_word": "没有意义", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些数字没有意义，我看不懂。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写的那句话没有意义。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张旧地图现在没有意义了。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对我来说，钱多钱少没有意义。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一首没有人听的歌没有意义。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题没有意义，所以老师没回答。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，这个句子没有意义，要改。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有意义的工作，他不想做。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得这样的比赛没有意义。", "target_word": "没有意义", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "没有价值或含义，不值得", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781e042f-01c8-4179-94a7-75f6a8a36a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93638, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没有意义", "is_correct": true, "explanation": "正确。〈没有意义〉指词在这里没有价值或含义，与句子相符。"}, {"text": "生气", "is_correct": false, "explanation": "搭配：“生气”说人的情绪，不能用来形容词语。"}, {"text": "发烫", "is_correct": false, "explanation": "语义：“发烫”指温度高，词语没有温度。"}, {"text": "好吃", "is_correct": false, "explanation": "搭配：“好吃”说食物的味道，不能用于词语。"}], "explanations": {"没有意义": "正确。〈没有意义〉指词在这里没有价值或含义，与句子相符。", "生气": "搭配：“生气”说人的情绪，不能用来形容词语。", "发烫": "语义：“发烫”指温度高，词语没有温度。", "好吃": "搭配：“好吃”说食物的味道，不能用于词语。"}, "sentence_index": 0, "correct_answer": "没有意义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤没有意义，淡得很。", "explanation": "这里应该用〈没有味道〉。〈没有味道〉说食物的口感，〈没有意义〉说做了也没用或没有含义，不能用来形容汤的味道。"}, {"text": "这首歌很没有意义，大家都爱听。", "explanation": "这里应该用〈好听〉。〈没有意义〉说没有价值或含义，不能用来说歌曲是否动听；句中“大家都爱听”也与之矛盾。"}, {"text": "他的头发没有意义，有点干。", "explanation": "这里应该用〈没有光泽〉。〈没有光泽〉说头发的亮度，〈没有意义〉说做了也没用或没有含义，不能用来描述头发的亮度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没有意义", "is_correct": true, "explanation": "正确。〈没有意义〉指问题没有价值，所以老师不回答，前后相符。"}, {"text": "好听", "is_correct": false, "explanation": "语义：“好听”说声音悦耳，不能用来形容问题。"}, {"text": "宽敞", "is_correct": false, "explanation": "语义：“宽敞”说空间大，与问题无关。"}, {"text": "绿色", "is_correct": false, "explanation": "搭配：“绿色”指颜色，不能用来说问题。"}], "explanations": {"没有意义": "正确。〈没有意义〉指问题没有价值，所以老师不回答，前后相符。", "好听": "语义：“好听”说声音悦耳，不能用来形容问题。", "宽敞": "语义：“宽敞”说空间大，与问题无关。", "绿色": "搭配：“绿色”指颜色，不能用来说问题。"}, "sentence_index": 6, "correct_answer": "没有意义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室里没有意义，大家都在学习。", "explanation": "这里应该用〈安静〉。〈安静〉说没有声音，〈没有意义〉说没有价值或含义，不能用来形容教室里的声音情况。"}, {"text": "他的手没有意义，我想帮他暖一暖。", "explanation": "这里应该用〈很冷〉。〈没有意义〉说没有价值，不能用来形容手的冷热。"}, {"text": "学校离家没有意义，他每天骑车上学。", "explanation": "这里应该用〈很远〉。〈没有意义〉不能用来说两地之间的距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次争论不没有意义，我们不再吵了。", "corrected_sentence": "这次争论没有意义，我们不再吵了。", "error_description": "否定词重复：〈没有意义〉本身已表示否定，前面再加〈不〉说法别扭，应直接说“没有意义”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次比赛已经没有意义着。", "corrected_sentence": "这次比赛已经没有意义了。", "error_description": "错误在“着”：〈没有意义〉表示状态的变化，应用〈了〉，不能用〈着〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
