INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93639, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "沙滩是海边软软的沙地。", "primary_collocate": null, "pronunciation": "shā tān", "ipa": "ʂa˥ tʰan˥", "syllable_count": 2, "sentences": [{"text": "我们在沙滩上走路。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在沙滩上玩沙子。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的沙滩软软的。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她光着脚走在沙滩上。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天很多人去沙滩晒太阳。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在沙滩上捡到了一个漂亮的贝壳。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在沙滩上堆了一座沙堡。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙滩上有很多小螃蟹。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在沙滩上看海。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在沙滩上写下了我的名字。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "海边软软的沙地，人们玩耍休息的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b69c20c8-55e0-48cc-a4ad-ae6e68dd460f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93639, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沙滩", "is_correct": true, "explanation": "沙滩是海边软软的沙地，可以在上面走路，符合句意。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是放书本的桌子，人不能在上面走路。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以踩踏行走的地面。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“上”表示表面，房间是封闭空间，应说“在房间里”。"}], "explanations": {"沙滩": "沙滩是海边软软的沙地，可以在上面走路，符合句意。", "课桌": "语义：课桌是放书本的桌子，人不能在上面走路。", "天空": "语义：天空不是可以踩踏行走的地面。", "房间": "搭配：“上”表示表面，房间是封闭空间，应说“在房间里”。"}, "sentence_index": 0, "correct_answer": "沙滩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在海边捡了一些沙滩。", "explanation": "这里应该用〈沙子〉。沙滩指大片沙地，不是可以捡拾的颗粒，捡的东西要说“沙子”。"}, {"text": "我把沙滩放进了冰箱。", "explanation": "这里应该用〈西瓜〉。沙滩是海边的大片沙地，不能放进冰箱；放进冰箱的要说“西瓜”之类的东西。"}, {"text": "我们在沙滩里游泳。", "explanation": "这里应该用〈大海〉。沙滩是陆地上的沙地，不能说“在沙滩里游泳”，应说“在海里游泳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93639, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙滩", "is_correct": true, "explanation": "沙滩是软软的沙地，孩子可以在上面堆沙堡，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是厨房电器，不能在上面堆沙堡。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是家电，孩子不能在上面堆沙堡。"}, {"text": "书架", "is_correct": false, "explanation": "语义：书架是放书的家具，不能在上面堆沙堡。"}], "explanations": {"沙滩": "沙滩是软软的沙地，孩子可以在上面堆沙堡，符合句意。", "冰箱": "语义：冰箱是厨房电器，不能在上面堆沙堡。", "电视": "语义：电视是家电，孩子不能在上面堆沙堡。", "书架": "语义：书架是放书的家具，不能在上面堆沙堡。"}, "sentence_index": 6, "correct_answer": "沙滩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "骆驼在沙滩上走了三天，一直没有找到水。", "explanation": "这里应该用〈沙漠〉。骆驼长途跋涉的是干旱的沙漠，沙滩在海边，不能这样说。"}, {"text": "书包里装满了沙滩。", "explanation": "这里应该用〈石子〉。沙滩是大片沙地，不能装进书包；装满书包的小颗粒要说“石子”。"}, {"text": "妈妈在厨房里煮沙滩。", "explanation": "这里应该用〈饺子〉。沙滩是地面，不能下锅煮，煮的东西要说“饺子”之类的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那座沙滩上没有一个人。", "corrected_sentence": "那片沙滩上没有一个人。", "error_description": "量词错误：“沙滩”应搭配量词“片”，不用“座”。“座”多用于山、桥、楼房等。错误形式：那座沙滩；正确形式：那片沙滩。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们沙滩上搭了一个帐篷。", "corrected_sentence": "我们在沙滩上搭了一个帐篷。", "error_description": "方位短语错误：动作的地点须用“在……上”引出，“沙滩上”前缺少“在”。错误形式：我们沙滩上搭了一个帐篷；正确形式：我们在沙滩上搭了一个帐篷。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
