INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93640, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海边、河边由沙子堆积而成的平地。", "primary_collocate": null, "pronunciation": "shā tān", "ipa": "ʂa˥ tʰan˥", "syllable_count": 2, "sentences": [{"text": "河边有一片很长的沙滩。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水退了，沙滩变得很宽。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的旁边有一片小沙滩。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "涨潮的时候，海水盖住了沙滩。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个海边的沙滩很干净。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在沙滩上打排球。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着沙滩走了一个小时。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的沙滩是白色的。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里的沙滩很安静。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在沙滩边的小店吃海鲜。", "target_word": "沙滩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "海边或河边由沙子堆积形成的平地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b69c20c8-55e0-48cc-a4ad-ae6e68dd460f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93640, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沙滩", "is_correct": true, "explanation": "沙滩是河边或海边由沙子堆成的平地，可以说“一片很长的沙滩”，符合句意。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：量词“片”不用于书本，应说“一本”，且书本不是平地。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是家具，不是河边的平地，不能说“很长的一片”。"}, {"text": "牙刷", "is_correct": false, "explanation": "语义：牙刷是日用品，不是河边的平地，不能说“一片很长的牙刷”。"}], "explanations": {"沙滩": "沙滩是河边或海边由沙子堆成的平地，可以说“一片很长的沙滩”，符合句意。", "课本": "搭配：量词“片”不用于书本，应说“一本”，且书本不是平地。", "书桌": "语义：书桌是家具，不是河边的平地，不能说“很长的一片”。", "牙刷": "语义：牙刷是日用品，不是河边的平地，不能说“一片很长的牙刷”。"}, "sentence_index": 0, "correct_answer": "沙滩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用沙滩给我做了一件衣服。", "explanation": "这里应该用〈布〉。沙滩是海边或河边的沙地，不能用来做衣服，做衣服要用“布”。"}, {"text": "孩子们在沙滩里游泳。", "explanation": "这里应该用〈大海〉。沙滩是陆地上的沙地，不能说“在沙滩里游泳”，应说“在海里游泳”。"}, {"text": "工人把沙滩倒进了模子里。", "explanation": "这里应该用〈沙子〉。沙滩指大片地面，不能像材料一样倒进模子；可以倒进模子的散沙要说“沙子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙滩", "is_correct": true, "explanation": "沙滩是可以沿着走的平地，符合句意。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯是运送人的设备，不是可以沿着走的路线。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是纸质单据，不是可以沿着行走的地方。"}, {"text": "拖鞋", "is_correct": false, "explanation": "搭配：“沿着”后接路线或边缘，“拖鞋”不能构成行走的路线。"}], "explanations": {"沙滩": "沙滩是可以沿着走的平地，符合句意。", "电梯": "语义：电梯是运送人的设备，不是可以沿着走的路线。", "账单": "语义：账单是纸质单据，不是可以沿着行走的地方。", "拖鞋": "搭配：“沿着”后接路线或边缘，“拖鞋”不能构成行走的路线。"}, "sentence_index": 6, "correct_answer": "沙滩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在沙滩上滑冰。", "explanation": "这里应该用〈冰面〉。沙滩是松软的沙地，不能滑冰，滑冰要在冰面上。"}, {"text": "他在杯子里倒了一些沙滩。", "explanation": "这里应该用〈水〉。沙滩是大片沙地，不是液体，不能倒进杯子。"}, {"text": "他把沙滩放进了锅里。", "explanation": "这里应该用〈鸡蛋〉。沙滩是地面，不能放进锅里，放进锅里的要说“鸡蛋”之类的食材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "潮水退了，沙滩露下来了。", "corrected_sentence": "潮水退了，沙滩露出来了。", "error_description": "补语错误：表示显现时，“露”后应接“出来”，不能接“下来”。错误形式：沙滩露下来了；正确形式：沙滩露出来了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他沙滩边钓了一条鱼。", "corrected_sentence": "他在沙滩边钓了一条鱼。", "error_description": "方位短语错误：动作的地点须用“在……边”引出，“沙滩边”前缺少“在”。错误形式：他沙滩边钓了一条鱼；正确形式：他在沙滩边钓了一条鱼。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
