INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93641, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海上是在大海的水面上。", "primary_collocate": null, "pronunciation": "hǎi shàng", "ipa": "xaɪ˨˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "海上今天风很大。", "target_word": "海上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海上有一只白色的小船。", "target_word": "海上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们在海上看到了日出。", "target_word": "海上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海上的天气变化很快。", "target_word": "海上", "complexity_tier": "T3", "furigana": "hǎi shàng de tiān qì biàn huà hěn kuài", "sentence_source": "generated"}, {"text": "很多渔民在海上工作。", "target_word": "海上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海上突然下起大雨来。", "target_word": "海上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他第一次在海上过夜。", "target_word": "海上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上有很多海鸟在飞。", "target_word": "海上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天的海上特别热闹。", "target_word": "海上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海上看不到一座山。", "target_word": "海上", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大海的水面上这个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6b8e2c5-1682-4b33-9c63-d8dce1b8d46c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93641, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海上", "is_correct": true, "explanation": "正确：海上指大海的水面之上，与“今天风很大”相符。"}, {"text": "室内", "is_correct": false, "explanation": "语义：室内没有大风，与句中“风很大”矛盾，句子说不通。"}, {"text": "海底", "is_correct": false, "explanation": "语义：海底不受风吹，与“风很大”矛盾，句子说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房在室内，不会刮大风，与“风很大”矛盾，句子说不通。"}], "explanations": {"海上": "正确：海上指大海的水面之上，与“今天风很大”相符。", "室内": "语义：室内没有大风，与句中“风很大”矛盾，句子说不通。", "海底": "语义：海底不受风吹，与“风很大”矛盾，句子说不通。", "厨房": "语义：厨房在室内，不会刮大风，与“风很大”矛盾，句子说不通。"}, "sentence_index": 0, "correct_answer": "海上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们潜到海上，看到了很多小鱼。", "explanation": "这里应该用〈海里〉。海上指海面之上，潜下去看鱼是在水下，要说“海里”。"}, {"text": "我们在海上堆沙堡，玩了一下午。", "explanation": "这里应该用〈沙滩上〉。海上指水面，堆沙堡要在沙滩上。"}, {"text": "海上有很多珊瑚。", "explanation": "这里应该用〈海底〉。珊瑚生长在海底，海上指水面之上，不能这样表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93641, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海上", "is_correct": true, "explanation": "正确：在海上过夜，符合“第一次”的语境。"}, {"text": "课堂", "is_correct": false, "explanation": "语义：课堂不能用于过夜，句子说不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“过夜”通常不以天空作地点，搭配不当。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：人不能在冰箱里过夜，句子说不通。"}], "explanations": {"海上": "正确：在海上过夜，符合“第一次”的语境。", "课堂": "语义：课堂不能用于过夜，句子说不通。", "天空": "搭配：“过夜”通常不以天空作地点，搭配不当。", "冰箱": "语义：人不能在冰箱里过夜，句子说不通。"}, "sentence_index": 6, "correct_answer": "海上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海上的草原很大，牛羊很多。", "explanation": "这里应该用〈草原上〉。草原在陆地上，海上指水面，不能说海上的草原。"}, {"text": "海上的公路上跑着一辆辆汽车，很热闹。", "explanation": "这里应该用〈岸上〉。公路建在陆地上，海上指水面，不能说海上的公路。"}, {"text": "海上的稻田一片接一片，绿油油的。", "explanation": "这里应该用〈田里〉。稻子种在陆地的田里，海上指水面，不能说稻田在海上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93641, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在海上里看到了一条大鲸鱼。", "corrected_sentence": "我们在海上看到了一条大鲸鱼。", "error_description": "“海上”后面不能再加“里”，“在海上”已经是完整的地点状语，应说“在海上看到”。“海上里”不是词语，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93641, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔船在海上的行驶了一整天。", "corrected_sentence": "渔船在海上行驶了一整天。", "error_description": "“海上”后面不能直接加“的”再接动词，应说“在海上行驶”。加上“的”后“行驶”变成名词性成分，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d67f02-5185-4672-81f3-6afd9ba0a653') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
