INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93643, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93643, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "法号是和尚或尼姑的新名字。", "primary_collocate": null, "pronunciation": "fǎ hào", "ipa": "fa˨˩˦ xɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他出家以后有了新的法号。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师父给他起了一个法号。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位和尚的法号很好记。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小尼姑的法号叫慧心。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她入寺后得到了一个法号。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不再用原来的名字，只用法号。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都叫他的法号。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问老和尚的法号是什么。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个法号是师父起的。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的法号里有一个静字。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个法号", "label": "量词"}, {"form": "法號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，和尚或尼姑出家后用的新名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088928fc-a436-497e-8711-79f5a28a97a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93643, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法号", "is_correct": true, "explanation": "“法号”是出家后得到的新名字，“有了新的……”正好指这个。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：出家后不会有婚礼，与“出家”相矛盾。"}, {"text": "学位", "is_correct": false, "explanation": "语义：学位是读书得到的，与“出家”的情境不合。"}, {"text": "女朋友", "is_correct": false, "explanation": "语义：出家人要断绝男女关系，出家以后不会有新的女朋友，与“出家”相矛盾。"}], "explanations": {"法号": "“法号”是出家后得到的新名字，“有了新的……”正好指这个。", "婚礼": "语义：出家后不会有婚礼，与“出家”相矛盾。", "学位": "语义：学位是读书得到的，与“出家”的情境不合。", "女朋友": "语义：出家人要断绝男女关系，出家以后不会有新的女朋友，与“出家”相矛盾。"}, "sentence_index": 0, "correct_answer": "法号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同学们都叫他小胖，这是他的法号。", "explanation": "这里应该用〈绰号〉。法号是出家后由师父所取的名号，同学给的外号要说绰号。"}, {"text": "我是一名小学老师，我的法号叫王小明。", "explanation": "这里应该用〈名字〉。法号是僧尼出家后由师父所取的名号，普通人的名字不能说成法号。"}, {"text": "我在银行开了一个法号。", "explanation": "这里应该用〈账户〉。“开”搭配账户，法号是出家时取的名号，不能“开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93643, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法号", "is_correct": true, "explanation": "“法号”是他出家后的名号，“大家都叫他的”正好指称呼。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“叫”的对象是名字或称呼，工资不能被叫。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是物品，不能用“大家都叫他的”来称呼。"}, {"text": "身份证号", "is_correct": false, "explanation": "搭配：“叫”的对象是称谓或名字，身份证号是编码，不能被“叫”。"}], "explanations": {"法号": "“法号”是他出家后的名号，“大家都叫他的”正好指称呼。", "工资": "语义：“叫”的对象是名字或称呼，工资不能被叫。", "桌子": "语义：桌子是物品，不能用“大家都叫他的”来称呼。", "身份证号": "搭配：“叫”的对象是称谓或名字，身份证号是编码，不能被“叫”。"}, "sentence_index": 6, "correct_answer": "法号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "师父给他取了一本法号。", "explanation": "这里应该用〈个〉。“本”用于书册，法号不用“本”。"}, {"text": "寺里新来的弟子有一头法号。", "explanation": "这里应该用〈个〉。“头”用于牲畜，法号不能用“头”。"}, {"text": "她有一条法号。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，法号不用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93643, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他剃度以后，师父给他取了一条法号。", "corrected_sentence": "他剃度以后，师父给他取了一个法号。", "error_description": "量词错误：“法号”应用量词“个”。“条”用于细长的东西，不能用于法号。错误形式是“一条法号”，正确形式是“一个法号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93643, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "师父给我取了一个的新法号。", "corrected_sentence": "师父给我取了一个新法号。", "error_description": "错误在于“一个”和“新”之间多加了“的”。数量短语“一个”后直接接修饰语，中间不加“的”。应说“一个新法号”，不说“一个的新法号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
