INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93644, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "僧尼出家后所取的名号。", "primary_collocate": null, "pronunciation": "fǎ hào", "ipa": "fa˨˩˦ xɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "僧人出家后都会取法号。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的俗名叫王明，法号明心。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "寺里的人不叫他的俗名，只叫法号。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个法号有平安的意思。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上记着那位高僧的法号。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出家后改了法号。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师父写下了新弟子的法号。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这位大师的法号吗？", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的法号是从经书里选的。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅的法号没人不知道。", "target_word": "法号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个法号", "label": "量词"}, {"form": "法號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，僧人或尼姑出家后取的名号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088928fc-a436-497e-8711-79f5a28a97a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法号", "is_correct": true, "explanation": "“法号”是僧人出家后取的名号，“取”正好对应。"}, {"text": "戒律", "is_correct": false, "explanation": "搭配：“取”不能带“戒律”，戒律要说“受戒”或“遵守戒律”。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：出家后的僧人不会“取”游戏，与句意不合。"}, {"text": "女朋友", "is_correct": false, "explanation": "语义：僧人出家后不会取女朋友，与“出家”相矛盾。"}], "explanations": {"法号": "“法号”是僧人出家后取的名号，“取”正好对应。", "戒律": "搭配：“取”不能带“戒律”，戒律要说“受戒”或“遵守戒律”。", "游戏": "语义：出家后的僧人不会“取”游戏，与句意不合。", "女朋友": "语义：僧人出家后不会取女朋友，与“出家”相矛盾。"}, "sentence_index": 0, "correct_answer": "法号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位和尚的法号是教授。", "explanation": "这里应该用〈头衔〉。“教授”是职称，不能当作法号。"}, {"text": "同学们给他起的法号很可爱。", "explanation": "这里应该用〈绰号〉。法号是师父在僧人出家时所取，同学给的外号要说绰号。"}, {"text": "作家为自己取了一个法号。", "explanation": "这里应该用〈笔名〉。作家写作时用的是笔名，法号是出家后的名号，不是作家取的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法号", "is_correct": true, "explanation": "“法号”是僧人的名号，“师父写下了……的”正好指写下的名号。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，不是名号，“写下了新弟子的雨伞”不合句意。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是名号，“写下了新弟子的汽车”不合句意。"}, {"text": "月饼", "is_correct": false, "explanation": "语义：月饼是食品，不是名号，“写下了新弟子的月饼”不合句意。"}], "explanations": {"法号": "“法号”是僧人的名号，“师父写下了……的”正好指写下的名号。", "雨伞": "语义：雨伞是日用品，不是名号，“写下了新弟子的雨伞”不合句意。", "汽车": "语义：汽车不是名号，“写下了新弟子的汽车”不合句意。", "月饼": "语义：月饼是食品，不是名号，“写下了新弟子的月饼”不合句意。"}, "sentence_index": 6, "correct_answer": "法号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的法号很有名。", "explanation": "这里应该用〈名称〉。公司的名字叫名称，法号只指僧尼出家后的名号。"}, {"text": "你的手机法号是多少？", "explanation": "这里应该用〈号码〉。电话用的是号码，法号是僧尼的名号。"}, {"text": "我家小狗的法号叫豆豆。", "explanation": "这里应该用〈名字〉。动物的称呼是名字，法号只用于出家的僧尼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他入寺以后，师父为他取了一座法号。", "corrected_sentence": "他入寺以后，师父为他取了一个法号。", "error_description": "量词错误：“法号”应用量词“个”。“座”用于山、房屋等大型固定物，不能用于法号。错误形式是“一座法号”，正确形式是“一个法号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想知道他的法号们。", "corrected_sentence": "我想知道他的法号。", "error_description": "后缀错误：“们”只加在指人的名词后，“法号”指名号，不能说“法号们”。错误形式是“他的法号们”，正确形式是“他的法号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce34d5c8-1069-48d2-b285-555364cb3fb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
