INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93645, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "爬是手和脚一起用力，向上或向前走。", "primary_collocate": null, "pronunciation": "pá", "ipa": "pʰa˧˥", "syllable_count": 1, "sentences": [{"text": "小猫爬上了树。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝在地上爬得很快。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们爬到了山顶。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢爬树。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面墙很陡，他手脚并用才爬上去。", "target_word": "爬", "complexity_tier": "T3", "furigana": "pá", "sentence_source": "generated"}, {"text": "小男孩爬过墙，跑了。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累得爬不动了。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只虫子爬到我的手上。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人爬了两个小时才到山上。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边爬一边喘气。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爬了", "label": "完成体 了"}, {"form": "爬着", "label": "持续体 着"}, {"form": "爬过", "label": "经历体 过"}], "register": "中性", "sense_fingerprint": "手脚并用用力向上或向前走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdffcdca-4576-4326-9e48-c5ba571a4003') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93645, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爬", "is_correct": true, "explanation": "爬（pá）：手脚并用向上或向前走，即本词的意思。"}, {"text": "怕", "is_correct": false, "explanation": "pà（第四声）与 pá（第二声）声调不同，意思是害怕。"}, {"text": "趴", "is_correct": false, "explanation": "pā（第一声）与 pá（第二声）声调不同，意思是身体伏在某物上。"}, {"text": "拔", "is_correct": false, "explanation": "bá 与 pá 声母不同（b 不送气，p 送气），声调相同，意思是拔出。"}, {"text": "盘", "is_correct": false, "explanation": "pán 与 pá 韵母不同（-an 与 -a），声调相同，意思是盘子。"}], "explanations": {"爬": "爬（pá）：手脚并用向上或向前走，即本词的意思。", "怕": "pà（第四声）与 pá（第二声）声调不同，意思是害怕。", "趴": "pā（第一声）与 pá（第二声）声调不同，意思是身体伏在某物上。", "拔": "bá 与 pá 声母不同（b 不送气，p 送气），声调相同，意思是拔出。", "盘": "pán 与 pá 韵母不同（-an 与 -a），声调相同，意思是盘子。"}, "sentence_index": null, "correct_answer": "爬"}, "level_3": {"options": [{"text": "爬", "is_correct": true, "explanation": "爬：手脚并用向上移动，与“小猫”和“上了树”搭配，正确。"}, {"text": "游", "is_correct": false, "explanation": "语义：游是在水中前进，不能用来表示小猫向上攀到树上。"}, {"text": "漂", "is_correct": false, "explanation": "语义：漂是浮动或随风飘动，与手脚并用地攀上树的动作不符。"}, {"text": "驾", "is_correct": false, "explanation": "搭配：“驾”的对象是车、马等交通工具，不能与“小猫”搭配。"}], "explanations": {"爬": "爬：手脚并用向上移动，与“小猫”和“上了树”搭配，正确。", "游": "语义：游是在水中前进，不能用来表示小猫向上攀到树上。", "漂": "语义：漂是浮动或随风飘动，与手脚并用地攀上树的动作不符。", "驾": "搭配：“驾”的对象是车、马等交通工具，不能与“小猫”搭配。"}, "sentence_index": 0, "correct_answer": "爬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们爬火车去北京。", "explanation": "这里应该用〈乘〉。爬指手脚并用地移动，不能用于乘坐火车；“乘火车”才是正确说法。"}, {"text": "他正在爬作业。", "explanation": "这里应该用〈做〉。爬指手脚并用地移动，不能用于作业；“做作业”才是正确说法。"}, {"text": "他爬了一场考试。", "explanation": "这里应该用〈参加〉。爬不能用于考试，“参加考试”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93645, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爬", "is_correct": true, "explanation": "爬（pá）：手脚并用向上或向前走，即本词的意思。"}, {"text": "麻", "is_correct": false, "explanation": "má（第二声）与 pá（第二声）声母不同（m 与 p），意思是麻。"}, {"text": "排", "is_correct": false, "explanation": "pái（第二声）与 pá（第二声）韵母不同（-ai 与 -a），意思是排列。"}, {"text": "皮", "is_correct": false, "explanation": "pí（第二声）与 pá（第二声）韵母不同（-i 与 -a），意思是皮。"}, {"text": "啪", "is_correct": false, "explanation": "pā（第一声）与 pá（第二声）声调不同，多用于拟声，表示拍击声。"}], "explanations": {"爬": "爬（pá）：手脚并用向上或向前走，即本词的意思。", "麻": "má（第二声）与 pá（第二声）声母不同（m 与 p），意思是麻。", "排": "pái（第二声）与 pá（第二声）韵母不同（-ai 与 -a），意思是排列。", "皮": "pí（第二声）与 pá（第二声）韵母不同（-i 与 -a），意思是皮。", "啪": "pā（第一声）与 pá（第二声）声调不同，多用于拟声，表示拍击声。"}, "sentence_index": null, "correct_answer": "爬"}, "level_3": {"options": [{"text": "爬", "is_correct": true, "explanation": "爬：手脚并用移动，与“累得”和“不动了”搭配，正确。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：嚼是咀嚼食物，不能用来表示人累到动不了。"}, {"text": "吞", "is_correct": false, "explanation": "语义：吞是咽下，与因疲劳而动不了的意思无关。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬不动”多指食物太硬，不能用来形容“累得”。"}], "explanations": {"爬": "爬：手脚并用移动，与“累得”和“不动了”搭配，正确。", "嚼": "语义：嚼是咀嚼食物，不能用来表示人累到动不了。", "吞": "语义：吞是咽下，与因疲劳而动不了的意思无关。", "咬": "搭配：“咬不动”多指食物太硬，不能用来形容“累得”。"}, "sentence_index": 6, "correct_answer": "爬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈爬了一个西瓜。", "explanation": "这里应该用〈切〉。爬是手脚并用的移动，不能用于切东西。"}, {"text": "我爬了一本书。", "explanation": "这里应该用〈买〉。爬不能用于买书，“买一本书”才是正确说法。"}, {"text": "请你爬好雨伞，别忘了带。", "explanation": "这里应该用〈拿〉。爬不能用于拿东西，“拿好雨伞”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子爬了上屋顶。", "corrected_sentence": "孩子爬上了屋顶。", "error_description": "错误：“爬了上屋顶”。正确：“爬上了屋顶”。“了”应放在补语“上”之后，表示动作完成，放在动词和补语之间是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从树上爬来下了。", "corrected_sentence": "他从树上爬下来了。", "error_description": "错误：“爬来下了”。正确：“爬下来了”。趋向补语“下来”是固定组合，不能倒置成“来下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
