INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93646, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "手脚并用向上或向前移动。", "primary_collocate": null, "pronunciation": "pá", "ipa": "pʰa˧˥", "syllable_count": 1, "sentences": [{"text": "你看，那个小孩正在向前爬。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们爬上山，看到了太阳。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗爬不上这面高墙。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从窗口爬进了房间。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛爬到墙上去了。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天爬了一座高山。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小宝宝刚学会爬。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们爬着往前走。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的猫常常爬到桌子上。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要爬这棵树，很危险。", "target_word": "爬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爬了", "label": "完成体 了"}, {"form": "爬着", "label": "持续体 着"}, {"form": "爬过", "label": "经历体 过"}], "register": "中性", "sense_fingerprint": "手脚并用向上或向前移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdffcdca-4576-4326-9e48-c5ba571a4003') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93646, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爬", "is_correct": true, "explanation": "爬（pá）：手脚并用向上或向前移动，即本词的意思。"}, {"text": "怕", "is_correct": false, "explanation": "pà（第四声）与 pá（第二声）声调不同，意思是害怕。"}, {"text": "趴", "is_correct": false, "explanation": "pā（第一声）与 pá（第二声）声调不同，意思是身体伏在某物上。"}, {"text": "拔", "is_correct": false, "explanation": "bá 与 pá 声母不同（b 不送气，p 送气），声调相同，意思是拔出。"}, {"text": "盘", "is_correct": false, "explanation": "pán 与 pá 韵母不同（-an 与 -a），声调相同，意思是盘子。"}], "explanations": {"爬": "爬（pá）：手脚并用向上或向前移动，即本词的意思。", "怕": "pà（第四声）与 pá（第二声）声调不同，意思是害怕。", "趴": "pā（第一声）与 pá（第二声）声调不同，意思是身体伏在某物上。", "拔": "bá 与 pá 声母不同（b 不送气，p 送气），声调相同，意思是拔出。", "盘": "pán 与 pá 韵母不同（-an 与 -a），声调相同，意思是盘子。"}, "sentence_index": null, "correct_answer": "爬"}, "level_3": {"options": [{"text": "爬", "is_correct": true, "explanation": "爬：手脚并用向前移动，与“小孩”和“向前”搭配，正确。"}, {"text": "飞", "is_correct": false, "explanation": "语义：小孩不能飞，“向前飞”也不是手脚并用的动作。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是发出声音，不能表示身体向前移动。"}, {"text": "画", "is_correct": false, "explanation": "搭配：“画”需要画面或图形作对象，不能说“向前画”。"}], "explanations": {"爬": "爬：手脚并用向前移动，与“小孩”和“向前”搭配，正确。", "飞": "语义：小孩不能飞，“向前飞”也不是手脚并用的动作。", "唱": "语义：唱是发出声音，不能表示身体向前移动。", "画": "搭配：“画”需要画面或图形作对象，不能说“向前画”。"}, "sentence_index": 0, "correct_answer": "爬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他爬汽车去上班。", "explanation": "这里应该用〈开〉。爬指手脚并用地移动，不能用于驾驶汽车；“开汽车去上班”才是正确说法。"}, {"text": "我们爬了一场电影。", "explanation": "这里应该用〈看〉。爬不能与电影搭配，“看电影”才是正确说法。"}, {"text": "她爬上了眼镜。", "explanation": "这里应该用〈戴〉。爬不能用于眼镜，“戴上眼镜”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93646, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爬", "is_correct": true, "explanation": "爬（pá）：手脚并用向上或向前移动，即本词的意思。"}, {"text": "麻", "is_correct": false, "explanation": "má（第二声）与 pá（第二声）声母不同（m 与 p），意思是麻。"}, {"text": "排", "is_correct": false, "explanation": "pái（第二声）与 pá（第二声）韵母不同（-ai 与 -a），意思是排列。"}, {"text": "皮", "is_correct": false, "explanation": "pí（第二声）与 pá（第二声）韵母不同（-i 与 -a），意思是皮。"}, {"text": "啪", "is_correct": false, "explanation": "pā（第一声）与 pá（第二声）声调不同，多用于拟声，表示拍击声。"}], "explanations": {"爬": "爬（pá）：手脚并用向上或向前移动，即本词的意思。", "麻": "má（第二声）与 pá（第二声）声母不同（m 与 p），意思是麻。", "排": "pái（第二声）与 pá（第二声）韵母不同（-ai 与 -a），意思是排列。", "皮": "pí（第二声）与 pá（第二声）韵母不同（-i 与 -a），意思是皮。", "啪": "pā（第一声）与 pá（第二声）声调不同，多用于拟声，表示拍击声。"}, "sentence_index": null, "correct_answer": "爬"}, "level_3": {"options": [{"text": "爬", "is_correct": true, "explanation": "爬：手脚并用移动，是婴儿最先学会的移动方式，与“刚学会”搭配，正确。"}, {"text": "躺", "is_correct": false, "explanation": "语义：躺是身体平卧，不是需要学习才会的移动技能。"}, {"text": "驾", "is_correct": false, "explanation": "搭配：“驾”的对象是车、马等，不能用于婴儿。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”需要坐骑，指人跨坐在车或动物上，不指婴儿的移动。"}], "explanations": {"爬": "爬：手脚并用移动，是婴儿最先学会的移动方式，与“刚学会”搭配，正确。", "躺": "语义：躺是身体平卧，不是需要学习才会的移动技能。", "驾": "搭配：“驾”的对象是车、马等，不能用于婴儿。", "骑": "搭配：“骑”需要坐骑，指人跨坐在车或动物上，不指婴儿的移动。"}, "sentence_index": 6, "correct_answer": "爬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈爬了一个西瓜。", "explanation": "这里应该用〈切〉。爬是手脚并用的移动，不能用于切西瓜。"}, {"text": "我爬了一本书。", "explanation": "这里应该用〈买〉。爬不能用于买书，“买一本书”才是正确说法。"}, {"text": "请你爬好雨伞，别忘了带。", "explanation": "这里应该用〈拿〉。爬不能用于拿雨伞，“拿好雨伞”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae431f26-58d7-4585-a1aa-639adff2d6ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
