INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93647, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民主", "is_correct": true, "explanation": "民主与法西斯相反：前者是人民当家作主，后者是不让人说话。"}, {"text": "树木", "is_correct": false, "explanation": "树木是植物，与法西斯没有反义关系。"}, {"text": "书本", "is_correct": false, "explanation": "书本与法西斯的含义没有相对关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流是自然事物，与法西斯没有反义关系。"}], "correct_answer": "民主", "explanations": {"民主": "民主与法西斯相反：前者是人民当家作主，后者是不让人说话。", "树木": "树木是植物，与法西斯没有反义关系。", "书本": "书本与法西斯的含义没有相对关系。", "河流": "河流是自然事物，与法西斯没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
