INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93647, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法西斯是让国家由一个人说了算，不让别人说话的坏办法。", "primary_collocate": null, "pronunciation": "fǎ xī sī", "ipa": "fa˨˩ ɕi˥ sɨ˥", "syllable_count": 3, "sentences": [{"text": "法西斯就是一个人说了算的坏办法。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在法西斯的国家，老百姓不能说真话。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷小时候，那个国家就是法西斯，老百姓不敢说话。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们都恨法西斯，因为它不让人说话。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：什么是法西斯？", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法西斯让国家变得很可怕。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要记住法西斯带来的痛苦。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上讲了法西斯的故事。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法西斯不好，因为只有一个人做决定。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们读了书，知道了法西斯是坏办法。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "法西斯主义", "label": "复合"}, {"form": "法西斯分子", "label": "复合"}], "register": "通用", "sense_fingerprint": "一个人说了算、不让别人说话的坏办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b69c20c8-55e0-48cc-a4ad-ae6e68dd460f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93647, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法西斯", "is_correct": true, "explanation": "法西斯指由一个人说了算、不让别人说话的坏办法，符合句意。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海是自然事物，不是一个人说了算的坏办法。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能是“一个人说了算”的办法。"}, {"text": "饺子", "is_correct": false, "explanation": "搭配：“……的办法”需要表示做法或制度的词，“饺子”是食物，不能充当办法。"}], "explanations": {"法西斯": "法西斯指由一个人说了算、不让别人说话的坏办法，符合句意。", "大海": "语义：大海是自然事物，不是一个人说了算的坏办法。", "天气": "语义：天气是自然现象，不能是“一个人说了算”的办法。", "饺子": "搭配：“……的办法”需要表示做法或制度的词，“饺子”是食物，不能充当办法。"}, "sentence_index": 0, "correct_answer": "法西斯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天喝法西斯。", "explanation": "这里应该用〈咖啡〉。法西斯是一种坏办法，不是饮料，不能用“喝”。"}, {"text": "这个国家的法西斯很长。", "explanation": "这里应该用〈河流〉。法西斯是抽象的坏办法，没有长短，不能用“很长”来形容。"}, {"text": "我在花园里种了法西斯。", "explanation": "这里应该用〈花〉。法西斯是一种坏办法，不是植物，不能“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93647, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法西斯", "is_correct": true, "explanation": "法西斯带来痛苦，指那种不让人说话的坏办法，符合句意。"}, {"text": "星期三", "is_correct": false, "explanation": "语义：星期三是时间名词，不能带来痛苦。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是饮食，不会带来需要记住的痛苦。"}, {"text": "凳子", "is_correct": false, "explanation": "搭配：“带来的痛苦”多指社会或历史事件，“凳子”是普通家具，不搭配。"}], "explanations": {"法西斯": "法西斯带来痛苦，指那种不让人说话的坏办法，符合句意。", "星期三": "语义：星期三是时间名词，不能带来痛苦。", "午饭": "语义：午饭是饮食，不会带来需要记住的痛苦。", "凳子": "搭配：“带来的痛苦”多指社会或历史事件，“凳子”是普通家具，不搭配。"}, "sentence_index": 6, "correct_answer": "法西斯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天骑法西斯去上学。", "explanation": "这里应该用〈自行车〉。法西斯是坏办法，不是交通工具，不能用“骑”。"}, {"text": "他把法西斯切开了。", "explanation": "这里应该用〈蛋糕〉。法西斯是抽象的坏办法，不能用刀切开；能切开的食物要说“蛋糕”之类。"}, {"text": "孩子们唱了法西斯。", "explanation": "这里应该用〈歌曲〉。法西斯不是歌，不能用“唱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93647, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要法西斯赶出去。", "corrected_sentence": "我们要把法西斯赶出去。", "error_description": "错误：“把”字句中“把”不能省略；去掉“把”后，“法西斯”变成“赶”的主语，句意不通。正确说法是“我们要把法西斯赶出去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93647, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书讲了法西斯地坏处。", "corrected_sentence": "这本书讲了法西斯的坏处。", "error_description": "错误：修饰“坏处”时应用“的”，不能用“地”（“地”是状语标记，用于修饰动词）。正确说法是“讲了法西斯的坏处”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93648, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民主", "is_correct": true, "explanation": "民主与法西斯相反：前者是人民当家作主，后者是极端独裁。"}, {"text": "书本", "is_correct": false, "explanation": "书本与法西斯的政治含义没有相对关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流是自然事物，与法西斯没有反义关系。"}, {"text": "树木", "is_correct": false, "explanation": "树木是植物，与政治主张没有反义关系。"}], "correct_answer": "民主", "explanations": {"民主": "民主与法西斯相反：前者是人民当家作主，后者是极端独裁。", "书本": "书本与法西斯的政治含义没有相对关系。", "河流": "河流是自然事物，与法西斯没有反义关系。", "树木": "树木是植物，与政治主张没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
