INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93648, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "主张极端独裁、崇尚暴力的政治主张和政治运动。", "primary_collocate": null, "pronunciation": "fǎ xī sī", "ipa": "fa˨˩ ɕi˥ sɨ˥", "syllable_count": 3, "sentences": [{"text": "法西斯政权在二十世纪三十年代上台。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史课上，老师讲了法西斯是怎么产生的。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法西斯主张独裁，不让人民有自由。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家一起打败了法西斯。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写了法西斯在欧洲的历史。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法西斯崇尚暴力，给世界带来了战争。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究法西斯已经二十年了。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影讲了人们反对法西斯的故事。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，法西斯政权倒台了。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法西斯的思想对人类非常危险。", "target_word": "法西斯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "法西斯主义", "label": "复合"}, {"form": "法西斯分子", "label": "复合"}], "register": "书面", "sense_fingerprint": "极端独裁、崇尚暴力的政治运动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b69c20c8-55e0-48cc-a4ad-ae6e68dd460f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法西斯", "is_correct": true, "explanation": "法西斯是极端独裁的政治运动，其政权可以在某个年代上台，符合句意。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不是政权，不能“上台”。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“上台”指人或政权登上统治舞台，不能用于饼干。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾是废弃物，不能作为政权上台。"}], "explanations": {"法西斯": "法西斯是极端独裁的政治运动，其政权可以在某个年代上台，符合句意。", "春天": "语义：春天是季节，不是政权，不能“上台”。", "饼干": "搭配：“上台”指人或政权登上统治舞台，不能用于饼干。", "垃圾": "语义：垃圾是废弃物，不能作为政权上台。"}, "sentence_index": 0, "correct_answer": "法西斯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把法西斯装进了书包。", "explanation": "这里应该用〈课本〉。法西斯是政治主张和运动，不是物品，不能装进书包。"}, {"text": "这个国家制定了法西斯。", "explanation": "这里应该用〈法律〉。法西斯是一种政治主张，不能像法律那样被“制定”。"}, {"text": "法西斯今天穿了一件红衣服。", "explanation": "这里应该用〈妹妹〉。法西斯是政治主张，不是人，不能“穿衣服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法西斯", "is_correct": true, "explanation": "法西斯是可以被研究的政治现象，符合句意。"}, {"text": "星期三", "is_correct": false, "explanation": "语义：星期三是时间名词，不是可以研究二十年的对象。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是饮食，不构成需要长期研究的对象。"}, {"text": "一个", "is_correct": false, "explanation": "语法：量词“一个”不能作“研究”的宾语，填入此处不成句。"}], "explanations": {"法西斯": "法西斯是可以被研究的政治现象，符合句意。", "星期三": "语义：星期三是时间名词，不是可以研究二十年的对象。", "午饭": "语义：午饭是饮食，不构成需要长期研究的对象。", "一个": "语法：量词“一个”不能作“研究”的宾语，填入此处不成句。"}, "sentence_index": 6, "correct_answer": "法西斯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天骑法西斯上班。", "explanation": "这里应该用〈自行车〉。法西斯是政治主张，不是交通工具，不能用“骑”。"}, {"text": "他在厨房里做法西斯。", "explanation": "这里应该用〈饭〉。法西斯是政治主张，不是食物，不能在厨房里“做”。"}, {"text": "他的法西斯很好吃。", "explanation": "这里应该用〈面包〉。法西斯是政治主张，不是食物，不能说“很好吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他曾经反对着法西斯。", "corrected_sentence": "他曾经反对过法西斯。", "error_description": "体标错误：“曾经”表示过去有过的经历，应用“过”，不能用“着”（“着”表示持续状态，与“曾经”相冲突）。正确说法是“反对过法西斯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人们终于推翻了一座法西斯政权。", "corrected_sentence": "人们终于推翻了一个法西斯政权。", "error_description": "量词错误：“座”用于山、楼等大型固定物，“政权”应用量词“个”。正确说法是“一个法西斯政权”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
