INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93649, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "狼是长得像大狗的野兽，生活在山里，很凶。", "primary_collocate": null, "pronunciation": "láng", "ipa": "laŋ˧˥", "syllable_count": 1, "sentences": [{"text": "山里有一只狼，样子像大狗。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，我听见山上有狼在叫。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼很凶，村里人都怕它。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狼看着羊，慢慢走过来。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狼比狗大，也比狗凶。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼住在山里，晚上出来找吃的。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山路上遇到了一只狼。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼的眼睛在黑夜里发着光。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，看见狼不要跑。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里的狼看起来像一只大狗。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只狼", "label": "量词"}, {"form": "一匹狼", "label": "量词"}, {"form": "野狼", "label": "复合"}, {"form": "狼群", "label": "复合"}], "register": "通用", "sense_fingerprint": "像大狗的凶野兽，住在山里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b69c20c8-55e0-48cc-a4ad-ae6e68dd460f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93649, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "浪", "is_correct": false, "explanation": "声调：làng（第四声）与 láng（第二声）声调不同，意思是波浪。"}, {"text": "狼", "is_correct": true, "explanation": "正确：狼（láng）是本词，指像大狗的野兽。"}, {"text": "蓝", "is_correct": false, "explanation": "韵母：lán 与 láng 韵母不同（an 与 ang），意思是蓝色。"}, {"text": "朗", "is_correct": false, "explanation": "声调：lǎng（第三声）与 láng（第二声）声调不同，意思是明朗。"}, {"text": "航", "is_correct": false, "explanation": "声母：háng 与 láng 声母不同（h 与 l），意思是航行、航空。"}], "explanations": {"浪": "声调：làng（第四声）与 láng（第二声）声调不同，意思是波浪。", "狼": "正确：狼（láng）是本词，指像大狗的野兽。", "蓝": "韵母：lán 与 láng 韵母不同（an 与 ang），意思是蓝色。", "朗": "声调：lǎng（第三声）与 láng（第二声）声调不同，意思是明朗。", "航": "声母：háng 与 láng 声母不同（h 与 l），意思是航行、航空。"}, "sentence_index": null, "correct_answer": "狼"}, "level_3": {"options": [{"text": "蝴蝶", "is_correct": false, "explanation": "语义：蝴蝶不像大狗，“样子像大狗”与蝴蝶不合。"}, {"text": "狼", "is_correct": true, "explanation": "正确：山里的野兽“狼”与“样子像大狗”相合，量词“只”也对。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象的样子不像大狗，“样子像大狗”与大象不合。"}, {"text": "鱼", "is_correct": false, "explanation": "搭配：鱼一般用“条”计量，“山里有一只鱼”不自然，而且鱼与“样子像大狗”不合。"}], "explanations": {"蝴蝶": "语义：蝴蝶不像大狗，“样子像大狗”与蝴蝶不合。", "狼": "正确：山里的野兽“狼”与“样子像大狗”相合，量词“只”也对。", "大象": "语义：大象的样子不像大狗，“样子像大狗”与大象不合。", "鱼": "搭配：鱼一般用“条”计量，“山里有一只鱼”不自然，而且鱼与“样子像大狗”不合。"}, "sentence_index": 0, "correct_answer": "狼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的狼每天晚上都会在床边叫我起床。", "explanation": "这里应该用〈猫〉。狼是野生动物，不会在床边叫人起床；这是家猫才会做的事。"}, {"text": "我看见一本狼，它在山路上跑。", "explanation": "这里应该用〈只〉或〈匹〉。〈本〉用于书籍，不能用来数狼。"}, {"text": "山上跑来一座狼，吓坏了路人。", "explanation": "这里应该用〈只〉或〈匹〉。〈座〉用于山、房屋等大型固定物，不用来数动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93649, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "忙", "is_correct": false, "explanation": "声母：máng 与 láng 声母不同（m 与 l），意思是忙碌。"}, {"text": "狼", "is_correct": true, "explanation": "正确：狼（láng）是本词，指像大狗的野兽。"}, {"text": "糖", "is_correct": false, "explanation": "声母：táng 与 láng 声母不同（t 与 l），意思是糖果。"}, {"text": "龙", "is_correct": false, "explanation": "韵母：lóng 与 láng 韵母不同（ong 与 ang），意思是龙。"}], "explanations": {"忙": "声母：máng 与 láng 声母不同（m 与 l），意思是忙碌。", "狼": "正确：狼（láng）是本词，指像大狗的野兽。", "糖": "声母：táng 与 láng 声母不同（t 与 l），意思是糖果。", "龙": "韵母：lóng 与 láng 韵母不同（ong 与 ang），意思是龙。"}, "sentence_index": null, "correct_answer": "狼"}, "level_3": {"options": [{"text": "海豚", "is_correct": false, "explanation": "语义：海豚生活在海里，山路上遇到海豚不合理。"}, {"text": "狼", "is_correct": true, "explanation": "正确：狼是山里常见的野兽，山路上遇到它合理。"}, {"text": "企鹅", "is_correct": false, "explanation": "语义：企鹅生活在南极一带，不会出现在山路上。"}, {"text": "手机", "is_correct": false, "explanation": "量词：手机用“部”，不说“一只手机”，句子不成立。"}], "explanations": {"海豚": "语义：海豚生活在海里，山路上遇到海豚不合理。", "狼": "正确：狼是山里常见的野兽，山路上遇到它合理。", "企鹅": "语义：企鹅生活在南极一带，不会出现在山路上。", "手机": "量词：手机用“部”，不说“一只手机”，句子不成立。"}, "sentence_index": 6, "correct_answer": "狼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "狼生活在南极，喜欢在冰上滑行。", "explanation": "这里应该用〈企鹅〉。狼生活在山林和草原，不生活在南极；在冰上滑行的是企鹅。"}, {"text": "村口那只狼总是对着路人摇尾巴。", "explanation": "这里应该用〈狗〉。摇尾巴讨好路人是狗的习性，狼是野生动物，不会这样做。"}, {"text": "动物园的狼很爱吃香蕉。", "explanation": "这里应该用〈猴子〉。狼吃肉，不爱吃香蕉这类水果，这里应换成猴子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93649, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里我在院子外看见一个狼。", "corrected_sentence": "夜里我在院子外看见一只狼。", "error_description": "“狼”是动物，量词应说“只”或“匹”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93649, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在山上看见两狼。", "corrected_sentence": "我在山上看见两只狼。", "error_description": "数词“两”后面要加量词，应说“两只狼”，不能直接说“两狼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
