INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93650, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种凶猛的野生动物，外形像狗，群居，吃肉。", "primary_collocate": null, "pronunciation": "láng", "ipa": "laŋ˧˥", "syllable_count": 1, "sentences": [{"text": "狼是一种野生动物，喜欢吃肉。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼喜欢成群生活，一起去找肉吃。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼外形像狗，可是比狗凶猛得多。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，狼饿了就会去找羊吃。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物书上说，狼是群居的动物。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼吃肉，不吃草。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草原上的狼一起追着一只鹿。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们很少在城里看到野生的狼。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狼跑得很快，能追上兔子。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护野生动物，也要保护狼。", "target_word": "狼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只狼", "label": "量词"}, {"form": "一匹狼", "label": "量词"}, {"form": "野狼", "label": "复合"}, {"form": "狼群", "label": "复合"}], "register": "通用", "sense_fingerprint": "外形像狗、群居吃肉的凶猛野生动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b69c20c8-55e0-48cc-a4ad-ae6e68dd460f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93650, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "浪", "is_correct": false, "explanation": "声调：làng（第四声）与 láng（第二声）声调不同，意思是波浪。"}, {"text": "狼", "is_correct": true, "explanation": "正确：狼（láng）是本词，指外形像狗、群居吃肉的野生动物。"}, {"text": "蓝", "is_correct": false, "explanation": "韵母：lán 与 láng 韵母不同（an 与 ang），意思是蓝色。"}, {"text": "朗", "is_correct": false, "explanation": "声调：lǎng（第三声）与 láng（第二声）声调不同，意思是明朗。"}, {"text": "航", "is_correct": false, "explanation": "声母：háng 与 láng 声母不同（h 与 l），意思是航行、航空。"}], "explanations": {"浪": "声调：làng（第四声）与 láng（第二声）声调不同，意思是波浪。", "狼": "正确：狼（láng）是本词，指外形像狗、群居吃肉的野生动物。", "蓝": "韵母：lán 与 láng 韵母不同（an 与 ang），意思是蓝色。", "朗": "声调：lǎng（第三声）与 láng（第二声）声调不同，意思是明朗。", "航": "声母：háng 与 láng 声母不同（h 与 l），意思是航行、航空。"}, "sentence_index": null, "correct_answer": "狼"}, "level_3": {"options": [{"text": "羊", "is_correct": false, "explanation": "语义：羊吃草，不吃肉，与“喜欢吃肉”不合。"}, {"text": "狼", "is_correct": true, "explanation": "正确：狼是群居的食肉野生动物，与“喜欢吃肉”相合。"}, {"text": "大米", "is_correct": false, "explanation": "搭配：“大米”是食物，不是动物，与“是一种野生动物”的说法不搭。"}, {"text": "兔子", "is_correct": false, "explanation": "语义：兔子吃草，“喜欢吃肉”与兔子不合。"}], "explanations": {"羊": "语义：羊吃草，不吃肉，与“喜欢吃肉”不合。", "狼": "正确：狼是群居的食肉野生动物，与“喜欢吃肉”相合。", "大米": "搭配：“大米”是食物，不是动物，与“是一种野生动物”的说法不搭。", "兔子": "语义：兔子吃草，“喜欢吃肉”与兔子不合。"}, "sentence_index": 0, "correct_answer": "狼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家养的狼很听话，每天在门口等我回家。", "explanation": "这里应该用〈狗〉。狼是野生动物，不会像家养的狗那样在门口等人。"}, {"text": "我在森林里看见一台狼，它跑得很快。", "explanation": "这里应该用〈只〉或〈匹〉。〈台〉用于机器、设备，不能用来数狼。"}, {"text": "草原上住着一座狼，每天夜里嚎叫。", "explanation": "这里应该用〈只〉或〈匹〉。〈座〉用于山、房屋等大型固定物，不用来数动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93650, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "忙", "is_correct": false, "explanation": "声母：máng 与 láng 声母不同（m 与 l），意思是忙碌。"}, {"text": "狼", "is_correct": true, "explanation": "正确：狼（láng）是本词，指外形像狗、群居吃肉的野生动物。"}, {"text": "糖", "is_correct": false, "explanation": "声母：táng 与 láng 声母不同（t 与 l），意思是糖果。"}, {"text": "龙", "is_correct": false, "explanation": "韵母：lóng 与 láng 韵母不同（ong 与 ang），意思是龙。"}], "explanations": {"忙": "声母：máng 与 láng 声母不同（m 与 l），意思是忙碌。", "狼": "正确：狼（láng）是本词，指外形像狗、群居吃肉的野生动物。", "糖": "声母：táng 与 láng 声母不同（t 与 l），意思是糖果。", "龙": "韵母：lóng 与 láng 韵母不同（ong 与 ang），意思是龙。"}, "sentence_index": null, "correct_answer": "狼"}, "level_3": {"options": [{"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠不会成群追赶一只鹿，句意不合。"}, {"text": "狼", "is_correct": true, "explanation": "正确：狼群会一起追捕猎物，“一起追着一只鹿”合理。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“树”不能主动去“追”，“一起追着”要求能动的主语。"}, {"text": "小鸡", "is_correct": false, "explanation": "语义：小鸡体型小，不能一起追赶一只鹿。"}], "explanations": {"老鼠": "语义：老鼠不会成群追赶一只鹿，句意不合。", "狼": "正确：狼群会一起追捕猎物，“一起追着一只鹿”合理。", "树": "搭配：“树”不能主动去“追”，“一起追着”要求能动的主语。", "小鸡": "语义：小鸡体型小，不能一起追赶一只鹿。"}, "sentence_index": 6, "correct_answer": "狼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "狼喜欢吃竹子，很少吃肉。", "explanation": "这里应该用〈熊猫〉。狼吃肉，不吃竹子；喜欢吃竹子、很少吃肉的是熊猫。"}, {"text": "狼成群生活，一起去花上采蜜。", "explanation": "这里应该用〈蜜蜂〉。狼不采蜜，“采蜜”是蜜蜂的习性。"}, {"text": "狼生活在南极，喜欢在冰上滑行。", "explanation": "这里应该用〈企鹅〉。狼生活在山林和草原，不生活在南极。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草原上来了一个狼，一直在看着我。", "corrected_sentence": "草原上来了一只狼，一直在看着我。", "error_description": "数量词用错：数动物“狼”应说“一只狼”，不能说“一个狼”。“个”用于一般人或事物，“只”才是动物的常用量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "草原上有五个狼，正在一起追兔子。", "corrected_sentence": "草原上有五只狼，正在一起追兔子。", "error_description": "量词用错：数动物“狼”应该用“只”或“匹”，不能用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e5ed31d-97f2-4ce0-b44d-6bc715d793a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
