INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93651, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海底是大海最下面的地方。", "primary_collocate": null, "pronunciation": "hǎi dǐ", "ipa": "xaɪ²¹⁴ ti²¹⁴", "syllable_count": 2, "sentences": [{"text": "海底有很多漂亮的鱼。", "target_word": "海底", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想潜到海底看一看。", "target_word": "海底", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海底很黑，也很安静。", "target_word": "海底", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那艘船沉到了海底。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海底有一座古老的城市。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在电影里看到了海底的鱼群。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "潜水员在海底待了二十分钟。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海底的水压很大，人不能直接下去。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些贝壳是从海底捞上来的。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在海底发现了一个很大的洞。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "海底世界", "label": "复合"}], "register": "中性", "sense_fingerprint": "大海最下面的地方，鱼和船沉下去的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06f273b2-8ada-4e9a-bf00-a5ca09e322b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93651, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "海底", "is_correct": true, "explanation": "海底：大海最下面的地方，即本词的意思。"}, {"text": "海堤", "is_correct": false, "explanation": "海堤（hǎidī）与 hǎidǐ 只有声调不同（第一声与第三声），意思是沿海挡浪的堤坝。"}, {"text": "海里", "is_correct": false, "explanation": "海里（hǎilǐ）与 hǎidǐ 只有声母不同（l 与 d），意思是航海距离单位。"}, {"text": "海地", "is_correct": false, "explanation": "海地（hǎidì）是国名，与 hǎidǐ 只有声调不同（第四声与第三声）。"}, {"text": "海米", "is_correct": false, "explanation": "海米（hǎimǐ）是虾米，与 hǎidǐ 只有声母不同（m 与 d）。"}], "explanations": {"海底": "海底：大海最下面的地方，即本词的意思。", "海堤": "海堤（hǎidī）与 hǎidǐ 只有声调不同（第一声与第三声），意思是沿海挡浪的堤坝。", "海里": "海里（hǎilǐ）与 hǎidǐ 只有声母不同（l 与 d），意思是航海距离单位。", "海地": "海地（hǎidì）是国名，与 hǎidǐ 只有声调不同（第四声与第三声）。", "海米": "海米（hǎimǐ）是虾米，与 hǎidǐ 只有声母不同（m 与 d）。"}, "sentence_index": null, "correct_answer": "海底"}, "level_3": {"options": [{"text": "海底", "is_correct": true, "explanation": "海底：大海最下面的地方，鱼生活在那里，句意通顺。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空在高处，没有水，不会有鱼。"}, {"text": "月球", "is_correct": false, "explanation": "语义：月球上没有水，不可能有漂亮的鱼。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“有很多漂亮的鱼”的处所应是水域，书包不能与之搭配。"}], "explanations": {"海底": "海底：大海最下面的地方，鱼生活在那里，句意通顺。", "天空": "语义：天空在高处，没有水，不会有鱼。", "月球": "语义：月球上没有水，不可能有漂亮的鱼。", "书包": "搭配：“有很多漂亮的鱼”的处所应是水域，书包不能与之搭配。"}, "sentence_index": 0, "correct_answer": "海底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "池塘的海底有很多泥。", "explanation": "这里应该用〈水底〉。海底专指大海的底部，池塘的底部要用水底。"}, {"text": "那艘船漂在海底。", "explanation": "这里应该用〈海面〉。船是浮在海面上的，海底在水下，不能说船漂在海底。"}, {"text": "孩子们在海底上玩沙子。", "explanation": "这里应该用〈海滩〉。海底在水下，人不能站在上面玩沙，玩沙要去海滩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海底", "is_correct": true, "explanation": "海底：大海最下面的地方，潜水员可以在那里待，句意通顺。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶装不下人，潜水员不可能在里面待二十分钟。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能供人长时间停留，与潜水员的活动不符。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“待”的处所要能容纳人，“眼睛”不能作为潜水员停留的地方。"}], "explanations": {"海底": "海底：大海最下面的地方，潜水员可以在那里待，句意通顺。", "花瓶": "语义：花瓶装不下人，潜水员不可能在里面待二十分钟。", "冰箱": "语义：冰箱不能供人长时间停留，与潜水员的活动不符。", "眼睛": "搭配：“待”的处所要能容纳人，“眼睛”不能作为潜水员停留的地方。"}, "sentence_index": 6, "correct_answer": "海底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只海底很深。", "explanation": "这里应该用〈片〉。“只”用于动物，海底是一片海域的底部，不能用“只”来数。"}, {"text": "这条海底很深。", "explanation": "这里应该用〈片〉。“条”用于细长的东西，海底不能用“条”来数。"}, {"text": "这头海底很深。", "explanation": "这里应该用〈片〉。“头”用于牛、猪等大型牲畜，海底不能用“头”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她潜海底找到了一个贝壳。", "corrected_sentence": "她潜到海底找到了一个贝壳。", "error_description": "补语缺失：“潜”后面要用“到”引出地点，应说“潜到海底”，不能直接说“潜海底”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93651, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他海底拍到了一条大鱼。", "corrected_sentence": "他在海底拍到了一条大鱼。", "error_description": "介词缺失：表示地点要用“在”引出，应说“在海底拍到”，漏掉“在”就不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
