INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93652, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海洋底部。", "primary_collocate": null, "pronunciation": "hǎi dǐ", "ipa": "xaɪ²¹⁴ ti²¹⁴", "syllable_count": 2, "sentences": [{"text": "科学家正在研究海底的石头。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海底的温度比海面低很多。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们在海底修了一条隧道。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海底有很深的山谷。", "target_word": "海底", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条电缆铺在海底，长一千公里。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震发生在海底，所以没有人受伤。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "后来人们在海底找到了飞机。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海底的泥土里有很多小虫子。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用机器人拍下了海底的样子。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海底的火山一直在慢慢地喷出热水。", "target_word": "海底", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "海底世界", "label": "复合"}], "register": "中性", "sense_fingerprint": "海洋底部的地形、地质与设施所在处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06f273b2-8ada-4e9a-bf00-a5ca09e322b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93652, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "海底", "is_correct": true, "explanation": "海底：海洋的底部，即本词的意思。"}, {"text": "海堤", "is_correct": false, "explanation": "海堤（hǎidī）与 hǎidǐ 只有声调不同（第一声与第三声），意思是沿海挡浪的堤坝。"}, {"text": "海里", "is_correct": false, "explanation": "海里（hǎilǐ）与 hǎidǐ 只有声母不同（l 与 d），意思是航海距离单位。"}, {"text": "海地", "is_correct": false, "explanation": "海地（hǎidì）是国名，与 hǎidǐ 只有声调不同（第四声与第三声）。"}, {"text": "海米", "is_correct": false, "explanation": "海米（hǎimǐ）是虾米，与 hǎidǐ 只有声母不同（m 与 d）。"}], "explanations": {"海底": "海底：海洋的底部，即本词的意思。", "海堤": "海堤（hǎidī）与 hǎidǐ 只有声调不同（第一声与第三声），意思是沿海挡浪的堤坝。", "海里": "海里（hǎilǐ）与 hǎidǐ 只有声母不同（l 与 d），意思是航海距离单位。", "海地": "海地（hǎidì）是国名，与 hǎidǐ 只有声调不同（第四声与第三声）。", "海米": "海米（hǎimǐ）是虾米，与 hǎidǐ 只有声母不同（m 与 d）。"}, "sentence_index": null, "correct_answer": "海底"}, "level_3": {"options": [{"text": "海底", "is_correct": true, "explanation": "海底：海洋的底部，科学家研究的石头就在那里，句意通顺。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是人造家具，不会产出天然石头，无法研究。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“研究……的石头”要求岩石有天然来源，书包不能与之搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱里没有天然岩石，科学家不会去研究它的石头。"}], "explanations": {"海底": "海底：海洋的底部，科学家研究的石头就在那里，句意通顺。", "课桌": "语义：课桌是人造家具，不会产出天然石头，无法研究。", "书包": "搭配：“研究……的石头”要求岩石有天然来源，书包不能与之搭配。", "冰箱": "语义：冰箱里没有天然岩石，科学家不会去研究它的石头。"}, "sentence_index": 0, "correct_answer": "海底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个湖的海底很浅。", "explanation": "这里应该用〈湖底〉。海底专指大海的底部，湖泊的底部要用湖底。"}, {"text": "我们在海底放风筝。", "explanation": "这里应该用〈海边〉。海底在水下，人不能在那里放风筝，放风筝要去海边。"}, {"text": "他们在海底搭帐篷。", "explanation": "这里应该用〈草地〉。海底在水下，不能搭帐篷，搭帐篷要用草地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海底", "is_correct": true, "explanation": "海底：海洋的底部，飞机可以沉在那里被找到，句意通顺。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包装不下飞机，不能在里面找到飞机。"}, {"text": "毛巾", "is_correct": false, "explanation": "语义：毛巾是布料，不能藏着一架飞机。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“在……找到”要求能容纳飞机的大场所，“眼睛”不能作为找到飞机的地点。"}], "explanations": {"海底": "海底：海洋的底部，飞机可以沉在那里被找到，句意通顺。", "钱包": "语义：钱包装不下飞机，不能在里面找到飞机。", "毛巾": "语义：毛巾是布料，不能藏着一架飞机。", "眼睛": "搭配：“在……找到”要求能容纳飞机的大场所，“眼睛”不能作为找到飞机的地点。"}, "sentence_index": 6, "correct_answer": "海底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那只海底有很多石头。", "explanation": "这里应该用〈片〉。“只”用于动物，海底不能用“只”来数。"}, {"text": "那棵海底有很多石头。", "explanation": "这里应该用〈片〉。“棵”用于树木和植物，海底不能用“棵”来数。"}, {"text": "那把海底有很多石头。", "explanation": "这里应该用〈片〉。“把”用于有柄的东西，海底不能用“把”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机器人潜海底拍了照片。", "corrected_sentence": "机器人潜到海底拍了照片。", "error_description": "补语缺失：“潜”后面要用“到”引出地点，应说“潜到海底”，不能说“潜海底”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员海底安装了一台仪器。", "corrected_sentence": "研究人员在海底安装了一台仪器。", "error_description": "介词缺失：表示地点要用“在”引出，应说“在海底安装”，漏掉“在”就不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '013c1274-3ca6-4790-a7eb-ac9dc3ba7b75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
