INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93658, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旧时民间的秘密结社组织。", "primary_collocate": null, "pronunciation": "huì dǎng", "ipa": "xweɪ˥˩ tɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "清朝时，民间有很多会党。", "target_word": "会党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会党在旧社会里很有名。", "target_word": "会党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天地会是清朝有名的会党。", "target_word": "会党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧时的会党常常反对官府。", "target_word": "会党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时加入过会党。", "target_word": "会党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候，会党的人用暗号互相认识。", "target_word": "会党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会党是旧时民间的秘密组织。", "target_word": "会党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写了清朝会党的故事。", "target_word": "会党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会党的首领带人离开了城市。", "target_word": "会党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人给我们讲了会党的历史。", "target_word": "会党", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个会党", "label": "量词"}, {"form": "会党首领", "label": "复合"}], "register": "书面", "sense_fingerprint": "会党·名词·旧时民间的秘密结社组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '168ad27f-59af-419a-aeff-3d9250db54ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会党", "is_correct": true, "explanation": "会党：指旧时民间的秘密结社，与“清朝时”的背景相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：清朝时还没有手机，与时代背景矛盾。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：清朝时还没有飞机，与时代背景矛盾。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是近代以后才有的东西，清朝时民间没有，与时代背景矛盾。"}], "explanations": {"会党": "会党：指旧时民间的秘密结社，与“清朝时”的背景相符。", "手机": "语义：清朝时还没有手机，与时代背景矛盾。", "飞机": "语义：清朝时还没有飞机，与时代背景矛盾。", "电脑": "语义：电脑是近代以后才有的东西，清朝时民间没有，与时代背景矛盾。"}, "sentence_index": 0, "correct_answer": "会党"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个会党每个月都公开召开会议。", "explanation": "这里应该用〈政党〉。会党是秘密结社，不会公开召开会议。"}, {"text": "这个会党是几个国家为了和平而组成的。", "explanation": "这里应该用〈联盟〉。会党是秘密结社，不是国家之间为和平而组成的联合组织。"}, {"text": "这个会党每周组织学者讨论学问。", "explanation": "这里应该用〈学会〉。会党是秘密结社，不是学术团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会党", "is_correct": true, "explanation": "会党：指旧时民间的秘密组织，与句中“秘密组织”的定义相符。"}, {"text": "政府", "is_correct": false, "explanation": "语义：政府是官方机构，不是民间的秘密组织。"}, {"text": "学府", "is_correct": false, "explanation": "语义：学府指高等学校，是公开的教育机构，不是民间的秘密组织。"}, {"text": "商会", "is_correct": false, "explanation": "语义：商会是公开的商人团体，与“秘密组织”矛盾。"}], "explanations": {"会党": "会党：指旧时民间的秘密组织，与句中“秘密组织”的定义相符。", "政府": "语义：政府是官方机构，不是民间的秘密组织。", "学府": "语义：学府指高等学校，是公开的教育机构，不是民间的秘密组织。", "商会": "语义：商会是公开的商人团体，与“秘密组织”矛盾。"}, "sentence_index": 6, "correct_answer": "会党"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他年轻时加入过一座会党。", "explanation": "这里应该用〈个〉。“座”用于建筑、山等大型物体，会党不能用“座”计量。"}, {"text": "民间曾有一条会党。", "explanation": "这里应该用〈个〉。“条”用于细长的物体，会党不能用“条”计量。"}, {"text": "他年轻时加入过一位会党。", "explanation": "这里应该用〈个〉。“位”用于称呼人，会党是团体，不能用“位”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "清末的时候，这一带出现过一只会党。", "corrected_sentence": "清末的时候，这一带出现过一个会党。", "error_description": "量词错误：会党应用量词“个”计量；“只”多用于动物，应为“一个会党”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书写了清朝一张会党的故事。", "corrected_sentence": "这本书写了清朝一个会党的故事。", "error_description": "量词错误：“张”用于平面的东西，会党应用“个”计量，应为“一个会党”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67af2435-450e-453b-ac42-e4d8dbca5467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
