INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93659, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "火星是天上一颗红红的星球。", "primary_collocate": null, "pronunciation": "huǒ xīng", "ipa": "xuɔ˨˩˦ ɕiŋ˥˥", "syllable_count": 2, "sentences": [{"text": "火星是一颗红色的星球。", "target_word": "火星", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "晚上我在天上看到了红红的火星。", "target_word": "火星", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火星看起来红红的，很漂亮。", "target_word": "火星", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明想坐飞船去火星玩。", "target_word": "火星", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火星离我们很远。", "target_word": "火星", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师给我们看了一张火星的照片。", "target_word": "火星", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最喜欢的星星是火星。", "target_word": "火星", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为什么火星是红色的？", "target_word": "火星", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟在纸上画了一颗红色的火星。", "target_word": "火星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上天很黑，我们找到了火星。", "target_word": "火星", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "天上红色的星球", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781e042f-01c8-4179-94a7-75f6a8a36a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93659, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "火星", "is_correct": true, "explanation": "火星是太阳系中一颗红色的行星，符合句中的定义。"}, {"text": "地球", "is_correct": false, "explanation": "语义：地球是蓝色的，与“红色”矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是星球，与“星球”矛盾。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是卫星，不是“红色的星球”。"}], "explanations": {"火星": "火星是太阳系中一颗红色的行星，符合句中的定义。", "地球": "语义：地球是蓝色的，与“红色”矛盾。", "石头": "语义：石头不是星球，与“星球”矛盾。", "月亮": "语义：月亮是卫星，不是“红色的星球”。"}, "sentence_index": 0, "correct_answer": "火星"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳系里有八颗火星。", "explanation": "这里应该用〈行星〉。火星是八大行星中一颗的专有名称，不能数“八颗火星”；泛指八大行星要用〈行星〉。"}, {"text": "夜里天上有一朵火星，闪得很亮。", "explanation": "这里应该用〈颗〉。火星是星球，量词用“颗”；“朵”多用于花朵、云朵，不能用于天体。"}, {"text": "我在天上看到了一只火星。", "explanation": "这里应该用〈颗〉。火星是星球，量词用“颗”，“只”多用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93659, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火星", "is_correct": true, "explanation": "火星是句中所指的天体，符合“星星”的所指。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“星星”指天体，苹果不是天体，句子说不通。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不是天体，与“星星”的所指矛盾。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“最喜欢的星星是饼干”不成立，“星星”不与食物搭配。"}], "explanations": {"火星": "火星是句中所指的天体，符合“星星”的所指。", "苹果": "语义：“星星”指天体，苹果不是天体，句子说不通。", "书": "语义：书不是天体，与“星星”的所指矛盾。", "饼干": "搭配：“最喜欢的星星是饼干”不成立，“星星”不与食物搭配。"}, "sentence_index": 6, "correct_answer": "火星"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在天上看到了一本火星。", "explanation": "这里应该用〈颗〉。火星是星球，量词用“颗”；“本”用于书本，不能用于天体。"}, {"text": "我们在天上看到了一条火星。", "explanation": "这里应该用〈颗〉。火星是星球，量词用“颗”，“条”用于细长的东西。"}, {"text": "傍晚天边挂着一朵火星，很亮。", "explanation": "这里应该用〈颗〉。火星是星球，量词用“颗”；“朵”多用于花朵、云朵，不能用于天体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93659, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很想去火星的玩。", "corrected_sentence": "我很想去火星玩。", "error_description": "结构助词错误：“去火星玩”中“火星”是去的地方，后面不能加“的”，应说“去火星玩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93659, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一起去火星的看看吧。", "corrected_sentence": "我们一起去火星看看吧。", "error_description": "结构助词错误：“火星”后面不能加“的”，应说“去火星看看吧”。“的”会把“火星”变成修饰语，句子就说不通了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
