INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93660, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "太阳系八大行星之一，表面呈红色。", "primary_collocate": null, "pronunciation": "huǒ xīng", "ipa": "xuɔ˨˩˦ ɕiŋ˥˥", "syllable_count": 2, "sentences": [{"text": "火星是太阳系的八大行星之一。", "target_word": "火星", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火星表面是红色的，因为有很多铁。", "target_word": "火星", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火星比地球小很多。", "target_word": "火星", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科学家正在研究火星上有没有水。", "target_word": "火星", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火星绕着太阳转。", "target_word": "火星", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火星上的天气非常冷。", "target_word": "火星", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "人类还没有去过火星。", "target_word": "火星", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火星离太阳比地球远。", "target_word": "火星", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个机器人已经到火星了。", "target_word": "火星", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火星有两颗很小的月亮。", "target_word": "火星", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "太阳系行星，表面红色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781e042f-01c8-4179-94a7-75f6a8a36a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93660, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "火星", "is_correct": true, "explanation": "火星是太阳系八大行星之一，符合句中的定义。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是恒星，不是行星，不能是“八大行星之一”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是地球的卫星，不是太阳系的行星。"}, {"text": "彗星", "is_correct": false, "explanation": "搭配：“八大行星之一”只能指行星，彗星不属于这一类。"}], "explanations": {"火星": "火星是太阳系八大行星之一，符合句中的定义。", "太阳": "语义：太阳是恒星，不是行星，不能是“八大行星之一”。", "月亮": "语义：月亮是地球的卫星，不是太阳系的行星。", "彗星": "搭配：“八大行星之一”只能指行星，彗星不属于这一类。"}, "sentence_index": 0, "correct_answer": "火星"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜空中有一朵火星，闪得很亮。", "explanation": "这里应该用〈颗〉。火星是星球，量词用“颗”；“朵”多用于花朵、云朵，不能用于天体。"}, {"text": "一根火星绕着太阳转。", "explanation": "这里应该用〈颗〉。火星是星球，量词用“颗”，“根”用于细长的东西。"}, {"text": "科学家在研究一张火星。", "explanation": "这里应该用〈颗〉。火星是行星，量词用“颗”；“张”用于平面的东西，不能用于天体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火星", "is_correct": true, "explanation": "火星是人类尚未亲自到达的天体，句意成立。"}, {"text": "月球", "is_correct": false, "explanation": "语义：人类早已登上月球，与“还没有去过”矛盾。"}, {"text": "北京", "is_correct": false, "explanation": "语义：人类早已去过北京，说“还没有去过北京”句意不成立。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用物品，不是人类可以“去”的地方。"}], "explanations": {"火星": "火星是人类尚未亲自到达的天体，句意成立。", "月球": "语义：人类早已登上月球，与“还没有去过”矛盾。", "北京": "语义：人类早已去过北京，说“还没有去过北京”句意不成立。", "冰箱": "语义：冰箱是家用物品，不是人类可以“去”的地方。"}, "sentence_index": 6, "correct_answer": "火星"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "太阳系一共有八颗火星。", "explanation": "这里应该用〈行星〉。火星是八大行星中一颗的专名，不能数“八颗火星”。"}, {"text": "我在望远镜里看到一只火星。", "explanation": "这里应该用〈颗〉。火星是星球，“只”多用于动物，不能用于天体。"}, {"text": "夜空里挂着一朵火星，很亮。", "explanation": "这里应该用〈颗〉。火星是行星，量词用“颗”；“朵”多用于花朵、云朵，不能用于天体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家火星上找到了一些冰。", "corrected_sentence": "科学家在火星上找到了一些冰。", "error_description": "介词错误：处所状语“火星上”前要用“在”，应说“在火星上找到”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没去了火星。", "corrected_sentence": "我还没去过火星。", "error_description": "体标错误：“没”与“了”不能搭配，表示“还没去过”应用“过”，应说“还没去过火星”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
