INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93662, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "受命秘密刺探情报或进行破坏活动的人。", "primary_collocate": null, "pronunciation": "tè wù", "ipa": "tʰɤ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "警察抓住了一个国外派来的特务。", "target_word": "特务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是一名特务的故事。", "target_word": "特务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他被人怀疑是敌国的特务。", "target_word": "特务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "特务在城里偷偷拍下了地图。", "target_word": "特务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个特务扮成卖报的人，每天站在路口。", "target_word": "特务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时期，城里到处都是特务。", "target_word": "特务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她小时候总以为邻居是特务。", "target_word": "特务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "特务把消息藏在一本旧书里。", "target_word": "特务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人给我们讲过抓特务的故事。", "target_word": "特务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个特务终于被当场抓住了。", "target_word": "特务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个特务", "label": "量词"}, {"form": "一名特务", "label": "量词"}, {"form": "特务机关", "label": "复合"}], "register": "中性", "sense_fingerprint": "受命秘密刺探情报或搞破坏的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14564538-3a40-44fa-a32f-b1e6c7a259d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93662, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特务", "is_correct": true, "explanation": "正确：“特务”指受命秘密刺探情报的人，与“国外派来的”相合。"}, {"text": "盒子", "is_correct": false, "explanation": "语义：盒子是物品，不能由国外派来，句子说的是一个人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头无法被派遣，“国外派来的石头”与句意不符。"}, {"text": "蔬菜", "is_correct": false, "explanation": "搭配：“抓住”的对象多为人或动物，“蔬菜”与“抓住”不搭配。"}], "explanations": {"特务": "正确：“特务”指受命秘密刺探情报的人，与“国外派来的”相合。", "盒子": "语义：盒子是物品，不能由国外派来，句子说的是一个人。", "石头": "语义：石头无法被派遣，“国外派来的石头”与句意不符。", "蔬菜": "搭配：“抓住”的对象多为人或动物，“蔬菜”与“抓住”不搭配。"}, "sentence_index": 0, "correct_answer": "特务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个特务在学校教数学，学生们都很喜欢他。", "explanation": "这里应该用〈老师〉。特务指受命秘密刺探情报的人，不指教书的人。"}, {"text": "我们班的特务是小明，他负责管理教室的灯。", "explanation": "这里应该用〈班长〉。特务指秘密刺探情报的人，不指班里管理事务的人。"}, {"text": "我妈妈是一名特务，她每天在医院照顾病人。", "explanation": "这里应该用〈护士〉。特务指秘密刺探情报的人，不指照顾病人的职业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特务", "is_correct": true, "explanation": "正确：“特务”指人，与“以为邻居是……”相合，符合句中的误会语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能被误认为邻居，句子的对象是人。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，与“邻居”不是同一类事物，句意不通。"}, {"text": "湖水", "is_correct": false, "explanation": "搭配：“邻居是……”后面要接人，“湖水”不能与“邻居”同指。"}], "explanations": {"特务": "正确：“特务”指人，与“以为邻居是……”相合，符合句中的误会语境。", "桌子": "语义：桌子是家具，不能被误认为邻居，句子的对象是人。", "窗户": "语义：窗户是建筑部件，与“邻居”不是同一类事物，句意不通。", "湖水": "搭配：“邻居是……”后面要接人，“湖水”不能与“邻居”同指。"}, "sentence_index": 6, "correct_answer": "特务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的猫很调皮，它是一个特务。", "explanation": "这里应该用〈猫〉。特务指人，不指动物，说猫要直接用“猫”。"}, {"text": "这次的特务是洗碗，大家都很累。", "explanation": "这里应该用〈任务〉。特务是人，不是一项工作任务。"}, {"text": "这个特务昨天考了第一名，老师很高兴。", "explanation": "这里应该用〈学生〉。特务指秘密刺探情报的人，不指参加考试的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街角站着一只特务。", "corrected_sentence": "街角站着一名特务。", "error_description": "错误：“一只特务”。正确：“一名特务”。“只”用于动物，指人的“特务”要用“名”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前见过一只特务。", "corrected_sentence": "我以前见过一个特务。", "error_description": "错误：“一只特务”。正确：“一个特务”。“只”用于动物，指人的“特务”要用“个”或“名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
