INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93663, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "男人家是说男人。", "primary_collocate": null, "pronunciation": "nán rén jia", "ipa": "nan˨˦ ɻən˨˦ tɕia", "syllable_count": 3, "sentences": [{"text": "男人家应该多帮妻子做家务。", "target_word": "男人家", "sentence_source": "generated"}, {"text": "你一个男人家，别老是哭。", "target_word": "男人家", "sentence_source": "generated"}, {"text": "男人家出门在外，要照顾好自己。", "target_word": "男人家", "sentence_source": "generated"}, {"text": "这种重活，男人家做起来更方便。", "target_word": "男人家", "sentence_source": "generated"}, {"text": "男人家说话要算数。", "target_word": "男人家", "sentence_source": "generated"}, {"text": "我们男人家不太会挑衣服。", "target_word": "男人家", "sentence_source": "generated"}, {"text": "家里的事，男人家也该管一管。", "target_word": "男人家", "sentence_source": "generated"}, {"text": "一个男人家，怎么这么小气？", "target_word": "男人家", "sentence_source": "generated"}, {"text": "男人家不爱逛街，他在外面等着。", "target_word": "男人家", "sentence_source": "generated"}, {"text": "她说，男人家都喜欢看球赛。", "target_word": "男人家", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语里泛指男人，常带评价或劝说语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14564538-3a40-44fa-a32f-b1e6c7a259d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93663, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陌生人", "is_correct": false, "explanation": "语义：“陌生人”与“妻子”的亲属关系矛盾，句意不通。"}, {"text": "男人家", "is_correct": true, "explanation": "正确：“男人家”指男人，与“妻子”“做家务”的语境相符。"}, {"text": "公司", "is_correct": false, "explanation": "搭配：“公司”不能作“帮妻子做家务”的施事。"}, {"text": "单身汉", "is_correct": false, "explanation": "语义：“单身汉”没有妻子，与“多帮妻子做家务”矛盾。"}], "explanations": {"陌生人": "语义：“陌生人”与“妻子”的亲属关系矛盾，句意不通。", "男人家": "正确：“男人家”指男人，与“妻子”“做家务”的语境相符。", "公司": "搭配：“公司”不能作“帮妻子做家务”的施事。", "单身汉": "语义：“单身汉”没有妻子，与“多帮妻子做家务”矛盾。"}, "sentence_index": 0, "correct_answer": "男人家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家商店专卖男人家，样子都很好看。", "explanation": "「男人家」指男人，不指衣服。这里应该用〈男装〉。"}, {"text": "她是个男人家，从来不化妆。", "explanation": "“男人家”只指男性，不能用来称呼女性。这里语义不对。"}, {"text": "这次运动会的男人家组决赛很精彩。", "explanation": "「男人家」是口语，不能用作组别名称。这里应该用〈男子组〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93663, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小狗", "is_correct": false, "explanation": "语义：“小狗”是动物，不会“管家里的事”，句意不通。"}, {"text": "外国人", "is_correct": false, "explanation": "语义：“外国人”与“家里的事，也该管一管”的语境不符，句意不通。"}, {"text": "男人家", "is_correct": true, "explanation": "正确：“男人家”指男人，与“家里的事也该管”的语境相符。"}, {"text": "客人", "is_correct": false, "explanation": "语义：“客人”不该管主人家里的事，句意矛盾。"}], "explanations": {"小狗": "语义：“小狗”是动物，不会“管家里的事”，句意不通。", "外国人": "语义：“外国人”与“家里的事，也该管一管”的语境不符，句意不通。", "男人家": "正确：“男人家”指男人，与“家里的事也该管”的语境相符。", "客人": "语义：“客人”不该管主人家里的事，句意矛盾。"}, "sentence_index": 6, "correct_answer": "男人家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑是个男人家，开机很快。", "explanation": "「男人家」只指人，不能用于物品。这里应该用〈机器〉。"}, {"text": "这个男人家才三岁，还不会自己穿鞋。", "explanation": "「男人家」指成年男性，不指幼儿。这里应该用〈男孩〉。"}, {"text": "我家养的那只狗是个男人家，整天围着我转。", "explanation": "「男人家」只指人，不能用于动物。这里应该用〈公狗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里有三只男人家在外面打工。", "corrected_sentence": "村里有三个男人家在外面打工。", "error_description": "量词错误：“男人家”指人，量词应用“个”，不能用“只”（“只”多用于小动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "街上走着两条男人家，有说有笑。", "corrected_sentence": "街上走着两个男人家，有说有笑。", "error_description": "量词错误：“男人家”指人，量词应用“个”，“条”用于细长的东西，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43d37193-fd53-40cf-a11e-80c8a8f4dd09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
