INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93665, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "目的地是你要去的那个地方。", "primary_collocate": null, "pronunciation": "mù dì dì", "ipa": "mu˥˩ ti˥˩ ti˥˩", "syllable_count": 3, "sentences": [{"text": "我们快到目的地了。", "target_word": "目的地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的目的地是哪里？", "target_word": "目的地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条路很长，目的地还很远。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐了三个小时，我们到了目的地。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉司机你的目的地。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的目的地是海边的小城。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不知道朋友的目的地在哪儿。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了目的地，我给你打电话。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个目的地我去过两次。", "target_word": "目的地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地图上有我们的目的地。", "target_word": "目的地", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "要去的那个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781e042f-01c8-4179-94a7-75f6a8a36a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93665, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目的地", "is_correct": true, "explanation": "目的地是要去的地方，“快到……了”后面接地点，句意成立。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“快到……了”后要接地点，“作业”不是地点。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“快到”后要接地点，“衣服”不是可以到达的地方。"}, {"text": "感觉", "is_correct": false, "explanation": "语义：感觉是心理状态，不能是要到达的地方。"}], "explanations": {"目的地": "目的地是要去的地方，“快到……了”后面接地点，句意成立。", "作业": "语义：“快到……了”后要接地点，“作业”不是地点。", "衣服": "搭配：“快到”后要接地点，“衣服”不是可以到达的地方。", "感觉": "语义：感觉是心理状态，不能是要到达的地方。"}, "sentence_index": 0, "correct_answer": "目的地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们出来旅游的目的地是放松。", "explanation": "这里应该用〈目的〉。目的地指要到达的地方，不能表示做事的目的。"}, {"text": "我的目的地是考上一所好大学。", "explanation": "这里应该用〈目标〉。目的地是具体的地点，不能指抽象的努力方向。"}, {"text": "我们找到了一条目的地。", "explanation": "这里应该用〈个〉。目的地是地点，量词不用“条”，“条”多用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93665, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目的地", "is_correct": true, "explanation": "目的地是朋友要去的地方，可以问“在哪儿”。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是时间，不是地点，不能问“在哪儿”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是地点，不能问“在哪儿”。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不能问“在哪儿”，搭配不成立。"}], "explanations": {"目的地": "目的地是朋友要去的地方，可以问“在哪儿”。", "生日": "语义：生日是时间，不是地点，不能问“在哪儿”。", "年龄": "语义：年龄不是地点，不能问“在哪儿”。", "心情": "搭配：“心情”不能问“在哪儿”，搭配不成立。"}, "sentence_index": 6, "correct_answer": "目的地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在地图上找到了一颗目的地。", "explanation": "这里应该用〈个〉。目的地是地点，量词用“个”；“颗”用于圆粒状的东西，不能用于目的地。"}, {"text": "我们来这里的目的地是学习汉语。", "explanation": "这里应该用〈目的〉。目的地不能表示做事的目的。"}, {"text": "我找到了一本目的地。", "explanation": "这里应该用〈个〉。“本”用于书籍，目的地不能用“本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车快在目的地了，大家准备下车吧。", "corrected_sentence": "车快到目的地了，大家准备下车吧。", "error_description": "动词错误：表示“快要到达”要用“到”，“在”表示所在，不能说“快在目的地了”，应说“快到目的地了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去过很多目的地们。", "corrected_sentence": "我们去过很多目的地。", "error_description": "词缀错误：“们”只用于指人的名词，“目的地”后不能加“们”，应说“很多目的地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
