INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旅程所要到达的地方。", "primary_collocate": null, "pronunciation": "mù dì dì", "ipa": "mu˥˩ ti˥˩ ti˥˩", "syllable_count": 3, "sentences": [{"text": "这次旅行的目的地是北京。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车的目的地是上海。", "target_word": "目的地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机准时到达了目的地。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路线的目的地是一座古城。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅客们带着行李走向目的地。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船要开三天才能到目的地。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆公共汽车的目的地是机场。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们选了一个很美的旅行目的地。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到目的地以前，我们要换两次车。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这趟旅程的目的地在山里。", "target_word": "目的地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "旅程要到达的终点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781e042f-01c8-4179-94a7-75f6a8a36a9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目的地", "is_correct": true, "explanation": "目的地是旅行要到达的地方，句意成立。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是物品，不是旅行要到达的地方。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能说“是北京”，搭配不成立。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是地点，不能说“是北京”。"}], "explanations": {"目的地": "目的地是旅行要到达的地方，句意成立。", "行李": "语义：行李是物品，不是旅行要到达的地方。", "天气": "搭配：“天气”不能说“是北京”，搭配不成立。", "价格": "语义：价格不是地点，不能说“是北京”。"}, "sentence_index": 0, "correct_answer": "目的地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们这次旅行的目的地是放松心情。", "explanation": "这里应该用〈目的〉。目的地指要到达的地方，不能表示旅行的目的。"}, {"text": "这三张目的地很有名。", "explanation": "这里应该用〈个〉。目的地是地点，“张”用于平面的东西，不能用于目的地。"}, {"text": "我找到了一棵目的地。", "explanation": "这里应该用〈个〉。“棵”用于树木，目的地不能用“棵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目的地", "is_correct": true, "explanation": "目的地是公共汽车要开往的地方，句意成立。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机是人，不是车要到达的地点。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位是车内的位置，不能说“是机场”。"}, {"text": "票价", "is_correct": false, "explanation": "搭配：“票价”不能说“是机场”，搭配不成立。"}], "explanations": {"目的地": "目的地是公共汽车要开往的地方，句意成立。", "司机": "语义：司机是人，不是车要到达的地点。", "座位": "语义：座位是车内的位置，不能说“是机场”。", "票价": "搭配：“票价”不能说“是机场”，搭配不成立。"}, "sentence_index": 6, "correct_answer": "目的地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的目的地是拿到冠军。", "explanation": "这里应该用〈目标〉。目的地是具体的地点，不能指要达成的结果。"}, {"text": "我们找到了一颗目的地。", "explanation": "这里应该用〈个〉。目的地是地点，量词用“个”；“颗”用于圆粒状的东西，不能用于目的地。"}, {"text": "这一支目的地很有名。", "explanation": "这里应该用〈个〉。“支”用于细长的东西，不用于地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条目的地离我们很远。", "corrected_sentence": "这个目的地离我们很远。", "error_description": "量词错误：地点应用“个”，不能用“条”，“这条目的地”应改为“这个目的地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个旅行团安排了三个目的地们。", "corrected_sentence": "这个旅行团安排了三个目的地。", "error_description": "词缀错误：“们”只加在指人的名词后，“目的地”后不能加“们”，应说“三个目的地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35f0903d-6e0d-4acf-b5c2-612a45e42e94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
