INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93667, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "硬件是电脑里能摸得到的东西，比如屏幕。", "primary_collocate": null, "pronunciation": "yìng jiàn", "ipa": "iŋ⁵¹ tɕjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "屏幕是电脑的硬件。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑坏了，是硬件的问题。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "键盘和屏幕都是硬件。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑的硬件很好，用着很快。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了新硬件，旧的不要了。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "硬件是摸得到的，软件摸不到。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想换一下电脑的硬件。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在店里看各种电脑硬件。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些硬件都是新买的。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的硬件越来越好了。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "硬件设备", "label": "复合"}], "register": "中性", "sense_fingerprint": "电脑里摸得到的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbbcbc0-280a-4f0c-a3f1-46de88612a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93667, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "硬件", "is_correct": true, "explanation": "正确。硬件指电脑里摸得到的部件，屏幕正是其中之一。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏属于软件内容，屏幕不是游戏，不能说“屏幕是电脑的游戏”。"}, {"text": "程序", "is_correct": false, "explanation": "语义：程序是一组指令，摸不到，屏幕不是程序。"}, {"text": "系统", "is_correct": false, "explanation": "搭配：“系统”指整套体系，屏幕只是其中一个部件，“是……的系统”不搭配。"}], "explanations": {"硬件": "正确。硬件指电脑里摸得到的部件，屏幕正是其中之一。", "游戏": "语义：游戏属于软件内容，屏幕不是游戏，不能说“屏幕是电脑的游戏”。", "程序": "语义：程序是一组指令，摸不到，屏幕不是程序。", "系统": "搭配：“系统”指整套体系，屏幕只是其中一个部件，“是……的系统”不搭配。"}, "sentence_index": 0, "correct_answer": "硬件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我写了一个新硬件。", "explanation": "这里应该用〈程序〉。“写”的对象是程序等软件，硬件是可以摸得到的部件，不能“写”。"}, {"text": "我经常上硬件看新闻。", "explanation": "这里应该用〈网站〉。“上”后面接网站、网页这类可以访问的对象，硬件不能“上”。"}, {"text": "他下载了一个新硬件。", "explanation": "这里应该用〈应用〉。“下载”的是应用或文件，硬件是要买、要装的设备，不能下载。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93667, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "硬件", "is_correct": true, "explanation": "正确。“换一下电脑的硬件”指更换电脑里的物理部件。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格是人的特点，电脑没有性格，不能“换”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述人的体形，不能用来说电脑。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄属于人或生物，电脑不能“换年龄”。"}], "explanations": {"硬件": "正确。“换一下电脑的硬件”指更换电脑里的物理部件。", "性格": "语义：性格是人的特点，电脑没有性格，不能“换”。", "身材": "体貌：身材描述人的体形，不能用来说电脑。", "年龄": "语义：年龄属于人或生物，电脑不能“换年龄”。"}, "sentence_index": 6, "correct_answer": "硬件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把硬件保存在U盘里。", "explanation": "这里应该用〈文件〉。“保存”的对象是文件或数据，硬件是设备，不能存进U盘。"}, {"text": "他每天听硬件。", "explanation": "这里应该用〈音乐〉。“听”的对象是声音或音乐，硬件不能“听”。"}, {"text": "我昨天打了硬件。", "explanation": "这里应该用〈游戏〉。“打”后面接游戏、球等，硬件是设备，不能“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93667, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司买了一只新硬件。", "corrected_sentence": "我们公司买了一套新硬件。", "error_description": "量词错误：“硬件”常与“套”或“台”搭配，不与“只”搭配，应把“一只新硬件”改为“一套新硬件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93667, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把旧硬件送对了朋友。", "corrected_sentence": "他把旧硬件送给了朋友。", "error_description": "介词错误：表示“送”的接受者要用“给”，不能用“对”，应把“送对了朋友”改为“送给了朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
