INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93668, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "计算机系统中的物理设备，与软件相对。", "primary_collocate": null, "pronunciation": "yìng jiàn", "ipa": "iŋ⁵¹ tɕjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "这个系统需要新的硬件。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件没问题，是硬件坏了。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每年花很多钱买硬件。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的电脑硬件太旧了。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会修电脑硬件，也会写软件。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "硬件和软件要一起用。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店专门卖电脑硬件。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "硬件不好，软件再好也很慢。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了电脑硬件的作用。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务器的硬件要定期检查。", "target_word": "硬件", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "硬件设备", "label": "复合"}], "register": "中性", "sense_fingerprint": "计算机系统的物理设备，与软件相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbbcbc0-280a-4f0c-a3f1-46de88612a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "硬件", "is_correct": true, "explanation": "正确。“这个系统需要新的硬件”指系统需要更换物理设备。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然状况，系统不能“需要新的天气”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格属于人，系统没有性格，不能“需要新的性格”。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”描述人或动物的身体状况，与“系统需要新的”搭配不当。"}], "explanations": {"硬件": "正确。“这个系统需要新的硬件”指系统需要更换物理设备。", "天气": "语义：天气是自然状况，系统不能“需要新的天气”。", "性格": "语义：性格属于人，系统没有性格，不能“需要新的性格”。", "体温": "搭配：“体温”描述人或动物的身体状况，与“系统需要新的”搭配不当。"}, "sentence_index": 0, "correct_answer": "硬件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他删除了旧硬件。", "explanation": "这里应该用〈文件〉。“删除”的对象是文件或数据，硬件是实物，不能删除。"}, {"text": "他每天听硬件。", "explanation": "这里应该用〈音乐〉。“听”的对象是声音或音乐，硬件不能“听”。"}, {"text": "他经常上硬件看新闻。", "explanation": "这里应该用〈网站〉。“上”后面接网站、网页，硬件不能“上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "硬件", "is_correct": true, "explanation": "正确。“这家店专门卖电脑硬件”指卖电脑的物理部件。"}, {"text": "食品", "is_correct": false, "explanation": "搭配：“电脑”不能修饰“食品”，“电脑食品”不成立。"}, {"text": "花草", "is_correct": false, "explanation": "语义：花草是植物，不是电脑的一类，店里不会专门卖“电脑花草”。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“电脑”只修饰与计算机有关的事物，不能说“电脑饮料”。"}], "explanations": {"硬件": "正确。“这家店专门卖电脑硬件”指卖电脑的物理部件。", "食品": "搭配：“电脑”不能修饰“食品”，“电脑食品”不成立。", "花草": "语义：花草是植物，不是电脑的一类，店里不会专门卖“电脑花草”。", "饮料": "搭配：“电脑”只修饰与计算机有关的事物，不能说“电脑饮料”。"}, "sentence_index": 6, "correct_answer": "硬件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天给妈妈打硬件。", "explanation": "这里应该用〈电话〉。“打”的对象是电话，硬件是设备，不能“打”。"}, {"text": "他晚上写硬件。", "explanation": "这里应该用〈作业〉。“写”的对象是作业或文章，硬件不能“写”。"}, {"text": "他会唱很多硬件。", "explanation": "这里应该用〈歌〉。“唱”的对象是歌，硬件不能“唱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
