INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93670, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对经济体制和经营管理方式所进行的变革。", "primary_collocate": null, "pronunciation": "jīng jì gǎi gé", "ipa": "tɕiŋ˥ tɕi˥˩ kaɪ˨˩˦ kɤ˧˥", "syllable_count": 4, "sentences": [{"text": "经济改革需要时间。", "target_word": "经济改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府公布了新的经济改革计划。", "target_word": "经济改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次经济改革主要改变管理方式。", "target_word": "经济改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济改革让企业有了更多自主权。", "target_word": "经济改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家谈了经济改革的方向。", "target_word": "经济改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济改革中也会遇到困难。", "target_word": "经济改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一篇关于经济改革的文章。", "target_word": "经济改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的经济改革先开始了。", "target_word": "经济改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济改革能提高工作效率。", "target_word": "经济改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都关心经济改革的结果。", "target_word": "经济改革", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "对经济体制和经营管理方式的变革", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f40a4c9d-1fd0-4de3-94d1-c63055ba03a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经济改革", "is_correct": true, "explanation": "经济改革：对体制的变革需要长期推进，所以需要时间。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景物，不是需要时间完成的过程。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯是日用器具，不需要时间去完成。"}, {"text": "纸巾", "is_correct": false, "explanation": "搭配：“需要时间”搭配过程或事情，不能说纸巾需要时间。"}], "explanations": {"经济改革": "经济改革：对体制的变革需要长期推进，所以需要时间。", "天空": "语义：天空是自然景物，不是需要时间完成的过程。", "水杯": "语义：水杯是日用器具，不需要时间去完成。", "纸巾": "搭配：“需要时间”搭配过程或事情，不能说纸巾需要时间。"}, "sentence_index": 0, "correct_answer": "经济改革"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的经济改革很好吃。", "explanation": "这里应该用〈饭菜〉。“好吃”形容食物，“经济改革”是抽象的变革，不能说“很好吃”。"}, {"text": "旧房子需要经济改革。", "explanation": "这里应该用〈改造〉。改革针对体制，房屋的翻新要用改造。"}, {"text": "这家企业的经济改革很快就卖掉了。", "explanation": "这里应该用〈产品〉。卖掉的是实物商品，经济改革是体制层面的变革，不能被卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0eb0521e-f62e-46f3-9f9f-cc04980c6a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济改革", "is_correct": true, "explanation": "经济改革：是可以写的话题，符合“关于……的文章”。"}, {"text": "时候", "is_correct": false, "explanation": "搭配：时候是时间词，不能直接作为文章的话题。"}, {"text": "对面", "is_correct": false, "explanation": "搭配：对面是方位词，不能直接作为文章的话题。"}, {"text": "之后", "is_correct": false, "explanation": "语义：之后表示时间先后，不指可以写文章的具体事物。"}], "explanations": {"经济改革": "经济改革：是可以写的话题，符合“关于……的文章”。", "时候": "搭配：时候是时间词，不能直接作为文章的话题。", "对面": "搭配：对面是方位词，不能直接作为文章的话题。", "之后": "语义：之后表示时间先后，不指可以写文章的具体事物。"}, "sentence_index": 6, "correct_answer": "经济改革"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们正在玩经济改革。", "explanation": "这里应该用〈游戏〉。玩的是游戏，经济改革是体制变革，不是可以玩的活动。"}, {"text": "他把我的经济改革弄丢了。", "explanation": "这里应该用〈钱包〉。钱包是实物，可以丢失；经济改革是抽象的变革，不能丢。"}, {"text": "这条河的经济改革很清澈。", "explanation": "这里应该用〈河水〉。清澈形容水质，经济改革不是水，不能用清澈来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0eb0521e-f62e-46f3-9f9f-cc04980c6a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "企业需要一条经济改革。", "corrected_sentence": "企业需要一项经济改革。", "error_description": "“一条经济改革”的量词错误：“条”用于细长的物体，改革应用量词“项”，正确形式为“一项经济改革”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0eb0521e-f62e-46f3-9f9f-cc04980c6a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国家推开了经济改革。", "corrected_sentence": "国家推行了经济改革。", "error_description": "动词搭配错误：“推开”指用手把门、东西等推向一边，不能搭配“经济改革”；实施改革应说“推行”，正确形式为“推行了经济改革”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0eb0521e-f62e-46f3-9f9f-cc04980c6a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
