INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93672, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对计算机网络的结构、设备和连接方式进行规划设计。", "primary_collocate": null, "pronunciation": "wǎng luò shè jì", "ipa": "waŋ˨˩˦ luo˥˩ ʂɤ˥˩ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "网络设计要先考虑设备和连接方式。", "target_word": "网络设计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司新楼的网络设计由工程师完成。", "target_word": "网络设计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网络设计用了两台交换机。", "target_word": "网络设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在课上讨论了医院的网络设计。", "target_word": "网络设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作是为银行做网络设计。", "target_word": "网络设计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的网络设计要保证每台电脑都能上网。", "target_word": "网络设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络设计出了问题，整栋楼都不能上网。", "target_word": "网络设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在修改机房的网络设计。", "target_word": "网络设计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份网络设计包括服务器和网线的位置。", "target_word": "网络设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学学的是计算机，现在做网络设计。", "target_word": "网络设计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套网络设计", "label": "量词"}, {"form": "一个网络设计", "label": "量词"}, {"form": "网络设计师", "label": "复合词"}], "register": "中性", "sense_fingerprint": "对计算机网络的结构、设备和连接方式的规划工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7d51479-38c9-402d-8933-0c454435b4a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网络设计", "is_correct": true, "explanation": "正确：“网络设计”指规划设备和连接方式的工作，符合句子。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”不涉及设备和连接方式，句子说的是网络规划。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”与设备和连接方式无关，句子的主语应是网络规划。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“感冒”不需要“先考虑设备和连接方式”，二者不搭配。"}], "explanations": {"网络设计": "正确：“网络设计”指规划设备和连接方式的工作，符合句子。", "午饭": "语义：“午饭”不涉及设备和连接方式，句子说的是网络规划。", "生日": "语义：“生日”与设备和连接方式无关，句子的主语应是网络规划。", "感冒": "搭配：“感冒”不需要“先考虑设备和连接方式”，二者不搭配。"}, "sentence_index": 0, "correct_answer": "网络设计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每周都做网络设计，修好坏掉的交换机。", "explanation": "这里应该用〈网络维修〉。“网络设计”是规划连接方式，“修好坏掉的交换机”属于维修，要说“网络维修”。"}, {"text": "这首歌的网络设计很动听。", "explanation": "这里应该用〈旋律〉。“网络设计”指网络的规划，不能用来形容歌曲好不好听。"}, {"text": "这台电脑装了网络设计。", "explanation": "这里应该用〈网卡〉。装在电脑上的是网卡等硬件，规划方案不能被“装”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网络设计", "is_correct": true, "explanation": "正确：“网络设计”出问题会导致整栋楼不能上网，符合句意。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“饭菜”出问题不会导致整栋楼不能上网，与句意不符。"}, {"text": "教材", "is_correct": false, "explanation": "语义：“教材”与上网和整栋楼的网络状况无关。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“窗帘”出问题一般说“坏了”，不会导致“不能上网”。"}], "explanations": {"网络设计": "正确：“网络设计”出问题会导致整栋楼不能上网，符合句意。", "饭菜": "语义：“饭菜”出问题不会导致整栋楼不能上网，与句意不符。", "教材": "语义：“教材”与上网和整栋楼的网络状况无关。", "窗帘": "搭配：“窗帘”出问题一般说“坏了”，不会导致“不能上网”。"}, "sentence_index": 6, "correct_answer": "网络设计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们公司的网络设计，每天都在机房里工作。", "explanation": "这里应该用〈网络设计师〉。“网络设计”指规划工作的内容，不指做这项工作的人，人要说“网络设计师”。"}, {"text": "他躺在网络设计上睡着了。", "explanation": "这里应该用〈沙发〉。“网络设计”是规划方案，不能躺在上面，要说躺在沙发上。"}, {"text": "我的网络设计没电了。", "explanation": "这里应该用〈手机〉。“没电”说的是有电池的设备，方案不会没电。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们修改了一把网络设计。", "corrected_sentence": "我们修改了一套网络设计。", "error_description": "量词错误：“网络设计”应用量词“套”，不能用“把”。应说“一套网络设计”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的工作是为医院挖网络设计。", "corrected_sentence": "他的工作是为医院做网络设计。", "error_description": "动词错误：“网络设计”是规划工作，应说“做网络设计”，不能说“挖网络设计”（“挖”用于挖掘实物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
