INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93674, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "县的名称。", "primary_collocate": null, "pronunciation": "xiàn míng", "ipa": "ɕjɛn⁵¹ miŋ³⁵", "syllable_count": 2, "sentences": [{"text": "县名要写在表格第一行。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县名以前不叫这个。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他背出了全省所有的县名。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个县名里有“水”字？", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县名改了以后，路牌也换了。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上每个县名都用小字写。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县名我第一次听说。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名表上要填县名和地址。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们比赛看谁记的县名多。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县名是用人名起的。", "target_word": "县名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "县的名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbbcbc0-280a-4f0c-a3f1-46de88612a3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93674, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "县名", "is_correct": true, "explanation": "正确。县名指县的名称，读作 xiàn míng。"}, {"text": "县民", "is_correct": false, "explanation": "县民（xiàn mín）的第二个音节与 míng 只差韵尾（n 与 ng），意思是县里的居民。"}, {"text": "巷名", "is_correct": false, "explanation": "巷名（xiàng míng）的第一个音节与 xiàn 只差韵母（ang 与 an），意思是巷子的名字。"}, {"text": "鲜明", "is_correct": false, "explanation": "鲜明（xiān míng）的第一个音节与 xiàn 声调不同（第一声与第四声），意思是清楚、明显。"}, {"text": "贤明", "is_correct": false, "explanation": "贤明（xián míng）的第一个音节与 xiàn 声调不同（第二声与第四声），意思是贤明、有智慧。"}], "explanations": {"县名": "正确。县名指县的名称，读作 xiàn míng。", "县民": "县民（xiàn mín）的第二个音节与 míng 只差韵尾（n 与 ng），意思是县里的居民。", "巷名": "巷名（xiàng míng）的第一个音节与 xiàn 只差韵母（ang 与 an），意思是巷子的名字。", "鲜明": "鲜明（xiān míng）的第一个音节与 xiàn 声调不同（第一声与第四声），意思是清楚、明显。", "贤明": "贤明（xián míng）的第一个音节与 xiàn 声调不同（第二声与第四声），意思是贤明、有智慧。"}, "sentence_index": null, "correct_answer": "县名"}, "level_3": {"options": [{"text": "县名", "is_correct": true, "explanation": "正确。县名是县的名称，可以写在表格的第一行。"}, {"text": "雷声", "is_correct": false, "explanation": "语义：雷声是一种声音，不是需要登记的名称，与“写在表格第一行”不合。"}, {"text": "肉汤", "is_correct": false, "explanation": "语义：肉汤是食物，不是需要登记的名称，与“写在表格第一行”不合。"}, {"text": "名讳", "is_correct": false, "explanation": "语域：“名讳”是敬辞，只用于称呼他人的名字，不能出现在表格上。"}], "explanations": {"县名": "正确。县名是县的名称，可以写在表格的第一行。", "雷声": "语义：雷声是一种声音，不是需要登记的名称，与“写在表格第一行”不合。", "肉汤": "语义：肉汤是食物，不是需要登记的名称，与“写在表格第一行”不合。", "名讳": "语域：“名讳”是敬辞，只用于称呼他人的名字，不能出现在表格上。"}, "sentence_index": 0, "correct_answer": "县名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的县名是李明。", "explanation": "这里应该用〈名字〉。县名只指县的名称，人的名字要说“名字”。"}, {"text": "这个县名很大，人口很多。", "explanation": "这里应该用〈县〉。县名只是名称，不能说“很大、人口很多”；说的是县本身。"}, {"text": "这个湖的县名很有意思。", "explanation": "这里应该用〈名字〉。湖不是县，县名只指县的名称，湖的名称要说“名字”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93674, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "县名", "is_correct": true, "explanation": "正确。县名指县的名称，读作 xiàn míng。"}, {"text": "线民", "is_correct": false, "explanation": "线民（xiàn mín）的第二个音节与 míng 只差韵尾（n 与 ng），意思是提供消息的人。"}, {"text": "显明", "is_correct": false, "explanation": "显明（xiǎn míng）的第一个音节与 xiàn 声调不同（第三声与第四声），意思是明显。"}, {"text": "贤名", "is_correct": false, "explanation": "贤名（xián míng）的第一个音节与 xiàn 声调不同（第二声与第四声），意思是好名声。"}], "explanations": {"县名": "正确。县名指县的名称，读作 xiàn míng。", "线民": "线民（xiàn mín）的第二个音节与 míng 只差韵尾（n 与 ng），意思是提供消息的人。", "显明": "显明（xiǎn míng）的第一个音节与 xiàn 声调不同（第三声与第四声），意思是明显。", "贤名": "贤名（xián míng）的第一个音节与 xiàn 声调不同（第二声与第四声），意思是好名声。"}, "sentence_index": null, "correct_answer": "县名"}, "level_3": {"options": [{"text": "县名", "is_correct": true, "explanation": "正确。“这个……我第一次听说”说的是一个县的名字。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是人人都接触的东西，不会“第一次听说”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是眼睛看到的景象，不是可以“听说”的对象。"}, {"text": "芳名", "is_correct": false, "explanation": "语域：“芳名”是敬辞，用于称呼他人的名字，不能指地名。"}], "explanations": {"县名": "正确。“这个……我第一次听说”说的是一个县的名字。", "空气": "语义：空气是人人都接触的东西，不会“第一次听说”。", "天空": "语义：天空是眼睛看到的景象，不是可以“听说”的对象。", "芳名": "语域：“芳名”是敬辞，用于称呼他人的名字，不能指地名。"}, "sentence_index": 6, "correct_answer": "县名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在这个县名教书。", "explanation": "这里应该用〈县〉。“在……教书”要接地点，县名只是名称，不能表示地点。"}, {"text": "我把这个县名借给了同学。", "explanation": "这里应该用〈书〉。“借”的对象是书或物品，县名只是名称，不能借给别人。"}, {"text": "我喜欢吃这个县名。", "explanation": "这里应该用〈菜〉。“吃”的对象是食物，县名只是名称，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一下子记住了两只县名。", "corrected_sentence": "他一下子记住了两个县名。", "error_description": "量词错误：“县名”应搭配“个”，“只”用于动物，应把“两只县名”改为“两个县名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条县名很难写。", "corrected_sentence": "那个县名很难写。", "error_description": "量词错误：“县名”应搭配“个”，“条”用于长条形的东西，应把“那条县名”改为“那个县名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bad2dc1-9320-445e-a479-5da02e474c1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93676, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赏", "is_correct": true, "explanation": "“赏”与“罚”构成反义，《现代汉语词典》收录“赏罚”一词，指奖赏与处罚相对。"}, {"text": "送", "is_correct": false, "explanation": "“送”指把东西交给别人，与“处罚”这一义项没有对应关系。"}, {"text": "请", "is_correct": false, "explanation": "“请”指邀请或礼貌地要求，与“处罚”这一义项没有对应关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”指用笔记录文字，与“处罚”这一义项没有对应关系。"}], "correct_answer": "赏", "explanations": {"赏": "“赏”与“罚”构成反义，《现代汉语词典》收录“赏罚”一词，指奖赏与处罚相对。", "送": "“送”指把东西交给别人，与“处罚”这一义项没有对应关系。", "请": "“请”指邀请或礼貌地要求，与“处罚”这一义项没有对应关系。", "写": "“写”指用笔记录文字，与“处罚”这一义项没有对应关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93676, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赏", "is_correct": true, "explanation": "“赏”与“罚”构成反义，《现代汉语词典》收录“赏罚”一词，指奖赏与处罚相对。"}, {"text": "教", "is_correct": false, "explanation": "“教”指传授知识或技能，与“处罚”这一义项没有对应关系。"}, {"text": "买", "is_correct": false, "explanation": "“买”指花钱取得东西，与“处罚”这一义项没有对应关系。"}, {"text": "讲", "is_correct": false, "explanation": "“讲”指陈述或解释，与“处罚”这一义项没有对应关系。"}], "correct_answer": "赏", "explanations": {"赏": "“赏”与“罚”构成反义，《现代汉语词典》收录“赏罚”一词，指奖赏与处罚相对。", "教": "“教”指传授知识或技能，与“处罚”这一义项没有对应关系。", "买": "“买”指花钱取得东西，与“处罚”这一义项没有对应关系。", "讲": "“讲”指陈述或解释，与“处罚”这一义项没有对应关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93676, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对违反规定或犯错的人给予处分。", "primary_collocate": null, "pronunciation": "fá", "ipa": "fa˧˥", "syllable_count": 1, "sentences": [{"text": "他犯了错，老师罚他站在门外。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车闯红灯，警察会罚钱。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上班迟到，老板罚了他五十块钱。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明没写作业，老师罚他抄课文。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球员严重犯规，裁判罚他下场。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这里乱扔垃圾，要罚二百元。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟说了谎，爸爸罚过他一次。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁把杯子打破了，我就罚谁洗碗。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机停车超时，交警罚了他一百元。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时他违反规则，裁判罚了他两分钟。", "target_word": "罚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "罚了", "label": "体标"}, {"form": "罚过", "label": "体标"}, {"form": "罚款", "label": "复合"}, {"form": "处罚", "label": "复合"}, {"form": "罰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：对犯错或违规的人给予处分，如罚钱、罚站", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '996bd829-ae6b-4c7b-887c-9cabc20a2540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93676, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "罚", "is_correct": true, "explanation": "罚 fá：对犯错或违规的人给予处分，正是本义。"}, {"text": "发", "is_correct": false, "explanation": "发 fā（第一声）与 fá（第二声）声调不同，意思是发出、发送。"}, {"text": "法", "is_correct": false, "explanation": "法 fǎ（第三声）与 fá（第二声）声调不同，意思是法律、方法。"}, {"text": "华", "is_correct": false, "explanation": "华 huá 与 fá 声母不同（h 与 f），意思是中华、华丽。"}, {"text": "烦", "is_correct": false, "explanation": "烦 fán 比 fá 多一个鼻音韵尾 n，意思是烦恼、麻烦。"}], "explanations": {"罚": "罚 fá：对犯错或违规的人给予处分，正是本义。", "发": "发 fā（第一声）与 fá（第二声）声调不同，意思是发出、发送。", "法": "法 fǎ（第三声）与 fá（第二声）声调不同，意思是法律、方法。", "华": "华 huá 与 fá 声母不同（h 与 f），意思是中华、华丽。", "烦": "烦 fán 比 fá 多一个鼻音韵尾 n，意思是烦恼、麻烦。"}, "sentence_index": null, "correct_answer": "罚"}, "level_3": {"options": [{"text": "罚", "is_correct": true, "explanation": "“罚”指对犯错的人给予处分，与“他犯了错”“站在门外”的语境相符。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是褒奖，与“他犯了错”的语境相反。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是给好处，不能用来让人“站在门外”。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”要带受事和接受者（送他东西），不能直接接“站在门外”这样的动词短语。"}], "explanations": {"罚": "“罚”指对犯错的人给予处分，与“他犯了错”“站在门外”的语境相符。", "表扬": "语义：“表扬”是褒奖，与“他犯了错”的语境相反。", "奖励": "语义：“奖励”是给好处，不能用来让人“站在门外”。", "送": "配价：“送”要带受事和接受者（送他东西），不能直接接“站在门外”这样的动词短语。"}, "sentence_index": 0, "correct_answer": "罚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他罚了一个好主意，大家都夸他聪明。", "explanation": "这里应该用〈想出〉。罚是给予处分，不能与“主意”搭配；想出主意要说“想出”。"}, {"text": "他把电视机罚坏了，修了三天才好。", "explanation": "这里应该用〈弄〉。罚是给予处分，不表示损坏；把东西弄坏要说“弄坏”。"}, {"text": "她把答案罚错了，老师没有看出来。", "explanation": "这里应该用〈算〉。罚是给予处分，不表示计算；算错答案要说“算错”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93676, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "罚", "is_correct": true, "explanation": "罚 fá：对犯错或违规的人给予处分，正是本义。"}, {"text": "房", "is_correct": false, "explanation": "房 fáng 比 fá 多一个韵尾 ng，意思是房子。"}, {"text": "凡", "is_correct": false, "explanation": "凡 fán 比 fá 多一个鼻音韵尾 n，意思是凡是、所有。"}, {"text": "拔", "is_correct": false, "explanation": "拔 bá 与 fá 声母不同（b 与 f），意思是拔出。"}, {"text": "滑", "is_correct": false, "explanation": "滑 huá 与 fá 声母不同（h 与 f），意思是光滑。"}], "explanations": {"罚": "罚 fá：对犯错或违规的人给予处分，正是本义。", "房": "房 fáng 比 fá 多一个韵尾 ng，意思是房子。", "凡": "凡 fán 比 fá 多一个鼻音韵尾 n，意思是凡是、所有。", "拔": "拔 bá 与 fá 声母不同（b 与 f），意思是拔出。", "滑": "滑 huá 与 fá 声母不同（h 与 f），意思是光滑。"}, "sentence_index": null, "correct_answer": "罚"}, "level_3": {"options": [{"text": "罚", "is_correct": true, "explanation": "“罚”指对犯错的人给予处分，与“弟弟说了谎”的语境相符。"}, {"text": "赞扬", "is_correct": false, "explanation": "语义：“赞扬”是肯定和褒奖，与“说了谎”的语境矛盾。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”针对好的行为，不能用来回应“说了谎”。"}, {"text": "包", "is_correct": false, "explanation": "配价：“包”要接事物宾语，不能组成“包过他一次”这样的人与次数结构。"}], "explanations": {"罚": "“罚”指对犯错的人给予处分，与“弟弟说了谎”的语境相符。", "赞扬": "语义：“赞扬”是肯定和褒奖，与“说了谎”的语境矛盾。", "夸奖": "语义：“夸奖”针对好的行为，不能用来回应“说了谎”。", "包": "配价：“包”要接事物宾语，不能组成“包过他一次”这样的人与次数结构。"}, "sentence_index": 6, "correct_answer": "罚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他弄坏了邻居的自行车，要罚给邻居两百块。", "explanation": "这里应该用〈赔〉。罚是给予处分，不指赔偿他人的损失；赔偿要说“赔”。"}, {"text": "老师罚他一朵小红花，因为他帮助了同学。", "explanation": "这里应该用〈奖〉。罚是给予处分，帮助同学是好事，给小红花是奖励，不能用罚。"}, {"text": "他借了我的钱，说下个月罚给我。", "explanation": "这里应该用〈还〉。罚是给予处分，不表示归还欠款；把钱还回来要说“还”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没交作业，老师罚他了抄三遍。", "corrected_sentence": "他没交作业，老师罚了他抄三遍。", "error_description": "错误：“罚他了抄三遍”；正确：“罚了他抄三遍”。“了”应紧跟动词“罚”，不能放在宾语“他”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把玩具弄坏了，妈妈罚他过一次。", "corrected_sentence": "他把玩具弄坏了，妈妈罚过他一次。", "error_description": "错误：“罚他过一次”；正确：“罚过他一次”。“过”是动词的体标，应紧跟动词“罚”，不能放在宾语“他”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc1b492e-1358-4f92-96d1-6c6e30148d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
