INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93677, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "羊是身上有毛的动物，会咩咩叫。", "primary_collocate": null, "pronunciation": "yáng", "ipa": "jɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "草地上有很多羊。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民每天早上带羊去山上。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只羊一直在咩咩叫。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友喜欢看羊吃草。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在农场里见过羊。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只羊的毛又白又软。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "羊看见我就跑开了。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家养着二十多只羊。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "羊饿了，开始大声叫。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只羊跑进了院子。", "target_word": "羊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "头", "label": "量词"}, {"form": "群", "label": "量词"}, {"form": "山羊", "label": "复合词"}, {"form": "绵羊", "label": "复合词"}], "register": "中性", "sense_fingerprint": "身上有毛、会咩咩叫的常见动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e36a8cdb-5406-47d1-930e-7fc5be5a3f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
